INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('merville-franceville', 'Merville-Franceville', 'franceville|franceville-plage|merville-franceville-plage|baie de sallenelles|merville-franceville', 49.2849, -0.2118, 'France', 'sea', 350, 'guide', 'kitesurf', 'Works at all tides. Low tide gives flat water in the runnels (baïnes), good for beginners and freestyle, but it can mean a 30-minute walk back to the car. Waves break on the sandbanks on the ebb and at high tide. The beach is about 7 km long and up to 200 m wide, so some sand stays dry even at high tide.', 'Orne estuary and bird reserve to the west: riding is strictly prohibited in the last 300 m on the reserve side. Sandbanks and shallow water. Heavy crowding in summer, with dozens of kiters. The beach is shared with horse riders, hunters (Sept-Jan), shrimp and shellfish gatherers, swimmers and walkers. Cold water outside summer: in Feb 2020 two kiters were rescued and one had hypothermia.', 'Described as the only Calvados beach where kitesurfing is allowed all year. In summer (July-August) kiting is limited to a marked zone on the western side. The ornithological reserve at the western end is closed to all riding. From 16 June to 30 Sept, horses are allowed only 05:00-09:00 and after 20:00, between the Orne estuary and the marked kite zone.', 'Western end of the beach near the Orne estuary, next to the Kite-R Evolution school. Take Boulevard Wattier west to the wooden barrier that marks the kite zone. Parking at the barrier or on the access track is forbidden: park in the side streets and carry your gear along the dune path. Rig and launch at least 100 m away from the dune vegetation.', 'March-November. Riding is possible all year, with stricter rules in July-August.', 'seed', 'https://vvanat.fr/blog/franceville-normandie-kitesurf/|https://vvanat.fr/blog/association-francevillaise-de-kitesurf/|https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/franceville-normandie-france.html', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'merville-franceville' AND (SELECT status FROM spots WHERE id = 'merville-franceville') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'merville-franceville', 'NE', 'best', 'Summer afternoon thermal, typically 16-18 kn. A venturi effect from the Orne estuary can make it 10-15 kn stronger than forecast, though another guide calls the NE thermal weak, filling only on the western beaches.' WHERE (SELECT status FROM spots WHERE id = 'merville-franceville') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'merville-franceville', 'N', 'best', 'Onshore. Part of the NW-NE reference range.' WHERE (SELECT status FROM spots WHERE id = 'merville-franceville') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'merville-franceville', 'NW', 'best', 'Said to be slightly steadier and gives waves.' WHERE (SELECT status FROM spots WHERE id = 'merville-franceville') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'merville-franceville', 'W', 'ok', 'Listed among the usable onshore/side-shore directions.' WHERE (SELECT status FROM spots WHERE id = 'merville-franceville') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'merville-franceville', 'SW', 'marginal', 'Sources disagree. One guide calls SW the best direction (venturi in Sallenelles Bay, flat-water lagoons); another calls SE-SW offshore and gusty off the main beach. Experienced riders only, and only inside the bay.' WHERE (SELECT status FROM spots WHERE id = 'merville-franceville') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'merville-franceville', 'S', 'forbidden', 'Offshore. Described as unsuitable.' WHERE (SELECT status FROM spots WHERE id = 'merville-franceville') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'merville-franceville', 'SE', 'forbidden', 'Offshore, gusty and unpredictable.' WHERE (SELECT status FROM spots WHERE id = 'merville-franceville') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('wissant', 'Wissant', 'baie de wissant|wissant plage|wissant', 50.88726, 1.66131, 'France', 'sea', 315, 'guide', 'kitesurf|windsurf|wingfoil|sailing', 'Big tidal range, so conditions vary a lot with the tide. Waves are best at high tide, but the rip and shorebreak are also strongest then and the beach is very narrow by the promenade. SW wind with a falling tide is the classic setup. Tidal current can reach several knots and pushes riders downwind.', 'Strong tidal current (one guide cites up to 11 kn), so walking back upwind is common. Rip currents and shorebreak, worst at high tide. Narrow beach and seawall at high tide. Crowds on good days. Heavy shipping traffic in the Dover Strait offshore. Breakwater stakes at Sangatte on downwinders. Wartime ordnance occasionally found on the beach: a demining operation took place in Oct 2025.', 'South beach (Dune d''Aval) is reserved for water sports (kitesurf, land yacht) with swimming banned. Kite zoning is enforced more strictly in high season so beach users can share the space. Check the town hall''s current beach order (arrêté).', 'Windsurfers mostly use the left (west) part of the bay, kiters the right. At high tide everyone gathers in front of the reinforced seafront promenade, where the beach almost disappears. The south beach (Dune d''Aval) is reserved for water sports (kite, land yacht) and swimming is banned there. The beach is narrow, so take extra care when launching and landing. Gets crowded on good days.', 'Usable all year. Strongest, most reliable winds roughly September to December; March to September also cited for kitesurfing.', 'seed', 'https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/wissant-nord-pas-de-calais-france.html|https://vvanat.fr/blog/wissant-planche-a-voile/|https://www.plages.tv/chiens/liste-wissant-62179a|https://www.surf-report.com/surf-info/wissant-s1107.html', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'wissant' AND (SELECT status FROM spots WHERE id = 'wissant') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wissant', 'SW', 'best', 'Reference direction: side-shore from the left. The region''s best wave conditions, a top French high-wind spot. Works best on a falling tide. Allows a downwinder to Sangatte along the beaches and cliffs.' WHERE (SELECT status FROM spots WHERE id = 'wissant') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wissant', 'WSW', 'best', 'Side-on with waves. Similar to SW.' WHERE (SELECT status FROM spots WHERE id = 'wissant') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wissant', 'W', 'ok', 'Side-on to onshore. Usable.' WHERE (SELECT status FROM spots WHERE id = 'wissant') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wissant', 'NW', 'ok', 'Onshore, from the Channel. Regular wind but choppier water and harder exits through the shorebreak.' WHERE (SELECT status FROM spots WHERE id = 'wissant') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wissant', 'N', 'ok', 'Cited by surf-report as a good orientation. Side-on from the right.' WHERE (SELECT status FROM spots WHERE id = 'wissant') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wissant', 'NE', 'marginal', 'Side-shore to side-off from the right, gusty near Cap Blanc-Nez. Strong NE flow is common in the bay. Inferred from beach orientation, not confirmed by locals.' WHERE (SELECT status FROM spots WHERE id = 'wissant') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wissant', 'S', 'marginal', 'Side-offshore from the left. Gusty over the dunes and cliffs. Inferred from beach orientation.' WHERE (SELECT status FROM spots WHERE id = 'wissant') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wissant', 'SE', 'forbidden', 'Offshore: drifts riders out into the Channel and its shipping lanes.' WHERE (SELECT status FROM spots WHERE id = 'wissant') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wissant', 'ESE', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'wissant') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wissant', 'E', 'forbidden', 'Offshore to side-off. Gusty off the land.' WHERE (SELECT status FROM spots WHERE id = 'wissant') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('berck-sur-mer-grande-plage-terminus', 'Berck-sur-Mer (Grande Plage / Terminus)', 'berck-plage|berck terminus|berck la grande plage|berck-sur-mer (grande plage / terminus)', 50.424, 1.563, 'France', 'sea', 260, 'guide', 'kitesurf|windsurf|wingfoil', 'At low tide the sea goes out 2-3 km. Large tidal pools (baïnes) form, giving flat water for about 2.5 h around low tide, good for beginners. At high tide the water is 300-400 m from the seawall, with waves and shore break; intermediate+ in onshore wind. Currents are stronger on the falling tide. The rising tide fills in fast around the sandbanks and can cut people off.', 'Bouchot mussel beds north of Berck, uncovered at low tide and marked with a yellow buoy. Waves and currents at high tide, especially on the falling tide. Fast rising tide around the sandbanks between Baie d''Authie and the main beach. Shore break at high tide in onshore wind. Summer crowds near the town centre. Baie d''Authie to the south is a confined area for experienced riders only.', 'Inside the 300 m coastal strip, the mayor sets the rules and speed is limited to 5 kn. In July-August, kiting is not allowed in the swimming zones in front of the town centre. Guide sources say kiting is banned in Baie d''Authie (Les Sternes) to protect a seal colony; windsurfing is allowed there.', 'About 3 km of sandy beach from the Maritime Hospital (south) to Terminus beach (north). Main access is the Terminus car park (north, near the mussel beds) or the Saint-Nicolas car park. Northern beach is reached via Esplanade Parmentier past the Eole Club land-yacht base. In July-August, stay away from the swimming zones in front of the town centre.', 'Year-round (windy coast); water is very cold in winter.', 'seed', 'https://www.opale-kite.fr/lecole/le-spot/|https://theridery.com/pages/spot-de-kitesurf-berck-la-grande-plage|https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/les-sternes-berck-nord-pas-de-calais-france.html|https://park4night.com/en/place/274795', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'berck-sur-mer-grande-plage-terminus' AND (SELECT status FROM spots WHERE id = 'berck-sur-mer-grande-plage-terminus') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'berck-sur-mer-grande-plage-terminus', 'SW', 'best', 'Dominant wind and reference direction; side-onshore. Typical range is 12-28 kn with choppy water.' WHERE (SELECT status FROM spots WHERE id = 'berck-sur-mer-grande-plage-terminus') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'berck-sur-mer-grande-plage-terminus', 'WSW', 'best', 'Side-onshore. Works well across the whole beach.' WHERE (SELECT status FROM spots WHERE id = 'berck-sur-mer-grande-plage-terminus') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'berck-sur-mer-grande-plage-terminus', 'W', 'ok', 'Straight onshore. Rides well, but at high tide there is shore break and it is harder to get out (intermediate+).' WHERE (SELECT status FROM spots WHERE id = 'berck-sur-mer-grande-plage-terminus') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'berck-sur-mer-grande-plage-terminus', 'WNW', 'ok', 'Inside the usable S-to-N arc through W.' WHERE (SELECT status FROM spots WHERE id = 'berck-sur-mer-grande-plage-terminus') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'berck-sur-mer-grande-plage-terminus', 'NW', 'ok', 'Inside the usable arc. Check the Fort-Mahon anemometer for northerly components.' WHERE (SELECT status FROM spots WHERE id = 'berck-sur-mer-grande-plage-terminus') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'berck-sur-mer-grande-plage-terminus', 'SSW', 'ok', 'Inside the usable S-SW-to-N arc.' WHERE (SELECT status FROM spots WHERE id = 'berck-sur-mer-grande-plage-terminus') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'berck-sur-mer-grande-plage-terminus', 'S', 'marginal', 'Full south is slightly side-off. Guides advise avoiding it.' WHERE (SELECT status FROM spots WHERE id = 'berck-sur-mer-grande-plage-terminus') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'berck-sur-mer-grande-plage-terminus', 'N', 'marginal', 'Wind is disturbed by beachfront buildings. Guides advise avoiding it.' WHERE (SELECT status FROM spots WHERE id = 'berck-sur-mer-grande-plage-terminus') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'berck-sur-mer-grande-plage-terminus', 'NE', 'forbidden', 'Offshore. The local school moves to Wissant in NE wind.' WHERE (SELECT status FROM spots WHERE id = 'berck-sur-mer-grande-plage-terminus') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'berck-sur-mer-grande-plage-terminus', 'E', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'berck-sur-mer-grande-plage-terminus') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'berck-sur-mer-grande-plage-terminus', 'SE', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'berck-sur-mer-grande-plage-terminus') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('hardelot-plage', 'Hardelot-Plage', 'hardelot|neufchâtel-hardelot|plage d''hardelot|base de glisse georges pernoud|hardelot-plage', 50.6326, 1.5768, 'France', 'sea', 275, 'guide', 'kitesurf|windsurf|wingfoil|sailing', 'Large tidal range. At low tide the wide beach has baïnes (sandbar pools) with flat water over several km, the best conditions for beginners and freestyle. At high tide there is little beach, more waves and stronger current, so it gets more technical. Tidal current is moderate but real.', 'Tidal currents, especially around high tide. Shore break and reduced launch space at high tide. Busy in summer with swimmers, schools and sand yachts on the beach at low tide.', 'In season, watersports are banned in the lifeguarded swimming zone at Plage Centrale (about 600 m long). Ride outside it and beyond the 300 m coastal strip rules. Schools run supervised zones in peak season. Check the current municipal order (Neufchâtel-Hardelot) for exact zone limits.', 'Launch on the beach in front of the Base de glisse Georges Pernoud (seafront, Hardelot-Plage). Changing rooms and showers at the base. Schools (e.g. Kitezone) and sand-yacht clubs share the beach, so give them space and keep clear of beach users when launching or landing. The north beach (towards the Becque estuary and dunes) is also used for watersports.', 'All year. Most consistent wind from October to March. Summer works but the beach is crowded.', 'seed', 'https://www.kitezone.fr/lecole/spots|https://www.kiteloopers.com/en/spots/kite-spot-france-hardelot-plage-plage-dhardelot|https://lets-kite.com/fr/spots/1035/hardelot?saison=kitesurf|https://www.plages.tv/detail/plage-nord-hardelot-62152', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'hardelot-plage' AND (SELECT status FROM spots WHERE id = 'hardelot-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hardelot-plage', 'S', 'ok', 'Side-shore. Local school Kitezone lists the south sector as recommended.' WHERE (SELECT status FROM spots WHERE id = 'hardelot-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hardelot-plage', 'SSW', 'ok', 'Side to side-on. Works well.' WHERE (SELECT status FROM spots WHERE id = 'hardelot-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hardelot-plage', 'SW', 'best', 'Prevailing wind on this coast. Side-onshore. Reference direction.' WHERE (SELECT status FROM spots WHERE id = 'hardelot-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hardelot-plage', 'WSW', 'best', 'Side-onshore. Reference direction.' WHERE (SELECT status FROM spots WHERE id = 'hardelot-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hardelot-plage', 'W', 'best', 'Onshore to side-onshore. Choppier and wavier at high tide.' WHERE (SELECT status FROM spots WHERE id = 'hardelot-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hardelot-plage', 'WNW', 'ok', 'Side-onshore. Usable.' WHERE (SELECT status FROM spots WHERE id = 'hardelot-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hardelot-plage', 'NW', 'ok', 'Upper limit of the S to NW working range given by spot guides.' WHERE (SELECT status FROM spots WHERE id = 'hardelot-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hardelot-plage', 'NNW', 'ok', 'Usable depending on conditions.' WHERE (SELECT status FROM spots WHERE id = 'hardelot-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hardelot-plage', 'N', 'ok', 'Side-shore. Kitezone lists the north sector as recommended. Other guides say it depends on conditions.' WHERE (SELECT status FROM spots WHERE id = 'hardelot-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hardelot-plage', 'NNE', 'marginal', 'Side-offshore. Gusty. Avoid unless experienced.' WHERE (SELECT status FROM spots WHERE id = 'hardelot-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hardelot-plage', 'SSE', 'marginal', 'Side-offshore. Gusty over the dunes.' WHERE (SELECT status FROM spots WHERE id = 'hardelot-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hardelot-plage', 'NE', 'forbidden', 'Offshore. Do not ride.' WHERE (SELECT status FROM spots WHERE id = 'hardelot-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hardelot-plage', 'E', 'forbidden', 'Offshore. Do not ride.' WHERE (SELECT status FROM spots WHERE id = 'hardelot-plage') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('dunkerque-malo-les-bains', 'Dunkerque Malo-les-Bains', 'dunkerque - malo / dunes de flandre (dfc)|malo terminus|plage du terminus|parc du vent|dunkerque|dunkerque malo-les-bains', 51.05583, 2.42407, 'France', 'sea', 340, 'guide', 'kitesurf|windsurf|wingfoil|sailing', 'Very large tidal range (about 4.7-5.5 m springs). Low to mid tide works best: the beach dries far out, giving lots of space, and riders stand in the shallows. Avoid high tide, when the beach shrinks; wait at least 1 h after high water. Falling tide is often quoted as best. Tidal current about 1-2 kn.', '3 rocky breakwaters offshore and 1 marked wreck east of the base. Offshore drift in S-SW winds. Moderate tidal current. Busy beach (land yachts, bikes, joggers, dogs), crowded at weekends. The port of Dunkerque lies to the west.', 'Swimming is banned in the central kite/watersports zone along the Parc du Vent. The ends of the beach are bathing areas, with lifeguards in summer. From 1 July to 31 August, a prefectural order limits kiting to a zone 500 m west of the Terminus post, facing the Parc du Vent at the sailing base. The ''batteries'' zone to the east (blockhouses, Leffrinckoucke dyke) is open all year.', 'Launch from the beach in front of the Station Nautique des Dunes de Flandre / base Licorne (Digue Nicolas II), next to the Parc du Vent, about 10 m from the beach. Home of the Dunkerque Flysurfing Club (DFC), which runs lessons and a kite simulator. The kite/sailing zone is the central beach along the Parc du Vent, between the Pavois and Terminus lifeguard posts. Stay out of the bathing areas at each end. The beach is shared with land yachts, cyclists and joggers.', 'Rideable all year (March-November most cited). April-August is best, with a peak in June.', 'seed', 'https://lets-kite.com/fr/spots/1097/kitesurf/dunkerque-malo-dunes-de-flandre-dfc|https://www.plages.tv/detail/plage-du-terminus-malo-les-bains-dunkerque-59140|https://www.wannakitesurf.com/spot/Europe/France/Nord_Pas_de_Calais/Dunkerque/|https://vvanat.fr/blog/kitesurf-dunkerque-malo/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'dunkerque-malo-les-bains' AND (SELECT status FROM spots WHERE id = 'dunkerque-malo-les-bains') = 'seed';
