INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'dunkerque-malo-les-bains', 'NNW', 'best', 'Onshore to side-onshore. Flat to choppy water.' WHERE (SELECT status FROM spots WHERE id = 'dunkerque-malo-les-bains') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'dunkerque-malo-les-bains', 'N', 'best', 'Onshore to side-onshore.' WHERE (SELECT status FROM spots WHERE id = 'dunkerque-malo-les-bains') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'dunkerque-malo-les-bains', 'NNE', 'best', 'Side-onshore.' WHERE (SELECT status FROM spots WHERE id = 'dunkerque-malo-les-bains') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'dunkerque-malo-les-bains', 'NE', 'best', 'Side-onshore. One end of the reference NW-NE range.' WHERE (SELECT status FROM spots WHERE id = 'dunkerque-malo-les-bains') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'dunkerque-malo-les-bains', 'WNW', 'ok', 'Usable. Waves build as the wind turns west.' WHERE (SELECT status FROM spots WHERE id = 'dunkerque-malo-les-bains') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'dunkerque-malo-les-bains', 'W', 'ok', 'Common and usable. Side-shore with waves for experienced riders.' WHERE (SELECT status FROM spots WHERE id = 'dunkerque-malo-les-bains') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'dunkerque-malo-les-bains', 'ENE', 'marginal', 'Conditional: side-shore and gustier.' WHERE (SELECT status FROM spots WHERE id = 'dunkerque-malo-les-bains') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'dunkerque-malo-les-bains', 'E', 'marginal', 'Conditional: side-shore to side-off.' WHERE (SELECT status FROM spots WHERE id = 'dunkerque-malo-les-bains') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'dunkerque-malo-les-bains', 'WSW', 'marginal', 'Offshore risk. Experienced riders only, never alone.' WHERE (SELECT status FROM spots WHERE id = 'dunkerque-malo-les-bains') = 'seed';
