INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'dunkerque-malo-les-bains', 'SSE', 'forbidden', 'Offshore. Avoid.' WHERE (SELECT status FROM spots WHERE id = 'dunkerque-malo-les-bains') = 'seed';
