INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('le-crotoy', 'Le Crotoy', 'le crotoy plage nord|plage du marais|baie de somme - le crotoy|le crotoy', 50.22836, 1.61016, 'France', 'estuary', 225, 'guide', 'kitesurf|windsurf', 'Only rideable around high tide: about 2 h for small coefficients and up to 4 h for big ones. Best with coefficients 60-90. Below 60 the water does not come in far enough. Above 90 currents are strong and the beach floods quickly, leaving little room to launch. At low tide the sea goes out several hundred metres and you can end up stranded on the sand.', 'Strong estuary currents, especially when the tide turns; the falling tide pushes riders out to sea, mainly in side winds. Very shallow water with sandbanks and hidden obstacles. Muddy bottom in places. Fast-rising tide. Crowds on weekends. Birds and seals in the nearby reserve are easily disturbed.', 'No board or kite sports in front of the built-up seafront, where currents are violent. Kitesurfing is banned in the Baie de Somme National Nature Reserve: do not go past the yellow buoys marking the reserve entrance. The town recommends these sports in the bay only for riders who already have training.', 'Launch from the north end of Le Crotoy beach (plage nord / Plage du Marais, Chemin du Marais), where the official kite zone is. A ramp along the dike gives access. Parking near the beach, paid in some seasons. At high tide the launch strip is narrow: take turns when launching. Crowded on weekends and in summer.', '', 'seed', 'https://spots.universkite.fr/item/spot-de-kitesurf-le-crotoy/|https://theridery.com/pages/spot-kitesurf-baie-de-somme-le-crotoy|https://www.somme-tourisme.com/en/?p=17250|https://villeducrotoy.fr/sports/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'le-crotoy' AND (SELECT status FROM spots WHERE id = 'le-crotoy') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'le-crotoy', 'W', 'best', 'Reference direction for freeride/freestyle; most frequent wind at the spot.' WHERE (SELECT status FROM spots WHERE id = 'le-crotoy') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'le-crotoy', 'SW', 'ok', 'Onshore, roughly parallel to beach, small shore break.' WHERE (SELECT status FROM spots WHERE id = 'le-crotoy') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'le-crotoy', 'NW', 'ok', 'Side-shore (starboard tack), small wavelets for jumping.' WHERE (SELECT status FROM spots WHERE id = 'le-crotoy') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'le-crotoy', 'S', 'marginal', 'Listed as usable by some guides, but local school says wind is more irregular and currents stronger.' WHERE (SELECT status FROM spots WHERE id = 'le-crotoy') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'le-crotoy', 'N', 'marginal', 'Less advised: gusty/irregular wind and stronger currents (The Ridery).' WHERE (SELECT status FROM spots WHERE id = 'le-crotoy') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'le-crotoy', 'NE', 'forbidden', 'Offshore, strongly discouraged.' WHERE (SELECT status FROM spots WHERE id = 'le-crotoy') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'le-crotoy', 'E', 'forbidden', 'Offshore, strongly discouraged.' WHERE (SELECT status FROM spots WHERE id = 'le-crotoy') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'le-crotoy', 'SE', 'forbidden', 'Offshore, strongly discouraged.' WHERE (SELECT status FROM spots WHERE id = 'le-crotoy') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('cabourg', 'Cabourg', 'cap cabourg|plage de cabourg|cabourg', 49.296, -0.10488, 'France', 'sea', 345, 'guide', 'kitesurf', 'Large tidal range. At low tide, big sandbanks shelter a shallow, flat lagoon-like area that suits beginners. At high tide there is shorebreak and the groynes are a hazard.', 'Groynes (épis) along the beach, especially at high tide. Shorebreak at high tide. Shallow water and sandbanks at low tide. The Dives estuary and Port-Guillaume channel are next to Cap Cabourg. The beach gets crowded in summer.', 'The local school describes a ZRUK (Zone Réservée Uniquement au Kitesurf) open year-round, even in summer. A spot guide reports that kiting is banned during the summer holidays outside designated areas. Check the current municipal beach-marking order and the summer bathing zones before riding.', 'Main launch is on Cabourg beach at Cap Cabourg (Avenue Durand-Morimbau, east end of the town near the Dives estuary), where Le Menhir Normandie Kite is based (FFVL-affiliated, showers and changing rooms). Stay out of the school''s lesson area and keep clear of beginners.', '', 'seed', 'https://en.normandie-tourisme.fr/sports-and-leisure-activities/le-menhir-normandie-kite-kitesurfing-school/|https://www.manawa.com/fr-FR/activite/france/cabourg/kitesurf/cours-de-kitesurf-a-cabourg/2540|https://vvanat.fr/blog/cabourg-spot-de-kitesurf/|https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/cabourg-normandie-france.html', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'cabourg' AND (SELECT status FROM spots WHERE id = 'cabourg') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cabourg', 'W', 'best', 'Reference direction per the local school. W to NW winds bring waves.' WHERE (SELECT status FROM spots WHERE id = 'cabourg') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cabourg', 'WNW', 'best', 'Between W and NW, both of which the school lists as best. W–NW winds bring waves.' WHERE (SELECT status FROM spots WHERE id = 'cabourg') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cabourg', 'NW', 'best', 'Reference direction per the local school. W to NW winds bring waves.' WHERE (SELECT status FROM spots WHERE id = 'cabourg') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cabourg', 'WSW', 'ok', 'Listed as working by the local school. Side-shore from the left on a beach facing roughly NNW.' WHERE (SELECT status FROM spots WHERE id = 'cabourg') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cabourg', 'SW', 'marginal', 'The school lists SW as working, but it is side-off on this coastline. Gusty, and it pushes you away from the beach.' WHERE (SELECT status FROM spots WHERE id = 'cabourg') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cabourg', 'N', 'ok', 'Listed as working by the school (beach sessions in N wind). Close to onshore, so expect chop and shorebreak at high tide.' WHERE (SELECT status FROM spots WHERE id = 'cabourg') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cabourg', 'NE', 'ok', 'Fairly weak summer thermal. Mostly freeride conditions.' WHERE (SELECT status FROM spots WHERE id = 'cabourg') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cabourg', 'S', 'forbidden', 'Offshore. In S wind the school only runs boat-supported deep-water sessions.' WHERE (SELECT status FROM spots WHERE id = 'cabourg') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cabourg', 'SSE', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'cabourg') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cabourg', 'SSW', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'cabourg') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('siouville-hague', 'Siouville-Hague', 'siouville|plage de siouville-hague|anse de vauville (south end)|siouville-hague', 49.55849, -1.84012, 'France', 'sea', 280, 'guide', 'kitesurf|windsurf', 'Shorebreak can be very violent at low tide. Waves are softer at high tide and hollower at low tide; mid-tide is generally best for waves.', 'Powerful waves and heavy shorebreak, especially at low tide; experienced riders only. Rocky outcrop at the south end of the beach. Busy with surfers.', 'In season, all watersports (sailing, windsurf, surf, kitesurf, kayak...) are banned inside the supervised bathing area; lifeguard hours can shift with the tide, so check the flags and the municipal bylaw posted at the lifeguard post. Motorised watercraft banned on all beaches July 1 to Sept 15, 9am to 7pm.', 'Main access via Cale John-Hunter (beach slipway) in Siouville. Launch outside the supervised swimming zone and keep clear of surfers from the Cotentin Surf Club. The beach runs about 11 km north to Vauville, so there is room to spread out away from the village. No windsurf rental: the local club is surf-only, so bring your own gear.', '', 'seed', 'https://www.manche-tourism.com/outdoor/water-sport/sportive-practice/champion-windsurf/|https://en.normandie-tourisme.fr/sports-and-leisure-activities/plage-de-siouville-hague/|https://vvanat.fr/blog/cote-normande-kitesurf/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'siouville-hague' AND (SELECT status FROM spots WHERE id = 'siouville-hague') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'siouville-hague', 'SW', 'best', 'Reference direction: southwesterly lows give the best wave-sailing conditions. The cape and rocks at the south end partly shelter the beach from S/SW, so wind can be gusty near the south end.' WHERE (SELECT status FROM spots WHERE id = 'siouville-hague') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'siouville-hague', 'WSW', 'best', 'Cross-onshore on a west-facing beach, with good wave conditions.' WHERE (SELECT status FROM spots WHERE id = 'siouville-hague') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'siouville-hague', 'W', 'ok', 'Prevailing direction, onshore. Steady wind, good for jumping, but onshore with heavy shorebreak.' WHERE (SELECT status FROM spots WHERE id = 'siouville-hague') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'siouville-hague', 'S', 'marginal', 'Side-shore, but the cape and rocks to the south shelter the spot, so wind is weaker and gustier at Siouville than further along the bay.' WHERE (SELECT status FROM spots WHERE id = 'siouville-hague') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'siouville-hague', 'NE', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'siouville-hague') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'siouville-hague', 'ENE', 'forbidden', 'Offshore. Good surfing wind, not for kiting or windsurfing.' WHERE (SELECT status FROM spots WHERE id = 'siouville-hague') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'siouville-hague', 'E', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'siouville-hague') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'siouville-hague', 'ESE', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'siouville-hague') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'siouville-hague', 'SE', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'siouville-hague') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('saint-malo-plage-du-sillon', 'Saint-Malo – Plage du Sillon', 'le sillon|grande plage du sillon|saint-malo le sillon|rochebonne|saint-malo – plage du sillon', 48.6566, -2.0046, 'France', 'sea', 330, 'guide', 'kitesurf|windsurf|wingfoil', 'Tidal range up to about 12 m. Best from mid to low tide: wide beach and flat water at low tide. At high tide on big coefficients the beach becomes very narrow, the marked zone disappears, and there are currents and shore break along the seawall.', 'Rocky areas only visible at low tide. Rows of old wooden breakwater posts (brise-lames) on the beach. Currents and shore break near the seawall at high tide. Wind turbulence from the seawall and city ramparts. Crowded urban beach.', 'Kitesurf is officially allowed at Plage du Sillon and Plage de Rochebonne (Saint-Malo city beach data). In summer (about 15 June–15 Sept), kiting is reportedly banned in bathing zones and only allowed in a marked corridor about 300 m wide, kept 50 m from the seawall. July–August restrictions reportedly apply 09:00–19:00. Check the current municipal order.', 'Main launch in front of the Thermes Marins / surf school, in the middle of the Sillon. Park on the street, cross the seawall and walk down the stairs. Waves near Rochebonne at the east end. Share the beach with swimmers, surfers and walkers, and stay in the marked kite zone when there is one.', 'Mostly September to May. Best wind March–May and in winter (Dec–Jan). Summer has NE thermals but more restrictions.', 'seed', 'https://lets-kite.com/fr/spots/1050/kitesurf/le-sillon-saint-malo-cote-d-emeraude|https://www.kitesurfy.com/kitespot/saint-malo-le-sillon|https://www.data.gouv.fr/datasets/emplacement-et-reglementations-des-plages-de-saint-malo', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'saint-malo-plage-du-sillon' AND (SELECT status FROM spots WHERE id = 'saint-malo-plage-du-sillon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'saint-malo-plage-du-sillon', 'W', 'best', 'Reference direction, side-shore (port tack). Brings some waves.' WHERE (SELECT status FROM spots WHERE id = 'saint-malo-plage-du-sillon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'saint-malo-plage-du-sillon', 'WNW', 'best', 'Side-onshore.' WHERE (SELECT status FROM spots WHERE id = 'saint-malo-plage-du-sillon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'saint-malo-plage-du-sillon', 'NW', 'best', 'Side-onshore to onshore. Strong NW storms make it rough.' WHERE (SELECT status FROM spots WHERE id = 'saint-malo-plage-du-sillon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'saint-malo-plage-du-sillon', 'NNW', 'ok', 'Onshore.' WHERE (SELECT status FROM spots WHERE id = 'saint-malo-plage-du-sillon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'saint-malo-plage-du-sillon', 'N', 'best', 'Onshore to side-onshore.' WHERE (SELECT status FROM spots WHERE id = 'saint-malo-plage-du-sillon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'saint-malo-plage-du-sillon', 'NNE', 'ok', 'Side-onshore.' WHERE (SELECT status FROM spots WHERE id = 'saint-malo-plage-du-sillon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'saint-malo-plage-du-sillon', 'NE', 'best', 'Side-onshore. Summer NE thermal days.' WHERE (SELECT status FROM spots WHERE id = 'saint-malo-plage-du-sillon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'saint-malo-plage-du-sillon', 'WSW', 'ok', 'Usable, getting side-off. Wind disturbed by the seawall and ramparts.' WHERE (SELECT status FROM spots WHERE id = 'saint-malo-plage-du-sillon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'saint-malo-plage-du-sillon', 'SW', 'marginal', 'Conditional: side-offshore and gusty in the lee of the town.' WHERE (SELECT status FROM spots WHERE id = 'saint-malo-plage-du-sillon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'saint-malo-plage-du-sillon', 'ENE', 'marginal', 'Conditional.' WHERE (SELECT status FROM spots WHERE id = 'saint-malo-plage-du-sillon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'saint-malo-plage-du-sillon', 'E', 'forbidden', 'Offshore, does not work.' WHERE (SELECT status FROM spots WHERE id = 'saint-malo-plage-du-sillon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'saint-malo-plage-du-sillon', 'SE', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'saint-malo-plage-du-sillon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'saint-malo-plage-du-sillon', 'S', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'saint-malo-plage-du-sillon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'saint-malo-plage-du-sillon', 'SSW', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'saint-malo-plage-du-sillon') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('penthievre', 'Penthièvre', 'penthièvre océan|plage de penthièvre|isthme de penthièvre|les palissades|penthièvre', 47.5463, -3.1345, 'France', 'sea', 250, 'guide', 'kitesurf|windsurf|wingfoil', 'Bay side works mainly from mid-tide to low tide: shallow and standable, sheltered from swell and current. Ocean side tide behaviour for kiting is not documented. The surf break there is reported best around high tide.', 'Ocean side: exposed beach break with small to medium waves, and reefs are reported. Bay side: dike and oyster shells make it technical despite the flat water. Busy with schools in season.', 'Ocean side: the north zone (accesses 10-11) is a take-off/landing-only zone. Bay side: kite and other air-towed sports banned from 29 May to 11 September in front of the beach at the southern end of Camping de Penthièvre (reported dates; check the current municipal order).', 'Two launches about 100 m apart across the isthmus at the entrance to the Quiberon peninsula. Ocean side: the beach north of Fort de Penthièvre, for west-sector winds. Its northern part (beach accesses 10 and 11) is a take-off/landing-only zone. Bay side: 3 km sandy beach from Camping des Sables Blancs to the isthmus, for E/SE/NE winds. Parking at the isthmus. Schools use the bay side for beginners.', 'Year-round. Strongest and most reliable west winds are Oct-Mar, best Jan-Mar, for experienced riders. Lighter summer winds (weakest in July) suit the bay side. Schools operate Mar-Nov.', 'seed', 'https://vvanat.fr/blog/kitesurf-golfe-du-morbihan/|https://www.ecole.kite-spirit.com/ecole-kitesurf-quiberon/|https://www.unplug-kitesurf.com/spots/penthievre-france|https://thespot2be.com/spot/les_palissades/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'penthievre' AND (SELECT status FROM spots WHERE id = 'penthievre') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'penthievre', 'W', 'best', 'Reference direction for the ocean side (Côte Sauvage) north of Fort de Penthièvre. Schools quote W at 15-30 kn.' WHERE (SELECT status FROM spots WHERE id = 'penthievre') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'penthievre', 'WSW', 'best', 'West-sector wind, onshore to slightly cross on the ocean beach.' WHERE (SELECT status FROM spots WHERE id = 'penthievre') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'penthievre', 'WNW', 'best', 'West-sector wind, onshore to slightly cross on the ocean beach.' WHERE (SELECT status FROM spots WHERE id = 'penthievre') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'penthievre', 'SW', 'ok', 'Cross-onshore on the ocean side. Listed as a working direction by spot guides.' WHERE (SELECT status FROM spots WHERE id = 'penthievre') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'penthievre', 'NW', 'ok', 'Cross-onshore on the ocean side.' WHERE (SELECT status FROM spots WHERE id = 'penthievre') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'penthievre', 'NE', 'forbidden', 'Offshore on the ocean beach. Use the bay-side launch instead (it works SE to NE).' WHERE (SELECT status FROM spots WHERE id = 'penthievre') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'penthievre', 'E', 'forbidden', 'Offshore on the ocean beach. It is the bay side''s reference wind (flat, shallow water facing Carnac).' WHERE (SELECT status FROM spots WHERE id = 'penthievre') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'penthievre', 'SE', 'forbidden', 'Offshore on the ocean beach. Use the bay side instead.' WHERE (SELECT status FROM spots WHERE id = 'penthievre') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('la-torche', 'La Torche', 'pointe de la torche|tronoën|pors carn (south bay, penmarc''h)|la torche', 47.83911, -4.3471, 'France', 'sea', 260, 'guide', 'kitesurf|windsurf|wingfoil', 'At high tide the beach is narrow, with shore break and little room to launch. At low tide the beach is wide with sandbanks, but the ''Méchants'' rocks are exposed on the NW of Pors Carn. At Pors Carn, rising tide is preferred because of the many rocks; some rocks midway along the beach are covered at high tide.', 'Powerful waves, often mast-high or more. Strong rip current running out along the point, plus baïnes and strong lateral currents. The ''Méchants'' reef and its currents must be avoided. Rocky outcrop splitting the bay. The right side is for experienced wave riders only. Heavy crowds of bathers and surfers in summer.', 'Prefectural order: at Pors Carn kitesurf is allowed only in the yellow-buoyed channel (in season); do not ride past the end of the channel. 15 June-15 September: the right side of the point is tacitly left to surfers. Natura 2000 site: keep inside the marked boundaries.', 'Main free car park at the point, with direct access, toilets and showers. Big launch area on the beach north (right) of the point. For Pors Carn (left/south bay), access from the Cyprès car park in Penmarc''h. Never launch or land a kite on the grass or dunes: beach only, all year round. Avoid riding solo.', 'September to May; spring peak (March-May, May best); frequent strong WSW winds November-March.', 'seed', 'https://lets-kite.com/fr/spots/1076/la-torche|https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/la-torche-bretagne-france.html|https://www.onekite.com/topic/3752/bretagne-spots-autour-de-la-torche-penmarc-h', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'la-torche' AND (SELECT status FROM spots WHERE id = 'la-torche') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-torche', 'N', 'ok', 'Mainly for the left/south bay (Pors Carn), where N-NE give side-on starboard conditions.' WHERE (SELECT status FROM spots WHERE id = 'la-torche') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-torche', 'NNE', 'marginal', 'Workable on the Pors Carn side only; side-off on the main beach north of the point.' WHERE (SELECT status FROM spots WHERE id = 'la-torche') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-torche', 'NE', 'marginal', 'Pors Carn side only (side-on starboard); side-off to offshore on the main La Torche beach.' WHERE (SELECT status FROM spots WHERE id = 'la-torche') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-torche', 'NNW', 'ok', 'Side-on, works on both sides of the point.' WHERE (SELECT status FROM spots WHERE id = 'la-torche') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-torche', 'NW', 'best', 'Dominant wind; wraps both sides of the point, side-on to side-onshore.' WHERE (SELECT status FROM spots WHERE id = 'la-torche') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-torche', 'WNW', 'best', 'Side-onshore starboard on the main beach, classic wave-riding direction.' WHERE (SELECT status FROM spots WHERE id = 'la-torche') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-torche', 'W', 'ok', 'Onshore on the main beach; Pors Carn also works in W, which few local spots do.' WHERE (SELECT status FROM spots WHERE id = 'la-torche') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-torche', 'WSW', 'best', 'Side-onshore on the right (north) side; frequent with strong winter storms Nov-Mar.' WHERE (SELECT status FROM spots WHERE id = 'la-torche') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-torche', 'SW', 'best', 'Side-onshore on the right (north) side, good for waves.' WHERE (SELECT status FROM spots WHERE id = 'la-torche') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-torche', 'SSW', 'ok', 'Workable on the main beach; Pors Carn is sheltered/offshore in SSW.' WHERE (SELECT status FROM spots WHERE id = 'la-torche') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-torche', 'SE', 'forbidden', 'Offshore (it is the classic surf wind here).' WHERE (SELECT status FROM spots WHERE id = 'la-torche') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-torche', 'ESE', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'la-torche') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-torche', 'E', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'la-torche') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('lacanau-ocean-plage-sud', 'Lacanau Océan – Plage Sud', 'lacanau|lacanau-océan|plage sud lacanau|lacanau south beach|lacanau océan – plage sud', 44.9905, -1.2025, 'France', 'sea', 270, 'guide', 'kitesurf|windsurf', 'Tidal range up to about 4 m. At high tide the waves are good but the shore break can be powerful and hard to get through, especially strapless. At low tide, sandbars and baïne channels show up and rip currents get stronger.', 'Baïnes (bowls between sandbars) produce strong seaward rip currents, especially on the falling tide. Powerful shore break. Sandbars that keep moving. Some alios (hard sandstone) outcrops can damage fins. Crowded with swimmers and surfers in summer.', 'In summer during the day, only Plage Sud is open to kiting. Stay out of the lifeguarded swimming zones and keep downwind of them. On Lac de Lacanau, kitesurfing is only allowed on either side of the channel leading to Talaris marina (separate spot). Check the current municipal and prefecture orders on site.', 'Launch at Plage Sud, south of the town''s central lifeguarded beaches. Reach the beach over the dune on boardwalks. Rig and ride outside the swimming zones and downwind of them. Typical kites: 10-12 m², or 7-9 m² when the thermal kicks in. The lake (Moutchic/Talaris) is a separate flat-water spot with its own zone.', 'All year; autumn (September–November) for steady wind and swell; summer for the thermal NW breeze, with restrictions.', 'seed', 'https://www.larive.fr/en/where-can-you-kitesurf-in-the-landes/|https://vvanat.fr/blog/windsurf-lacanau-ocean/|https://www.plages.tv/detail/plage-sud-lacanau-33680', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'lacanau-ocean-plage-sud' AND (SELECT status FROM spots WHERE id = 'lacanau-ocean-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lacanau-ocean-plage-sud', 'NW', 'best', 'Reference direction: side-on, often boosted by the summer thermal sea breeze.' WHERE (SELECT status FROM spots WHERE id = 'lacanau-ocean-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lacanau-ocean-plage-sud', 'NNW', 'ok', 'Side-on, works well.' WHERE (SELECT status FROM spots WHERE id = 'lacanau-ocean-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lacanau-ocean-plage-sud', 'N', 'ok', 'Side-shore along the beach; usable.' WHERE (SELECT status FROM spots WHERE id = 'lacanau-ocean-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lacanau-ocean-plage-sud', 'WNW', 'ok', 'Side-onshore; choppier water and harder to get out through the shore break.' WHERE (SELECT status FROM spots WHERE id = 'lacanau-ocean-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lacanau-ocean-plage-sud', 'W', 'marginal', 'Straight onshore: messy water and hard to get out through the shore break.' WHERE (SELECT status FROM spots WHERE id = 'lacanau-ocean-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lacanau-ocean-plage-sud', 'SW', 'ok', 'Side-onshore; listed among the usable directions.' WHERE (SELECT status FROM spots WHERE id = 'lacanau-ocean-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lacanau-ocean-plage-sud', 'S', 'ok', 'Side-shore; listed among the usable directions.' WHERE (SELECT status FROM spots WHERE id = 'lacanau-ocean-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lacanau-ocean-plage-sud', 'E', 'forbidden', 'Offshore: wind blows you out to sea, gusty air after crossing the dune and forest.' WHERE (SELECT status FROM spots WHERE id = 'lacanau-ocean-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lacanau-ocean-plage-sud', 'NE', 'forbidden', 'Side-offshore to offshore; do not ride on the ocean side.' WHERE (SELECT status FROM spots WHERE id = 'lacanau-ocean-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lacanau-ocean-plage-sud', 'SE', 'forbidden', 'Side-offshore to offshore; do not ride on the ocean side.' WHERE (SELECT status FROM spots WHERE id = 'lacanau-ocean-plage-sud') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('hossegor-plage-sud', 'Hossegor – Plage Sud', 'soorts-hossegor|hossegor plage sud|la sud|hossegor – plage sud', 43.6605, -1.4462, 'France', 'sea', 280, 'guide', 'kitesurf|windsurf', 'Shore break changes with tide and swell. The surf break at Plage Sud works mainly at low tide and not at high tide. Baïnes (sandbar troughs that create rip currents) form and change with the tide.', 'Strong north-to-south longshore current with significant turbulence a few dozen metres from shore. Baïnes and rip currents. Variable shore break. Big, powerful winter swell (3 m+). Heavy crowds of surfers, surf schools and swimmers, especially in summer. Keep a fixed landmark on shore to watch your drift.', 'Kiting is discouraged during supervised bathing hours, especially in summer, because of crowds. One guide says a signposted kite zone exists from June to September during supervised hours (not confirmed by an official source). 2026 lifeguard season at Plage Sud: 4 Apr–25 Oct. Hours are 12:30–18:30, except 11:00–19:00 from 4 Jul to 30 Aug. No animals on the beach.', 'Main kite area is Plage Sud (south ocean beach, toward Capbreton), which has free parking and a lifeguard post. Its water is calmer than the rest of the coast, so it is a fallback spot when the sea is big. Alternative: Plage des Culs-Nus in the north, next to Les Estagnots (Seignosse), which is the recommended spot in summer. Stay clear of swimmers, walkers and the many surf schools. Windsurf beginners use Lac d''Hossegor instead (Plage du Rey sailing school, Plage des Chênes-Lièges, Plage Blanche, Plage du Parc).', 'Autumn to spring (Sep–May) for Plage Sud outside supervised hours, with strong W–NW fronts in winter. In summer, N–NW afternoon thermals are better used at Les Estagnots.', 'seed', 'https://fksudouest.com/les-spots/hossegor/|https://vvanat.fr/blog/kitesurf-dans-les-landes/|https://www.hossegor.fr/activites/plage-sud-ocean/|https://www.allosurf.net/infos/surf/plage-hossegor-plage-sud-spot-30077.html', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'hossegor-plage-sud' AND (SELECT status FROM spots WHERE id = 'hossegor-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hossegor-plage-sud', 'S', 'marginal', 'Usable but the wind is often irregular from the south.' WHERE (SELECT status FROM spots WHERE id = 'hossegor-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hossegor-plage-sud', 'SSW', 'ok', 'Part of the usable S-to-N-through-W window.' WHERE (SELECT status FROM spots WHERE id = 'hossegor-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hossegor-plage-sud', 'SW', 'ok', 'Common in winter: often gusty and comes with big swell.' WHERE (SELECT status FROM spots WHERE id = 'hossegor-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hossegor-plage-sud', 'WSW', 'ok', 'Onshore: big waves in winter.' WHERE (SELECT status FROM spots WHERE id = 'hossegor-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hossegor-plage-sud', 'W', 'ok', 'Onshore. Possible, but staying clear of the surf zones is harder. Winter westerlies can be strong and gusty.' WHERE (SELECT status FROM spots WHERE id = 'hossegor-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hossegor-plage-sud', 'WNW', 'ok', 'Onshore and usable.' WHERE (SELECT status FROM spots WHERE id = 'hossegor-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hossegor-plage-sud', 'NW', 'best', 'Reference direction. Steady NW at 18–25 kn is described as ideal.' WHERE (SELECT status FROM spots WHERE id = 'hossegor-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hossegor-plage-sud', 'NNW', 'best', 'Summer thermal sector (N to NW), usually 10–18 kn, building mid/late afternoon around 16–17h.' WHERE (SELECT status FROM spots WHERE id = 'hossegor-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hossegor-plage-sud', 'N', 'best', 'Summer thermal, side-shore, light to moderate.' WHERE (SELECT status FROM spots WHERE id = 'hossegor-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hossegor-plage-sud', 'NE', 'forbidden', 'East-sector winds (NE to SE) are offshore. Avoid.' WHERE (SELECT status FROM spots WHERE id = 'hossegor-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hossegor-plage-sud', 'ENE', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'hossegor-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hossegor-plage-sud', 'E', 'forbidden', 'Offshore. This is the surfers'' best wind, not the kiters''.' WHERE (SELECT status FROM spots WHERE id = 'hossegor-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hossegor-plage-sud', 'ESE', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'hossegor-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hossegor-plage-sud', 'SE', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'hossegor-plage-sud') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('la-tranche-sur-mer-plage-du-phare', 'La Tranche-sur-Mer – Plage du Phare', 'le phare|plage du phare|la tranche|la tranche-sur-mer – plage du phare', 46.3419, -1.46306, 'France', 'sea', 210, 'guide', 'kitesurf|windsurf|wingfoil', 'Le Phare works best from mid-tide to high water, when the beach gets narrow. Near low tide the rocky shelf is exposed or shallow. At high tide with big coefficients, shorebreak is powerful and stronger currents make entry and exit hazardous. The main La Tranche beach works at any tide.', 'Rocky shelf under the break and rocks around the point (marked by yellow buoys). Shorebreak and strong currents at high tide, plus baïnes. Lobster-pot lines and large jellyfish. With swell, the spot becomes a technically demanding wave spot.', 'Kitesurf May–Sept: allowed only at Plage du Phare (designated zone). Off-season: allowed everywhere except Plage de la Belle Henriette (nature reserve). Lifeguards on Plage du Phare in summer; keep clear of the bathing area.', 'Summer kite zone at Plage du Phare is in front of the ruined bunker to the west. Beyond it, yellow buoys mark shallows on the point. Free parking at Impasse de la Youte, with beach accesses 146/147. Windsurf beginners usually use the main La Tranche beach (sailing school, sandy bottom, rescue boats). Le Phare is for experienced riders.', 'May–September (thermal NW sea breeze, mid-May to end of August); autumn and winter for frontal SW–NW winds', 'seed', 'https://boards.co.uk/travel/world-travel/la-tranche-sur-mer-vendee-france.html|https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/le-phare-pays-de-la-loire-france.html|https://vvanat.fr/blog/kitesurf-au-phare-de-la-tranche-sur-mer/|https://bord-de-mer.com/?p=9566', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'la-tranche-sur-mer-plage-du-phare' AND (SELECT status FROM spots WHERE id = 'la-tranche-sur-mer-plage-du-phare') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-tranche-sur-mer-plage-du-phare', 'NW', 'best', 'Reference direction. Thermal NW sea breeze, sped up between the mainland and Île de Ré; often comes in mid-afternoon (around 15:00) from May to August.' WHERE (SELECT status FROM spots WHERE id = 'la-tranche-sur-mer-plage-du-phare') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-tranche-sur-mer-plage-du-phare', 'WNW', 'best', 'Boards guide gives NW through W as the best range at Le Phare.' WHERE (SELECT status FROM spots WHERE id = 'la-tranche-sur-mer-plage-du-phare') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-tranche-sur-mer-plage-du-phare', 'W', 'best', 'Cross-onshore. Within the best range given by boards.co.uk.' WHERE (SELECT status FROM spots WHERE id = 'la-tranche-sur-mer-plage-du-phare') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-tranche-sur-mer-plage-du-phare', 'WSW', 'ok', 'Onshore-ish. Usable at Le Phare. SW is reported as the best direction for the main La Tranche beach.' WHERE (SELECT status FROM spots WHERE id = 'la-tranche-sur-mer-plage-du-phare') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-tranche-sur-mer-plage-du-phare', 'SW', 'ok', 'Onshore at Le Phare. Best direction for the main town beach (sailing school).' WHERE (SELECT status FROM spots WHERE id = 'la-tranche-sur-mer-plage-du-phare') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-tranche-sur-mer-plage-du-phare', 'SSW', 'ok', 'Given as the southern limit of the usable onshore range at Le Phare.' WHERE (SELECT status FROM spots WHERE id = 'la-tranche-sur-mer-plage-du-phare') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-tranche-sur-mer-plage-du-phare', 'NNW', 'ok', 'Usable, but northerly components cause an inshore wind shadow (gusty near the beach), especially at the main beach.' WHERE (SELECT status FROM spots WHERE id = 'la-tranche-sur-mer-plage-du-phare') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-tranche-sur-mer-plage-du-phare', 'N', 'marginal', 'Northern limit of the usable range. Wind shadow inshore, gusty.' WHERE (SELECT status FROM spots WHERE id = 'la-tranche-sur-mer-plage-du-phare') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-tranche-sur-mer-plage-du-phare', 'SE', 'marginal', 'Rare. Sideshore-to-side-off at Le Phare, moderate and gusty.' WHERE (SELECT status FROM spots WHERE id = 'la-tranche-sur-mer-plage-du-phare') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-tranche-sur-mer-plage-du-phare', 'NE', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'la-tranche-sur-mer-plage-du-phare') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'la-tranche-sur-mer-plage-du-phare', 'E', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'la-tranche-sur-mer-plage-du-phare') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('leucate-la-franqui-les-coussoules', 'Leucate La Franqui (Les Coussoules)', 'la franqui|les coussoules|leucate - la franqui - les coussoules|leucate la franqui (les coussoules)', 42.9382, 3.03858, 'France', 'sea', 100, 'guide', 'kitesurf|windsurf|wingfoil', 'Mediterranean: tide is negligible and the spot does not depend on it.', 'Cross-offshore Tramontane is strong and gusty and can push you out to sea. If you break gear or the wind drops, you drift offshore. When the wind turns onshore, a dumping shore break forms. The beach gets busy with schools and events such as the Mondial du Vent in April. In the nearby lagoon, oyster beds are marked by wooden posts.', 'During the supervised summer season the first 300 m from shore is the bathing band. Kites and windsurfs must cross it only through the marked nautical channel and ride beyond it. Local beach marking is set by municipal orders (e.g. arrêté n°32-2010 on beach marking). Le Goulet area is reserved for windsurf.', 'Park next to Camping des Coussoules / Domaine La Franqui. Walk about 300 m along the beach to the kite zone in front of the (old) lifeguard tower. The launch area is secured by the local association (KSL) and shared by independent riders and the many schools. The northern part toward Le Goulet is for windsurfers only.', 'March-April and July-October (Tramontane most consistent in spring); rideable year-round', 'seed', 'https://www.ultimatefrance.com/kitesurfing/south-france/leucate-la-franqui|https://www.ultimatefrance.com/?p=5582|http://en.wannakitesurf.com/spot/Europe/France/Languedoc_Roussillon/La_Franqui/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'leucate-la-franqui-les-coussoules' AND (SELECT status FROM spots WHERE id = 'leucate-la-franqui-les-coussoules') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'leucate-la-franqui-les-coussoules', 'N', 'ok', 'Tramontane veering north is side-shore. Flat to choppy water.' WHERE (SELECT status FROM spots WHERE id = 'leucate-la-franqui-les-coussoules') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'leucate-la-franqui-les-coussoules', 'NW', 'best', 'Tramontane, the reference wind. It blows cross-offshore and gusty, often 25-40+ kn. Flat water and chop for bump & jump, freeride and freestyle. For experienced riders only.' WHERE (SELECT status FROM spots WHERE id = 'leucate-la-franqui-les-coussoules') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'leucate-la-franqui-les-coussoules', 'WNW', 'marginal', 'The Tramontane gets more offshore and gusty here. Drift risk out to sea.' WHERE (SELECT status FROM spots WHERE id = 'leucate-la-franqui-les-coussoules') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'leucate-la-franqui-les-coussoules', 'W', 'forbidden', 'Straight offshore.' WHERE (SELECT status FROM spots WHERE id = 'leucate-la-franqui-les-coussoules') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'leucate-la-franqui-les-coussoules', 'NE', 'ok', 'Side-onshore.' WHERE (SELECT status FROM spots WHERE id = 'leucate-la-franqui-les-coussoules') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'leucate-la-franqui-les-coussoules', 'E', 'ok', 'Onshore. Waves build and tend to dump on the beach.' WHERE (SELECT status FROM spots WHERE id = 'leucate-la-franqui-les-coussoules') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'leucate-la-franqui-les-coussoules', 'SE', 'ok', 'Marin: humid onshore wind, mostly in summer. Gives surfable waves and a dumping shore break.' WHERE (SELECT status FROM spots WHERE id = 'leucate-la-franqui-les-coussoules') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'leucate-la-franqui-les-coussoules', 'S', 'ok', 'Side-onshore. Waves tend to dump on the beach.' WHERE (SELECT status FROM spots WHERE id = 'leucate-la-franqui-les-coussoules') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('leucate-plage-les-pilotis-le-mouret', 'Leucate Plage (Les Pilotis / Le Mouret)', 'les pilotis|le mouret|leucate-plage|leucate plage (les pilotis / le mouret)', 42.9006, 3.0511, 'France', 'sea', 100, 'guide', 'kitesurf|windsurf|wingfoil', 'Mediterranean: tide is negligible. Water level changes with wind (storm surge in Marin, lower water in Tramontane).', 'Offshore Tramontane: strong gusts and drift out to sea. Shore break and waves in onshore wind. Water stays shallow for a short distance from shore. Bathers in summer.', '', 'Sandy sea beach at Les Pilotis / Le Mouret, between Leucate Plage and the oyster centre. Beach clubs on site. Motorhome parking at Aire de Mouret. Le Mouret is a protected natural beach: respect bathers and keep the beach clear.', 'Spring and autumn for the strongest wind; summer for the thermal Marin (SE).', 'seed', 'https://en.tourisme-leucate.com/discover/riding-in-leucate/leucate-top-spots/|https://www.ultimatefrance.com/?p=5582|https://vvanat.fr/blog/planche-a-voile-port-leucate/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'leucate-plage-les-pilotis-le-mouret' AND (SELECT status FROM spots WHERE id = 'leucate-plage-les-pilotis-le-mouret') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'leucate-plage-les-pilotis-le-mouret', 'NW', 'forbidden', 'Tramontane, the dominant local wind (often 300+ days/yr), blows offshore here: flat water and fast runs per the tourist office, but it is strong and gusty and pushes riders out to sea. Experienced riders only, with rescue cover.' WHERE (SELECT status FROM spots WHERE id = 'leucate-plage-les-pilotis-le-mouret') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'leucate-plage-les-pilotis-le-mouret', 'N', 'forbidden', 'Offshore or cross-offshore with Tramontane gusts.' WHERE (SELECT status FROM spots WHERE id = 'leucate-plage-les-pilotis-le-mouret') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'leucate-plage-les-pilotis-le-mouret', 'WNW', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'leucate-plage-les-pilotis-le-mouret') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'leucate-plage-les-pilotis-le-mouret', 'SE', 'best', 'Marin, onshore: regular moderate thermal wind in summer, waves in the off-season. Suits bump & jump.' WHERE (SELECT status FROM spots WHERE id = 'leucate-plage-les-pilotis-le-mouret') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'leucate-plage-les-pilotis-le-mouret', 'S', 'ok', 'Side-shore. Lifts waves on this stretch of coast.' WHERE (SELECT status FROM spots WHERE id = 'leucate-plage-les-pilotis-le-mouret') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'leucate-plage-les-pilotis-le-mouret', 'E', 'ok', 'Onshore, sea state builds.' WHERE (SELECT status FROM spots WHERE id = 'leucate-plage-les-pilotis-le-mouret') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('gruissan', 'Gruissan', 'plage des chalets|la vieille nouvelle|gruissan plage|gruissan', 43.08612, 3.0915, 'France', 'sea', 120, 'guide', 'kitesurf|windsurf|wingfoil', 'Mediterranean, tide is negligible.', 'Offshore Tramontane: risk of drifting out to sea, and the wind is gusty and turbulent at the Chalets because of the buildings. Getting overpowered on strong days (wind can gain 10+ kn between Gruissan and Port-la-Nouvelle). Vieille Nouvelle has no lifeguards. Waves in Marin. At La Nautique lagoon: stone blocks and broken tiles on the bottom.', 'In summer, launching from the Plage des Chalets is banned because of the swimming zone: launch from the marked channels and go beyond the 300 m strip. No vehicles on the Vieille Nouvelle beach.', 'Two sea launches. Plage des Chalets (Pôle Mer / Akila school at the beach entrance, Défi Wind venue). La Vieille Nouvelle, south of the Chalets past the dike: the reference Tramontane spot, runs of 10+ km towards Port-la-Nouvelle, wind stronger and steadier there. Driving onto the Vieille Nouvelle beach is banned (reported €1,500 fine): access on foot from the Chalets or via the canal. Lagoon options: Étang de Mateille, La Nautique, Grazel.', 'April to October (Tramontane season). Wind more than 300 days a year.', 'seed', 'https://srokacompany.com/en/blogs/news/wingfoil-destination-in-gruissan|https://vvanat.fr/blog/zone-kitesurf-gruissan/|https://holfuy.com/en/weather/1135', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'gruissan' AND (SELECT status FROM spots WHERE id = 'gruissan') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'gruissan', 'NW', 'best', 'Tramontane, the dominant wind, Apr-Oct in 3-6 day spells. Offshore to side-offshore: flat, glassy water and long speed runs. Gusty near the Chalets buildings, steadier past the dike towards Vieille Nouvelle. Experienced riders only.' WHERE (SELECT status FROM spots WHERE id = 'gruissan') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'gruissan', 'WNW', 'marginal', 'Tramontane can swing to straight offshore. Gusty, high drift risk.' WHERE (SELECT status FROM spots WHERE id = 'gruissan') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'gruissan', 'W', 'forbidden', 'Straight offshore at a SE-facing beach (estimated from the coast orientation).' WHERE (SELECT status FROM spots WHERE id = 'gruissan') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'gruissan', 'NNE', 'ok', 'Cross-shore, lets you get back to the beach on either tack.' WHERE (SELECT status FROM spots WHERE id = 'gruissan') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'gruissan', 'SSW', 'ok', 'Cross-shore, lets you get back to the beach on either tack.' WHERE (SELECT status FROM spots WHERE id = 'gruissan') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'gruissan', 'SE', 'ok', 'Marin: onshore, brings waves, good for freeride.' WHERE (SELECT status FROM spots WHERE id = 'gruissan') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('port-la-nouvelle-plage-sud', 'Port-la-Nouvelle – Plage Sud', 'plage sud de port-la-nouvelle|port la nouvelle|port-la-nouvelle – plage sud', 43.005, 3.051, 'France', 'sea', 110, 'guide', 'kitesurf|windsurf', 'Mediterranean, tidal range negligible. Conditions depend on wind and swell, not tide.', 'Medium to powerful shore break in Marin. Harbour channel and breakwaters at the north end of the beach, with commercial port traffic. Offshore Tramontane (NW) carries riders out to sea.', '', 'Plage Sud, south of the harbour jetties. Sandy beach with parking. Usually much less crowded than nearby spots (Leucate, Gruissan).', '', 'seed', 'https://vvanat.fr/blog/port-la-nouvelle-le-rouet-windsurf/|https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/port-la-nouvelle-occitanie-pyrenees-mediterranee-france.html', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'port-la-nouvelle-plage-sud' AND (SELECT status FROM spots WHERE id = 'port-la-nouvelle-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'port-la-nouvelle-plage-sud', 'SE', 'best', 'Marin: onshore to cross-onshore, builds a medium to powerful beach break at Plage Sud. Waves are cleaner north of the breakwaters, but you have to cross the harbour channel to get there.' WHERE (SELECT status FROM spots WHERE id = 'port-la-nouvelle-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'port-la-nouvelle-plage-sud', 'ESE', 'ok', 'Marin variant, onshore with beach break.' WHERE (SELECT status FROM spots WHERE id = 'port-la-nouvelle-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'port-la-nouvelle-plage-sud', 'NE', 'ok', 'Occasional NE thermal between Gruissan and La Franqui, usually around 15 kn.' WHERE (SELECT status FROM spots WHERE id = 'port-la-nouvelle-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'port-la-nouvelle-plage-sud', 'NW', 'forbidden', 'Tramontane: offshore here, flat water but it pushes you out to sea. Guides say experienced riders only. Unsafe without rescue; ride the Etang de La Palme instead (onshore there).' WHERE (SELECT status FROM spots WHERE id = 'port-la-nouvelle-plage-sud') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'port-la-nouvelle-plage-sud', 'WNW', 'forbidden', 'Offshore at the sea beach.' WHERE (SELECT status FROM spots WHERE id = 'port-la-nouvelle-plage-sud') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('l-almanarre', 'L''Almanarre', 'almanarre|plage de l''almanarre|route du sel|presqu''île de giens - almanarre|l''almanarre', 43.065, 6.132, 'France', 'sea', 250, 'guide', 'kitesurf|windsurf|wingfoil', 'Mediterranean, almost no tide; it does not affect sessions.', 'Narrow beach with a road just behind, so launching and landing are risky. Strong, gusty Mistral. The water gets deep quickly. Waves close out in Mistral. There are rocks to the right of the launch. Crowded on the water and in the car parks when the wind is good, and cars at the car parks get broken into.', 'Kitesurfing is allowed only in the designated zones (Almanarre between accesses 16 and 21, plus two other designated zones). Riding is forbidden inside the 300 m strip from shore except in the marked channels, which are in place from April to October. Stricter rules apply from 15 June to 15 September, when the Route du Sel is open and summer zones are buoyed. A beach marshal and municipal police on jet-ski patrol in summer and can fine riders who break the rules.', 'Main kite zone: Route du Sel, between beach accesses 16 and 21. In summer it is marked by wooden posts with FFVL flags. The beach is narrow (about 150 m) with the road right behind it, so take off and land carefully and do not rig on the road. The water gets deep quickly. Quieter alternatives on the same beach: La Madrague (shallower, smaller waves) and behind Camping International, both with buoyed kite zones in summer. A welcome point with a beach marshal runs in July and August.', 'October to April for the most wind (Mistral). Summer works too, but with more restrictions and crowds.', 'seed', 'https://www.ultimatefrance.com/kitesurfing/south-france/almanarre|https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/l-almanarre-hyeres-provence-alpes-cote-d-azur-france.html|https://vvanat.fr/blog/kitesurf-almanarre-spot-carte/|https://hyeres.fr/wp-content/uploads/2026/07/regles_bonnes_pratique_kite_hyeres_fr_eng.pdf', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'l-almanarre' AND (SELECT status FROM spots WHERE id = 'l-almanarre') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'l-almanarre', 'NW', 'best', 'Mistral blows cross-onshore from the right, often Force 6-9. It is usually a little weaker here than further south. Gusty, with choppy water and closing-out waves that suit jumping more than wave riding.' WHERE (SELECT status FROM spots WHERE id = 'l-almanarre') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'l-almanarre', 'WNW', 'best', 'Mistral sector. Cross-onshore, powerful and gusty, with waves breaking on a small reef upwind.' WHERE (SELECT status FROM spots WHERE id = 'l-almanarre') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'l-almanarre', 'W', 'best', 'Onshore to cross-onshore. A reference direction, with choppy water and waves.' WHERE (SELECT status FROM spots WHERE id = 'l-almanarre') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'l-almanarre', 'SW', 'best', 'Libeccio, up to about 20 kn. A reference direction, cross-onshore from the left.' WHERE (SELECT status FROM spots WHERE id = 'l-almanarre') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'l-almanarre', 'NNW', 'marginal', 'Northerly Mistral turns side-shore to side-off from the right, so it gets gustier near the beach.' WHERE (SELECT status FROM spots WHERE id = 'l-almanarre') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'l-almanarre', 'E', 'forbidden', 'Offshore for this west-facing beach. Some guides describe flat, glassy water for experienced riders who can go upwind, but drifting out to sea is a real risk. Not suitable for most riders.' WHERE (SELECT status FROM spots WHERE id = 'l-almanarre') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'l-almanarre', 'SE', 'marginal', 'Some guides list it as usable, but it is side-off on a west-facing beach. Experienced riders only.' WHERE (SELECT status FROM spots WHERE id = 'l-almanarre') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('beauduc', 'Beauduc', 'plage de beauduc|plage de la comtesse|golfe de beauduc|beauduc', 43.39943, 4.58802, 'France', 'sea', NULL, 'guide', 'kitesurf|windsurf|wingfoil', 'Mediterranean, so tide is negligible. Strong SW wind and storm surge can flood the low-lying beach and the parking area.', 'Weever fish (vives) buried in the sand, stings can go through soft booties. Very remote, with weak or no phone signal, so rescue is slow; carry a first-aid kit. Cars can sink in soft sand. Beach floods in strong SW. Offshore drift in E/SE winds. Crowded in summer. Mosquitoes.', 'Protected natural site (communes of Arles and Saintes-Maries). Arles municipal order of 27/03/2014 and prefectoral order of 30/09/2013: Plage de la Comtesse is reserved for kites and sail sports, and the southern part for swimming and fishing. Motor vehicles and land sail sports are banned on the public maritime land of the point from 1 April to 30 September. Camping banned since 2018, dunes off-limits. Track limited to vehicles about 2.0-2.1 m wide; quads, motorbikes and campervans banned.', 'Kites launch and land on the right-hand part of the beach (Plage de la Comtesse), which is set aside for kites and other sail sports. Kitesurfers use the left side in onshore winds, where the water is deeper. Shallow water for about 100 m. Huge sand area with no walk from parking. No water, toilets or shops except a small snack bar in summer. Take your waste back to town.', 'Year-round. Best April-October, with June-July the peak (thermals and moderate Mistral). Strong Mistral in winter.', 'seed', 'https://ultimatefrance.com/kitesurfing/south-france/beauduc|https://vvanat.fr/blog/beauduc-kitesurf-dechets-reglementation/|https://vvanat.fr/blog/spot-de-windsurf-beauduc-acces/|https://se.kiteforum.com/landkite/spot/beauduc', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'beauduc' AND (SELECT status FROM spots WHERE id = 'beauduc') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'beauduc', 'N', 'best', 'Mistral is the reference wind here: cross-shore, flat to slightly choppy water, often strong and not too gusty over the flat salt marshes. Guides say about 15 kn is ideal, but winter Mistral can reach 60 kn.' WHERE (SELECT status FROM spots WHERE id = 'beauduc') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'beauduc', 'NNW', 'best', 'Mistral/Tramontane sector, cross-shore. Listed as a main direction on kiteforum. Can build small waves when strong.' WHERE (SELECT status FROM spots WHERE id = 'beauduc') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'beauduc', 'NW', 'best', 'Mistral/Tramontane, cross-shore, regularly 25-30 kn. The right-hand side of the beach is preferred by windsurfers in side-shore Mistral.' WHERE (SELECT status FROM spots WHERE id = 'beauduc') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'beauduc', 'W', 'ok', 'Listed among the good directions. The U-shaped bay keeps it rideable.' WHERE (SELECT status FROM spots WHERE id = 'beauduc') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'beauduc', 'SW', 'ok', 'Reliable summer thermal, side-shore to side-on, good for learning. The beach can flood in strong SW.' WHERE (SELECT status FROM spots WHERE id = 'beauduc') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'beauduc', 'S', 'ok', 'Side-on, rideable. Recommended for learners together with SW.' WHERE (SELECT status FROM spots WHERE id = 'beauduc') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'beauduc', 'SE', 'marginal', 'Sources disagree: one guide calls SE offshore and dangerous (schools move north), another lists it as a usable wind. Check on site.' WHERE (SELECT status FROM spots WHERE id = 'beauduc') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'beauduc', 'E', 'forbidden', 'Straight easterly is described as the only fully offshore wind. Do not ride.' WHERE (SELECT status FROM spots WHERE id = 'beauduc') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('saint-cyprien-plage-nord', 'Saint-Cyprien – Plage Nord', 'saint-cyprien plage|st cyprien north beach|plage de l''amourette|saint-cyprien – plage nord', 42.64078, 3.03544, 'France', 'sea', 90, 'guide', 'kitesurf|windsurf|wingfoil|sailing', 'Mediterranean with very little tide. Tide has almost no effect on sessions.', 'Swimmers and lifeguard zones on the beach in summer. Strong, gusty tramontane blows offshore. The harbour is to the south of Plage Nord.', 'Use the marked kite and windsurf channels. Lifeguard station no. 1 is on the beach. Dogs are not allowed on the beach. Parking is paid in July and August. I did not find the text of the municipal order.', 'Launch from Plage Nord (Boulevard Desnoyer). It has one marked channel for windsurfing and a separate one for kitesurfing, so use the kite channel to get in and out. The town and the local association have put signs across the whole practice area. Two water-sports clubs, including CBCM Boarder Club at 75 Bd Desnoyer, give lessons and rent gear.', 'April to October (tourist office).', 'seed', 'https://en.tourisme-saint-cyprien.com/activities/water-sports/go-kitesurfing/|https://www.tourisme-pyreneesorientales.com/plage-nord/saint-cyprien/loilar066v50qx3q|https://en.tourisme-saint-cyprien.com/saint-cyprien-the-destination/turning-the-beach-at-saint-cyprien/north-beach/|https://vvanat.fr/blog/spot-de-kitesurf-autour-de-perpignan/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'saint-cyprien-plage-nord' AND (SELECT status FROM spots WHERE id = 'saint-cyprien-plage-nord') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'saint-cyprien-plage-nord', 'NW', 'forbidden', 'Tramontane, the dominant local wind. It blows offshore here because the beach faces east, and it is often strong and gusty.' WHERE (SELECT status FROM spots WHERE id = 'saint-cyprien-plage-nord') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'saint-cyprien-plage-nord', 'W', 'forbidden', 'Offshore on an east-facing beach.' WHERE (SELECT status FROM spots WHERE id = 'saint-cyprien-plage-nord') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'saint-cyprien-plage-nord', 'N', 'marginal', 'Side-shore to side-off along a north-south coastline. Likely gusty.' WHERE (SELECT status FROM spots WHERE id = 'saint-cyprien-plage-nord') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'saint-cyprien-plage-nord', 'SE', 'ok', 'Marin, the onshore sea wind. Sources do not rate it as best or ok, so this rating is inferred from the beach orientation.' WHERE (SELECT status FROM spots WHERE id = 'saint-cyprien-plage-nord') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('carro', 'Carro', 'plage de carro|pointe de carro|les ragues|carro', 43.33153, 5.04337, 'France', 'sea', 225, 'guide', 'windsurf|kitesurf', '', 'Rocky reef and abrasive bottom with underwater holes, mussel-covered rocks and sea urchins, strong currents, heavy shore break, waves up to about 2 m, a dike/jetty near the port, and a risk of drifting offshore in Mistral.', '', 'No real beach at the wave spot: you launch from a rocky shelf on slippery slabs near Pointe de Carro. Large car parks on Rue des Ragues on the way out to the point. Advanced riders only. Kiting is described as tricky or impractical because of the rocky launch and landing. Equipment theft is reported, so do not leave gear unattended.', 'Year-round; often windy (Mistral and SE storms), and autumn to spring brings the most wave days.', 'seed', 'https://www.ultimatefrance.com/kitesurfing/south-france/carro|https://vvanat.fr/blog/carro-windsurf-secteur/|https://provence-alpes-cotedazur.com/que-faire/detente-et-loisirs/toutes-les-activites-detente-et-loisirs/spot-de-voile-de-carro-martigues-fr-4732872/|https://waterwind.it/new/en/windsurfing/spots/spots-reviews/262-france/1120-carro-france.html', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'carro' AND (SELECT status FROM spots WHERE id = 'carro') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'carro', 'SE', 'best', 'Cross-shore from the left; biggest waves (1.5-3 m) but choppy. Reference wave-riding direction.' WHERE (SELECT status FROM spots WHERE id = 'carro') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'carro', 'SSE', 'best', 'S/SE winds give the classic wave sessions.' WHERE (SELECT status FROM spots WHERE id = 'carro') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'carro', 'S', 'ok', 'Reported as working with swell.' WHERE (SELECT status FROM spots WHERE id = 'carro') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'carro', 'E', 'ok', 'Usable, but easterlies can blow out the waves.' WHERE (SELECT status FROM spots WHERE id = 'carro') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'carro', 'W', 'ok', 'Listed as a working direction; often lighter.' WHERE (SELECT status FROM spots WHERE id = 'carro') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'carro', 'NW', 'marginal', 'Mistral: cross-off from the right, clean reef-break waves, but there is a risk of being blown offshore. Experts only, and only if you can go upwind well.' WHERE (SELECT status FROM spots WHERE id = 'carro') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'carro', 'N', 'forbidden', 'Northerly Mistral is offshore and flattens the waves; guides suggest La Cabane, about 500 m west, instead.' WHERE (SELECT status FROM spots WHERE id = 'carro') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('tarifa-los-lances', 'Tarifa Los Lances', 'playa de los lances|los lances norte|los lances sur|rio jara|tarifa los lances', 36.0355, -5.62946, 'Spain', 'sea', 220, 'guide', 'kitesurf|windsurf|wingfoil', 'Rideable at all tide stages.', 'Levante is gusty and side-off, with drift risk out to sea. Shore break, especially with swell. Crowded, sometimes hectic, mostly in Levante. Wind is stronger near Tarifa town. Protected lagoon (La Charca) halfway along the beach: riding inside the staked area is forbidden.', 'Marked zones (yellow buoys) separate swimmers, kite schools and freeriders in summer; strictly enforced in summer, more relaxed in winter. Kiting in the protected lagoon is forbidden and can be fined.', '7+ km sandy beach with many access points and car parks along the beach road (Rio Jara, Football Field, Los Carriles, others near town). Rio Jara area is the main launch in Levante. In summer use only the marked kite zones; respect school and swimmer zones. Area north of the kite zone up to La Peña is reserved for windsurfing. Arrive early in high season.', 'March-September (windiest); rideable all year', 'seed', 'https://kitefuntarifa.com/en/kitesurf-spots-tarifa/kitesurf-spot-los-lances.html|https://www.iksurfmag.com/travel-guides/europe/spain/tarifa|https://andalucia.com/tarifa/kitesurf/practice-areas|https://en.wikipedia.org/wiki/Playa_de_Los_Lances', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'tarifa-los-lances' AND (SELECT status FROM spots WHERE id = 'tarifa-los-lances') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'tarifa-los-lances', 'E', 'best', 'Levante: strong, warm, gusty; side-off from the left at Los Lances. Most popular kite wind here, but drift risk out to sea; rescue boat service operates in Levante. Medium/small kites.' WHERE (SELECT status FROM spots WHERE id = 'tarifa-los-lances') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'tarifa-los-lances', 'W', 'best', 'Poniente: steady, cooler, side-on/onshore from the right. Wide beach makes it easy to find space. Medium/large kites.' WHERE (SELECT status FROM spots WHERE id = 'tarifa-los-lances') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('tarifa-valdevaqueros', 'Tarifa Valdevaqueros', 'valdevaqueros|playa de valdevaqueros|valdevaqueros tarifa|tarifa valdevaqueros', 36.06722, -5.67806, 'Spain', 'sea', 205, 'guide', 'kitesurf|windsurf|wingfoil', 'At high tide a small lagoon fills at the river mouth and gives flat water for tricks. No other tide guidance was found in the sources.', 'Rocks on the beach and underwater rocks at the southern end, inside the summer kite zone. The zone is narrow and very crowded in summer. Levante is side-offshore and can carry riders out to sea. Gusty, very strong Levante days.', 'Kite and windsurf zones are strictly enforced in summer when the beaches are crowded. Schools give this period as about 15 June to 15 September. Swimmer areas are marked by yellow buoys. Rules are more relaxed in winter.', 'The summer kite zone is the southern part of the beach, in front of Bibo bar. The northern part, up to the dunes, is for windsurfers. Respect the marked kite, windsurf and swimmer zones (yellow buoys). Access is by exits from the N-340. Parking fills up quickly in summer.', 'All year. Spring and autumn are best for Levante and space. Summer has reliable thermals but restricted, crowded zones.', 'seed', 'https://kitefuntarifa.com/en/kitesurf-spots-tarifa/kitesurf-spot-valdevaqueros.html|https://kitefuntarifa.com/en/blog/guide-kitesurf-spots-winds-tarifa.html|https://andalucia.com/tarifa/kitesurf/practice-areas|https://en.wikipedia.org/wiki/Valdevaqueros', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'tarifa-valdevaqueros' AND (SELECT status FROM spots WHERE id = 'tarifa-valdevaqueros') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'tarifa-valdevaqueros', 'E', 'best', 'Levante is the reference wind here, side-offshore, often strong and gusty, so small to medium kites. Outside summer it is called the safest Tarifa spot in Levante because Punta Paloma limits the risk of drifting out to sea.' WHERE (SELECT status FROM spots WHERE id = 'tarifa-valdevaqueros') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'tarifa-valdevaqueros', 'ENE', 'marginal', 'Levante turning more offshore. Risk of drifting out. ''If no-one else is out in Levante, don''t even think about it.''' WHERE (SELECT status FROM spots WHERE id = 'tarifa-valdevaqueros') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'tarifa-valdevaqueros', 'W', 'ok', 'Poniente: the easiest wind, lighter, needs bigger kites. Los Lances is usually preferred in Poniente because it has more space. Summer thermal effect around midday on warm days.' WHERE (SELECT status FROM spots WHERE id = 'tarifa-valdevaqueros') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'tarifa-valdevaqueros', 'WSW', 'ok', 'Poniente/thermal side-onshore. Usable with large kites (12-15 m) on light days.' WHERE (SELECT status FROM spots WHERE id = 'tarifa-valdevaqueros') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('el-medano-playa-sur-leocadio-machado', 'El Médano – Playa Sur (Leocadio Machado)', 'el medano|bahía de el médano|playa sur|playa del médano|playa leocadio machado|el médano – playa sur (leocadio machado)', 28.04305, -16.53923, 'Spain', 'sea', 130, 'guide', 'kitesurf|windsurf|wingfoil', 'Guides say it works at any tide. Watch out at low tide for exposed rocks just off and to the right of the launch, and around El Cabezo (the ''Godzilla'' rock).', 'Rocky shore downwind with very few places to land, so don''t drift past the bay. Gusty wind close inshore. Shore break, waves 1-2 m. Strong currents and swell outside the bay, where riding is not advised. Current near the northern jetty. Sand and volcanic reef bottom, with sea urchins on the rocky slabs at El Cabezo. The spot gets crowded with windsurfers, kiters and schools. Lifeguards on duty.', 'Kite and windsurf zones are separate: kites in the south of the bay, windsurfers upwind. Montaña Roja (south end) is a Special Nature Reserve. Its specific kite restrictions were not confirmed.', 'Sandy beach that shelves slowly into deep water. A dedicated kite set-up zone is on the beach. Kiters use the southern part of the bay, downwind of the windsurfers, and launch/land downwind (leeward) of the bunker. Windsurfers stay further upwind (north). Schools, rentals and gear storage containers are on the seafront.', 'All year round thanks to the trade winds. Strongest Jun-Sep, especially Jul-Aug.', 'seed', 'https://www.hellocanaryislands.com/kitesurfing/tenerife/kitesurf-on-el-medano-beach/|https://www.surf-magazin.de/en/spots-and-areas/international/spain/el-medano-el-cabezo-and-co-the-best-windsurfing-spots-on-tenerife/|https://web.kite-and-windsurfing-guide.com/en/spots/kiteboarding-windsurfing-sup/bahia-de-el-medano-playa-sur-tenerife-islas-canarias.html|https://wannakitesurf.com/spot/Europe/Canary/Tenerife/El_Medano_-_South_Beach/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'el-medano-playa-sur-leocadio-machado' AND (SELECT status FROM spots WHERE id = 'el-medano-playa-sur-leocadio-machado') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'el-medano-playa-sur-leocadio-machado', 'NE', 'best', 'Reference trade wind (alisios), side/cross-onshore from the left. Funnelled and strengthened by the island relief. Typically 16-25 kn, strongest in Jul-Aug.' WHERE (SELECT status FROM spots WHERE id = 'el-medano-playa-sur-leocadio-machado') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'el-medano-playa-sur-leocadio-machado', 'ENE', 'best', 'Prevailing direction in the stats (73-89°). Cross-onshore from the left.' WHERE (SELECT status FROM spots WHERE id = 'el-medano-playa-sur-leocadio-machado') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'el-medano-playa-sur-leocadio-machado', 'NNE', 'ok', 'Usable trade-wind variant. Gusty close to the shore, especially near the northern jetty.' WHERE (SELECT status FROM spots WHERE id = 'el-medano-playa-sur-leocadio-machado') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'el-medano-playa-sur-leocadio-machado', 'N', 'ok', 'The tourist board lists N and NE as the good directions, mainly in summer. It turns more side-shore, so expect gusts near the beach.' WHERE (SELECT status FROM spots WHERE id = 'el-medano-playa-sur-leocadio-machado') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'el-medano-playa-sur-leocadio-machado', 'E', 'ok', 'Onshore-leaning. Usable, more chop.' WHERE (SELECT status FROM spots WHERE id = 'el-medano-playa-sur-leocadio-machado') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'el-medano-playa-sur-leocadio-machado', 'NW', 'forbidden', 'Offshore given the SE-facing beach (inferred from orientation, not stated in guides).' WHERE (SELECT status FROM spots WHERE id = 'el-medano-playa-sur-leocadio-machado') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'el-medano-playa-sur-leocadio-machado', 'WNW', 'forbidden', 'Offshore given the SE-facing beach (inferred from orientation).' WHERE (SELECT status FROM spots WHERE id = 'el-medano-playa-sur-leocadio-machado') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'el-medano-playa-sur-leocadio-machado', 'W', 'forbidden', 'Offshore given the SE-facing beach (inferred from orientation).' WHERE (SELECT status FROM spots WHERE id = 'el-medano-playa-sur-leocadio-machado') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('pozo-izquierdo', 'Pozo Izquierdo', 'pozo|el arenal|playa de pozo izquierdo|pozo izquierdo', 27.82178, -15.42335, 'Spain', 'sea', 110, 'guide', 'windsurf', 'At high tide the wave breaks directly on the rocky shore, which makes entry and exit tricky and risks gear damage. At low tide the water is often choppy and messier without swell. With an Atlantic swell the waves can get big.', 'Loose lava boulders at the water''s edge; shorebreak on rocks at high tide; very strong, gusty wind; big waves when swell meets wind. Expert spot. Wave riders and PWA events crowd the water in summer. Don''t swim beyond the Ribanzo jetties: risk of being hit by a windsurfer.', 'Kitesurfing is reported as prohibited in Pozo Izquierdo bay; kiters use Salinas de Tenefé (Pozo south) instead. Venue of the PWA Windsurf World Cup (usually July–August), when the water is reserved for the event.', 'Launch from the main beach, El Arenal, in front of the Centro Internacional de Windsurfing (car parks, shops, schools). The beach is unofficially reserved for windsurfers. Entry and exit over loose dark lava boulders, so booties are recommended. Swimmers belong in the sheltered Playa del Ribanzo cove, behind the jetties.', 'Year-round, best May–September (strongest trade winds June–August); calmer, more easterly winds in winter.', 'seed', 'https://www.hellocanaryislands.com/windsurfing/gran-canaria/windsurfing-at-pozo-izquierdo|https://www.surf-magazin.de/en/spots-and-areas/international/spain/pozo-vargas-and-co-the-best-windsurfing-spots-on-gran-canaria/|https://kitejungle.com/kite-places/spain/salinas-tenefe-pozo-izquierdo|https://www.gran-canaria-info.com/en/blog/gran-canaria-beaches-pozo-izquierdo-beach', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'pozo-izquierdo' AND (SELECT status FROM spots WHERE id = 'pozo-izquierdo') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'pozo-izquierdo', 'NE', 'best', 'Reference trade wind (alisio). Cross-onshore from the left. Funnelled by the island''s relief, it is often very strong in summer (sometimes up to ~50 kn). Makes downwind wave riding technical.' WHERE (SELECT status FROM spots WHERE id = 'pozo-izquierdo') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'pozo-izquierdo', 'NNE', 'ok', 'Northerly variant of the trade wind; usable but less established than NE.' WHERE (SELECT status FROM spots WHERE id = 'pozo-izquierdo') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'pozo-izquierdo', 'ENE', 'ok', 'Usable trade wind, more onshore.' WHERE (SELECT status FROM spots WHERE id = 'pozo-izquierdo') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'pozo-izquierdo', 'E', 'marginal', 'Winter trade wind shifts east: lighter, less funnelled at Pozo. Southern spots (Bahía Feliz, Playa del Águila) are often better then.' WHERE (SELECT status FROM spots WHERE id = 'pozo-izquierdo') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'pozo-izquierdo', 'W', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'pozo-izquierdo') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('guincho', 'Guincho', 'praia do guincho|guincho beach|guincho', 38.73166, -9.47414, 'Portugal', 'sea', 270, 'guide', 'kitesurf|windsurf|wingfoil', 'Mid-low to mid-high tide is best: waves break on the outside and leave flat planing water between sets. At high tide the shorebreak and waves can be very powerful.', 'Rocks at both ends and in the middle of the beach, on the sand and in the water. Strong currents and rip currents: one narrow rip in the middle of the beach running out at an angle, another next to the rocks. Heavy swell and shorebreak. Gusty wind. Busy with surfers. Suited to intermediate and expert riders.', '', 'Wide sandy beach about 100 m deep with plenty of space. Launch in the middle of the beach, north or south of the central rocks. You can exit at either end. Keep to the northern side so you stay out of the surfers'' way.', 'May-September (July-August best). Usable April-October.', 'seed', 'https://se.kiteforum.com/kitesurf/spot/guincho|https://kitejungle.com/kite-places/portugal/praia-do-guincho|https://waterwind.it/new/en/windsurfing/spots/spots-reviews/265-world-other-countries/976-praia-do-guincho-portugal.html', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'guincho' AND (SELECT status FROM spots WHERE id = 'guincho') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'guincho', 'N', 'best', 'Reference direction: the summer Nortada blows side-shore and is strengthened by a thermal effect from the Sintra hills. Usually 15-25 kn, sometimes 35-40 kn, and often gusty.' WHERE (SELECT status FROM spots WHERE id = 'guincho') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'guincho', 'NNW', 'best', 'Side-shore to slightly cross-on from the right. This is the typical summer thermal direction.' WHERE (SELECT status FROM spots WHERE id = 'guincho') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'guincho', 'NW', 'ok', 'Cross-onshore from the right. Rideable, but the sea gets rougher with swell.' WHERE (SELECT status FROM spots WHERE id = 'guincho') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'guincho', 'WNW', 'ok', 'Cross-onshore. Expect a gusty thermal that swings between WNW and NW.' WHERE (SELECT status FROM spots WHERE id = 'guincho') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'guincho', 'W', 'ok', 'Listed as a working direction in spot guides. It is onshore, so expect heavy waves and shorebreak.' WHERE (SELECT status FROM spots WHERE id = 'guincho') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'guincho', 'NNE', 'marginal', 'On very hot days the wind veers cross-offshore NNE. It is very gusty.' WHERE (SELECT status FROM spots WHERE id = 'guincho') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'guincho', 'NE', 'forbidden', 'Offshore. When it gets too hot the wind can turn NE/E and then die completely.' WHERE (SELECT status FROM spots WHERE id = 'guincho') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'guincho', 'E', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'guincho') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('lagoa-de-obidos', 'Lagoa de Óbidos', 'óbidos lagoon|lagoa de óbidos este|bom sucesso|foz do arelho (lagoon side)|lagoa de óbidos', 39.41, -9.2, 'Portugal', 'lagoon', NULL, 'guide', 'kitesurf|windsurf|wingfoil', 'Tidal lagoon; mid to high tide preferred. Low tide exposes sandbanks: long fins catch, you may end up walking, and the top of the lagoon is unusable. Inside the lagoon it works on both tides but gets choppy with strong current at high tide. At Foz do Arelho, high tide brings a heavy shore break on the ocean side.', 'Strong currents at the estuary mouth. Sandbars and very shallow water at low tide. Sea urchins and seaweed inside the lagoon (wear booties). Gusty winds from S and E. Ocean-side shore break at Foz do Arelho can be big and powerful in swell. Many swimmers in summer.', 'Seasonal ban: kiting prohibited in the estuary and northern lagoon in summer (TheKiteSpot gives 15 Jun-15 Sep for the top of the lagoon). Kiting not officially allowed at Foz do Arelho in high summer due to swimmers. Designated kite/wingfoil zones and a teaching zone exist.', 'Most riders launch near Foz do Arelho on the lagoon side. In summer, when kiting is banned in the estuary and northern lagoon, use the windsurf school area (''Este'') or Praia do Bom Sucesso / Vau on the far bank. North end near Bom Sucesso: sandy beach, flat water, beginners. Inside lagoon: pebble beach. Respect the school/teaching zone and ride upwind of it.', 'April to October; June to September for the most reliable Nortada.', 'seed', 'https://locations.thekitespot.com/locations/kitesurf-obidos-lagoon-portugal|https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/lagoa-de-obidos-regiao-centro-portugal.html|https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/foz-do-arelho-regiao-centro-portugal.html', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'lagoa-de-obidos' AND (SELECT status FROM spots WHERE id = 'lagoa-de-obidos') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lagoa-de-obidos', 'N', 'best', 'Summer Nortada thermal, usually 15-20 kn, starts around 1 pm; hills funnel it down the lagoon, venturi effect strengthens it. Steady and reliable.' WHERE (SELECT status FROM spots WHERE id = 'lagoa-de-obidos') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lagoa-de-obidos', 'NNW', 'best', 'Nortada variant, funnelled down the lagoon; described as cross-shore.' WHERE (SELECT status FROM spots WHERE id = 'lagoa-de-obidos') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lagoa-de-obidos', 'NW', 'ok', 'Works; cross-onshore at Foz do Arelho.' WHERE (SELECT status FROM spots WHERE id = 'lagoa-de-obidos') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lagoa-de-obidos', 'SW', 'ok', 'Cross-shore at Foz do Arelho; one of its reference directions.' WHERE (SELECT status FROM spots WHERE id = 'lagoa-de-obidos') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lagoa-de-obidos', 'S', 'marginal', 'Land wind, mostly off-season; gusty.' WHERE (SELECT status FROM spots WHERE id = 'lagoa-de-obidos') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lagoa-de-obidos', 'E', 'marginal', 'Rideable on the lagoon but gusty; strengthened by nearby hills.' WHERE (SELECT status FROM spots WHERE id = 'lagoa-de-obidos') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('esposende-cavado-river-ofir', 'Esposende – Cávado River / Ofir', 'esposende, cavado river|rio cávado|ofir|restinga de ofir|esposende – cávado river / ofir', 41.525, -8.787, 'Portugal', 'estuary', 45, 'guide', 'kitesurf|windsurf', 'Tidal estuary. At low tide the flat-water area shrinks to a small shallow zone. At high tide the current can be strong and there is shore break on the sea side.', 'Strong tidal current at certain times of the high tide. Shore break at high tide. Waves on the sea side, medium between Ofir''s two breakwaters and bigger with swell. The river spot is crowded with beginners. Boat traffic from the school shuttles.', 'A marked kite zone is in place during the summer months. The narrow road from the town to the beach closes seasonally. Check with the local schools for current zoning.', 'Main launch: the sand beach at the tip of the Ofir spit, inside the nature reserve on the south bank of the Cávado across from the town. Kite schools run boat transfers from Esposende. By land it is a long walk from the beach parking, up to an hour. You can also launch from the town side. The river gets crowded with beginners, so give school lessons room.', 'April to October. Best from May or June to September, when the thermal Nortada blows.', 'seed', 'https://locations.thekitespot.com/locations/kitesurf-esposende-cavado-river-portugal|https://kitejungle.com/kite-places/portugal/ofir-esposende|https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/ofir-regiao-norte-portugal.html|https://lapointcamps.com/blog/kite-surf-sup-and-wake-in-esposende', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'esposende-cavado-river-ofir' AND (SELECT status FROM spots WHERE id = 'esposende-cavado-river-ofir') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'esposende-cavado-river-ofir', 'N', 'best', 'Nortada, the summer north wind boosted by afternoon thermals. Flat water in the river. Reported as weaker than at Viana do Castelo.' WHERE (SELECT status FROM spots WHERE id = 'esposende-cavado-river-ofir') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'esposende-cavado-river-ofir', 'NNW', 'best', 'Summer thermal flow, mostly N to NW according to the guides.' WHERE (SELECT status FROM spots WHERE id = 'esposende-cavado-river-ofir') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'esposende-cavado-river-ofir', 'NW', 'ok', 'Common summer direction (around 292-306° in monthly statistics). Usable in the river and on the sea side.' WHERE (SELECT status FROM spots WHERE id = 'esposende-cavado-river-ofir') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('torbole-conca-d-oro-lake-garda', 'Torbole (Conca d''Oro), Lake Garda', 'torbole sul garda|conca d''oro|molo paradiso|circolo surf torbole|torbole (conca d''oro), lake garda', 45.8718, 10.8725, 'Italy', 'lake', 225, 'guide', 'windsurf|wingfoil|kitesurf|sailing', '', 'Very crowded water in front of Conca d''Oro in summer. Public ferries (stay 200 m away). Regattas and race courses. Pebble beach. Gusty, side-off wind near shore in Pelèr. Ora chop up to about 1 m.', 'Garda Trentino kite rules: official lift service only, at least 200 m from shore and from public transport boats, no kiting during regattas, good weather only, wind up to 16 m/s. 1 Mar-9 Oct: kiting allowed from sunrise to 10:30 and from 16:30 to sunset, banned at midday, and only in designated areas after 18:00. 10 Oct-28 Feb: allowed from sunrise to sunset everywhere in Garda Trentino.', 'Windsurf and wing launch from Conca d''Oro / Molo Paradiso or from the Circolo Surf Torbole beach. There is a large lawn to rig on, a bar and parking nearby. The beach is pebbly, with a rubber mat to protect gear. Wind is steadier 50-70 m out. To avoid crowds, go upwind towards the tunnel or cross to Casa della Trota. Kitesurf: shore launches are not allowed. You must use an official boat lift service (Surf Segnana Torbole, Sailing Du Lac Riva) and stay at least 200 m from shore.', 'March-October for the Ora. Spring (April-June) has better wind and fewer crowds. Summer is the most crowded.', 'seed', 'https://gardatrentino.it/en/outdoor/water-sports/kitesurfing|https://360gardalife.com/en/magazine/where-to-windsurf-lake-garda-spot-freestyle/|https://www.waterwind.it/new/en/windsurfing/spots/spots-reviews/249-torbole-northern-garda-lake-italy.html', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'torbole-conca-d-oro-lake-garda' AND (SELECT status FROM spots WHERE id = 'torbole-conca-d-oro-lake-garda') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'torbole-conca-d-oro-lake-garda', 'S', 'best', 'Ora: thermal southerly, from roughly 12-13h until late afternoon on sunny days, March-October. Typically 20-25 kn on good days, with up to 1 m of chop. It strengthens towards the north of the lake. Clouds or low pressure weaken it.' WHERE (SELECT status FROM spots WHERE id = 'torbole-conca-d-oro-lake-garda') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'torbole-conca-d-oro-lake-garda', 'SSW', 'best', 'Ora sector, side-on to onshore along the north shore. Main direction for slalom, freeride and the One Hour Classic crossings to Casa della Trota.' WHERE (SELECT status FROM spots WHERE id = 'torbole-conca-d-oro-lake-garda') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'torbole-conca-d-oro-lake-garda', 'N', 'ok', 'Pelèr: strong northerly from dawn to mid-morning (about 7-11h, varies by season), strongest in the north (Torbole, Malcesine). Side-off near the beach, so the wind is gusty close to shore.' WHERE (SELECT status FROM spots WHERE id = 'torbole-conca-d-oro-lake-garda') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'torbole-conca-d-oro-lake-garda', 'NNE', 'marginal', 'Pelèr sector, side-off to offshore from the beach. Experienced riders only, and the morning kite windows apply.' WHERE (SELECT status FROM spots WHERE id = 'torbole-conca-d-oro-lake-garda') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('lo-stagnone', 'Lo Stagnone', 'stagnone di marsala|laguna dello stagnone|riserva naturale isole dello stagnone|birgi|lo stagnone', 37.8443, 12.46476, 'Italy', 'lagoon', 270, 'guide', 'kitesurf|windsurf|wingfoil', 'Practically no tide. Water level depends on wind: northerlies push water south (shallower spots), southerlies raise it slightly. Usually max about 1 m, often under 50 cm.', 'Very shallow water (often under 50 cm): be careful with jumps and falls. Muddy, silty bottom with seagrass, reeds, rocks and shells that can cut: wear booties. Occasional jellyfish. Gusty Scirocco. Crowded in summer, with many schools and students.', 'Nature reserve (since 1984) and Natura 2000 SIC/ZPS. Kiting is regulated by Capitaneria di Porto Marsala ordinances (zones and entry/exit corridors). Ride beyond 300 m from shore, 200 m inside the reserve. Helmet, buoyancy vest and line cutter required. Hydrofoils banned. Minimum age 14. Legal status contested since 2024 (Legambiente says kiting conflicts with the reserve rules).', 'Launch from the school/kite-centre areas on the east shore (Birgi and Contrada Spagnola, e.g. Kite Club Marsala, Pro Kite, the ''Kiter Wiese'' at Santa Maria in the north). Firm sand or grass rigging areas, knee- to waist-deep water. A kite pass from the centres is usually needed. Advanced riders ride further out and leave the inner zone to students.', 'High season June-September (daily thermal wind). Mid season April-May and October (often stronger wind). Kiting possible March-November.', 'seed', 'https://locations.thekitespot.com/locations/kitesurf-marsala-lo-stagnone-sicily-italy|https://matosurf.com/en/destinations/lo-stagnone/|http://www.iksurfmag.com/?p=26038|https://tp24.it/2024/07/05/cronaca/legambiente-announces-kitesurfing-ban-in-marsala-s-stagnone-lagoon/205960', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'lo-stagnone' AND (SELECT status FROM spots WHERE id = 'lo-stagnone') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lo-stagnone', 'NW', 'best', 'Maestrale/Mistral, the main summer direction, often thermally boosted, about 16-20 kn from spring to autumn. Flat water behind the salt-pan walls and Isola Lunga.' WHERE (SELECT status FROM spots WHERE id = 'lo-stagnone') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lo-stagnone', 'WNW', 'best', 'Part of the Maestrale/thermal sector. Flat, shallow water.' WHERE (SELECT status FROM spots WHERE id = 'lo-stagnone') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lo-stagnone', 'N', 'ok', 'Tramontana works. Northerly wind pushes water south, so some areas get shallower.' WHERE (SELECT status FROM spots WHERE id = 'lo-stagnone') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lo-stagnone', 'W', 'ok', 'Listed as working by spot guides. Onshore at east-shore launches.' WHERE (SELECT status FROM spots WHERE id = 'lo-stagnone') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lo-stagnone', 'SW', 'ok', 'Listed as working by spot guides.' WHERE (SELECT status FROM spots WHERE id = 'lo-stagnone') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lo-stagnone', 'S', 'ok', 'Works. Southerly wind raises the water level slightly.' WHERE (SELECT status FROM spots WHERE id = 'lo-stagnone') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lo-stagnone', 'SE', 'ok', 'Scirocco, warm and gusty, can go over 30 kn (big-air days). Mostly in spring and autumn.' WHERE (SELECT status FROM spots WHERE id = 'lo-stagnone') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'lo-stagnone', 'E', 'marginal', 'Not documented by sources. Estimated from beach orientation: offshore at the east-shore launches (Birgi and Contrada Spagnola schools). Confirm locally.' WHERE (SELECT status FROM spots WHERE id = 'lo-stagnone') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('porto-pollo', 'Porto Pollo', 'portu puddu|isola dei gabbiani|isuledda|porto pollo', 41.1899, 9.3253, 'Italy', 'sea', NULL, 'guide', 'kitesurf|windsurf|wingfoil|sailing', 'Very small Mediterranean tide. The kite beach is described as mainly unaffected by tides.', 'Very crowded in the summer holidays. The isthmus splits the area, so it divides the two zones. Strong Mistral days bring chop and waves up to about 2 m in the windward bay. Shore break is none to slight. Swimmers are in marked zones.', 'Kitesurfing and windsurfing have separate zones. Kiting and windsurfing are not allowed in the marked swimming areas of both bays. No specific municipal ordinance (Comune di Palau) was found online, so check with the local centres.', 'Sandy beaches on both sides of the narrow sand isthmus that joins Isola dei Gabbiani to the mainland. Kite zone: the west bay, on the left side of the peninsula, about 10 min walk from the windsurf centres. It has a big open launch beach and a mobile kite centre. Windsurf zone: the other bay, with direct launch from the centres (Sporting Club Sardinia, MB-Pro Center). Several car parks near the isthmus. Kites and windsurfers use separate zones, so stay in yours.', 'April to October/November. The most planing days are in April-May and October-November; June-September is peak season with reliable thermally boosted Ponente. Water is around 16°C in April (4/5 mm wetsuit).', 'seed', 'https://www.windfinder.com/spotguide/porto_pollo|https://www.surf-magazin.de/en/spots-and-areas/international/italy/spot-guide-windsurfing-spot-porto-pollo-in-sardinia/|https://www.sportif.travel/destinations/133/Greece_and_Mediterranean/Sardinia_-_Porto_Pollo|https://sardegnaturismo.it/it/esplora/porto-pollo', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'porto-pollo' AND (SELECT status FROM spots WHERE id = 'porto-pollo') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'porto-pollo', 'W', 'best', 'Ponente, the main summer wind. A jet effect through the Strait of Bonifacio speeds it up; usually 15-30 kn (4-8 Bft). Cross to cross-onshore from the left in the west (kite) bay. The bay downwind of the isthmus stays flat.' WHERE (SELECT status FROM spots WHERE id = 'porto-pollo') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'porto-pollo', 'WNW', 'best', 'Reference sector between Ponente and Mistral. You get bump & jump on the windward side of the isthmus and flat water on the lee side.' WHERE (SELECT status FROM spots WHERE id = 'porto-pollo') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'porto-pollo', 'NW', 'ok', 'Mistral. Can go over 30 kn, with gusts to around 40 kn, and can build waves up to about 2 m. For experienced riders.' WHERE (SELECT status FROM spots WHERE id = 'porto-pollo') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'porto-pollo', 'N', 'ok', 'Tramontana. Often weaker, around 10 kn on average according to the regional tourist board.' WHERE (SELECT status FROM spots WHERE id = 'porto-pollo') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'porto-pollo', 'E', 'ok', 'Levante is listed as a working wind, using the bay on the other side of the isthmus. Not confirmed for the west kite bay, where it may blow side-off or offshore. Check locally.' WHERE (SELECT status FROM spots WHERE id = 'porto-pollo') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'porto-pollo', 'S', 'forbidden', 'Inferred, not stated by any source: the spot is on the north coast, so a south wind blows off the mainland (offshore).' WHERE (SELECT status FROM spots WHERE id = 'porto-pollo') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('prasonisi', 'Prasonisi', 'prasonissi|prassonisi|prasonisi beach|prasonisi', 35.8813, 27.7633, 'Greece', 'sea', 285, 'guide', 'kitesurf|windsurf|wingfoil', 'Tide range is negligible in this part of the Mediterranean. The level changes with the seasons: in winter the water covers the sandbar, in summer the sand strip is exposed.', 'East side: very strong offshore wind downwind of the spot, with drift out to open sea. West side: steep, punchy waves of 1-2 m or more over the sandbar, with moderate shorebreak. Coral heads reported in the launch area. Shallow channel between the two beaches. Fast windsurfers close to shore. The centres run a rescue boat and a manned watchtower during opening hours.', '', 'Sand tombolo with two back-to-back bays. Kiters mainly use the west wave/onshore beach. Windsurf and wing schools (e.g. Procenter, Prasonisi Windsurf Centre) work on the east flat-water beach in cross-offshore wind. A shallow, standable strip about 20 m wide runs along the sandbar. In July-August the east side is crowded with windsurf students in the afternoons, so keep clear of the teaching area.', 'May to mid-October. Best June-September; strongest and most consistent in July-August (Meltemi). Facilities close outside roughly April-October.', 'seed', 'https://boards.co.uk/travel/world-travel/prasonisi-greece.html|https://charlieontravel.com/?p=16821|https://www.sportif.travel/destinations/88/Greece_and_Mediterranean/Rhodes_-_Prasonisi', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'prasonisi' AND (SELECT status FROM spots WHERE id = 'prasonisi') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'prasonisi', 'NW', 'best', 'Meltemi, sped up by a local venturi. Typically 15-30 kn in summer. Onshore on the west (wave) side, strong cross/side-offshore on the east (flat) side.' WHERE (SELECT status FROM spots WHERE id = 'prasonisi') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'prasonisi', 'WNW', 'best', 'Onshore to cross-onshore on the west wave beach. The east side stays flat.' WHERE (SELECT status FROM spots WHERE id = 'prasonisi') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'prasonisi', 'NNW', 'ok', 'Meltemi variant. Cross-onshore on the west beach.' WHERE (SELECT status FROM spots WHERE id = 'prasonisi') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'prasonisi', 'N', 'ok', 'Meltemi from the north. Side-shore on the west beach, offshore on the east beach.' WHERE (SELECT status FROM spots WHERE id = 'prasonisi') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'prasonisi', 'W', 'ok', 'Onshore on the west wave beach.' WHERE (SELECT status FROM spots WHERE id = 'prasonisi') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'prasonisi', 'E', 'forbidden', 'Offshore on the west wave beach. The next stop downwind is open sea.' WHERE (SELECT status FROM spots WHERE id = 'prasonisi') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'prasonisi', 'SE', 'forbidden', 'Offshore on the west wave beach.' WHERE (SELECT status FROM spots WHERE id = 'prasonisi') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('vassiliki', 'Vassiliki', 'vasiliki|vass|vassiliki bay|ponti|vassiliki', 38.63, 20.602, 'Greece', 'sea', 180, 'guide', 'windsurf|sailing', 'Tidal range is negligible, so the tide does not matter. Sources report no tide and no hidden obstacles under the surface.', 'Crowded water in season. Strong gusts off the western spit in NW wind. The wind can drop completely in the evening, leaving sailors stranded and needing rescue. Yachts anchor off Ponti. Ferries to Kefalonia/Ithaca use Vassiliki harbour on the east side in summer.', 'Kitesurfing is banned in Vassiliki all year. The nearest kite spot on Lefkada is Agios Ioannis (Milos beach) in the north.', 'The pebble beach at the north of the bay, between Vassiliki village (east) and Ponti (west), is lined with windsurf centres. It is waist-deep with a sand bottom and a sandbar about 50 m out, which is good for beach starts. Launch from the centres'' sections. The bay is very busy in season, with 100+ sailors at once.', 'Late May to October. June, July and August are the most consistent for Eric. May and September are quieter with less wind.', 'seed', 'https://www.surf-magazin.de/en/spots-and-areas/international/greece/vasiliki-milos-and-co-the-best-windsurfing-spots-on-lefkada/|https://web.kite-and-windsurfing-guide.com/europe/greece/lefkada-ionian-islands.html|https://boards.co.uk/travel/world-travel/vassiliki-greece.html|https://www.windsurf.co.uk/micro-guide-ocean-elements-vassiliki-lefkas-greece', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'vassiliki' AND (SELECT status FROM spots WHERE id = 'vassiliki') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'vassiliki', 'W', 'best', 'Afternoon thermal ''Eric'': cross-shore from the right (starboard tack out). Usually 15-20 kn and F5-6, with F7 and 25-30 kn days not unusual. Clouds over the western mountains signal that it is coming.' WHERE (SELECT status FROM spots WHERE id = 'vassiliki') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'vassiliki', 'WNW', 'ok', 'The NW gradient wind boosts Eric. It comes over the spit on the west side of the bay, so expect gusts.' WHERE (SELECT status FROM spots WHERE id = 'vassiliki') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'vassiliki', 'NW', 'marginal', 'Gusts strongly down over the long spit that closes the bay to the west. Side-off and gusty near Ponti.' WHERE (SELECT status FROM spots WHERE id = 'vassiliki') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'vassiliki', 'S', 'ok', 'Gentle onshore sea breeze (F1-2) from about 10:00. Good for beginners and light-wind freestyle on the shallow sandbar.' WHERE (SELECT status FROM spots WHERE id = 'vassiliki') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'vassiliki', 'N', 'forbidden', 'Offshore: the beach faces south, so north wind blows out to sea.' WHERE (SELECT status FROM spots WHERE id = 'vassiliki') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('brouwersdam', 'Brouwersdam', 'brouwersdam noordzeezijde|brouwersdam ouddorp|renesse / brouwersdam|brouwersdam', 51.7625, 3.854, 'Netherlands', 'sea', 300, 'guide', 'kitesurf|windsurf|wingfoil|sailing', 'Low tide gives flat water and standing depth in the shallows, good for learning. High tide brings small waves and a stronger current. Waves only build at high tide in stormy W to NW wind.', 'Chop builds with onshore wind. Stronger current at high tide. Very busy on windy weekends, with schools, windsurfers and beach users. Respect the buoyed zones and swimmers.', 'Kitesurfing is only allowed in the signposted kite zone on the North Sea side of the dam, marked by yellow buoys up to pavilion De Kous. A 2013 Goeree-Overflakkee decree banned kiting along the coast apart from this Brouwersdam strip; it expired in July 2023. Check the current local signs.', 'Main launch is on the North Sea beach around the middle of the 6.5 km dam. The kite zone, marked by yellow buoys, runs south to the beach pavilion De Kous. The beach at the north end, near the parking by the water, is for windsurfing only. A bay past the slipway at the north end of the dam is tolerated for kiting but not officially allowed. Free parking, large rigging space, shallow shoreline.', 'Apr-May and Sep-Oct are best; usable all year. Schools operate roughly late March to early November.', 'seed', 'https://web.kite-and-windsurfing-guide.com/europe/netherlands.html|https://www.kiteboarding-club.com/en/brouwersdam/|https://www.kiteboarding-club.com/en/kite-school-brouwersdam-faq/|https://lokaleregelgeving.overheid.nl/CVDR307403/1', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'brouwersdam' AND (SELECT status FROM spots WHERE id = 'brouwersdam') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'brouwersdam', 'SSW', 'ok', 'Listed as ideal by local school KBC; side-shore along the dam.' WHERE (SELECT status FROM spots WHERE id = 'brouwersdam') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'brouwersdam', 'SW', 'best', 'Reference direction with W/NW, from Atlantic lows over the British Isles.' WHERE (SELECT status FROM spots WHERE id = 'brouwersdam') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'brouwersdam', 'WSW', 'best', 'Side-on to onshore; choppy North Sea conditions.' WHERE (SELECT status FROM spots WHERE id = 'brouwersdam') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'brouwersdam', 'W', 'best', 'Onshore; stronger wind = more chop. Waves mainly at high tide in stormy W-NW.' WHERE (SELECT status FROM spots WHERE id = 'brouwersdam') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'brouwersdam', 'WNW', 'best', 'Onshore; most common strong-wind direction after low pressure moves east.' WHERE (SELECT status FROM spots WHERE id = 'brouwersdam') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'brouwersdam', 'NW', 'best', 'Onshore; offshore sandbars about 5 km out limit swell to about 1 m.' WHERE (SELECT status FROM spots WHERE id = 'brouwersdam') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'brouwersdam', 'NNW', 'ok', 'Side-on.' WHERE (SELECT status FROM spots WHERE id = 'brouwersdam') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'brouwersdam', 'N', 'ok', 'Listed as working by Windfinder and KBC; side-shore along the dam.' WHERE (SELECT status FROM spots WHERE id = 'brouwersdam') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'brouwersdam', 'NNE', 'ok', 'Listed as ideal by KBC; nearly parallel to the shore.' WHERE (SELECT status FROM spots WHERE id = 'brouwersdam') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'brouwersdam', 'ESE', 'forbidden', 'Offshore on the North Sea side. Schools move to the Grevelingen side (Bruinisse) instead.' WHERE (SELECT status FROM spots WHERE id = 'brouwersdam') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'brouwersdam', 'E', 'forbidden', 'Offshore on the North Sea side. Schools move to the Grevelingen side (Bruinisse) instead.' WHERE (SELECT status FROM spots WHERE id = 'brouwersdam') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'brouwersdam', 'SE', 'forbidden', 'Offshore on the North Sea side. Schools move to the Grevelingen side (Bruinisse) instead.' WHERE (SELECT status FROM spots WHERE id = 'brouwersdam') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('wijk-aan-zee', 'Wijk aan Zee', 'wijk aan zee noordpier|noordpier|de hangout kitespot|wijk aan zee', 52.4825, 4.5813, 'Netherlands', 'sea', 285, 'guide', 'kitesurf|windsurf', 'Waves depend heavily on the tide and can build sharply at high water. Plan your session around the tide.', 'Rip currents close to the jetty. Crowded with windsurfers, kiters and surfers. A sudden turn to offshore wind has led to KNRM rescues. Water pollution has been reported near the industrial harbour and steel works. Theft from cars has been reported.', '', 'Launch from the beach north of the Noordpier, near the beach bars and surf schools. The car park is behind the dunes, so expect a long walk to the beach. Guides mention two more launches further north along the coast. Local schools include Kiteflow and Ozlines. The spot is often crowded with windsurfers and kitesurfers, so keep your distance.', 'Rideable all year. Waves are usually smaller in summer.', 'seed', 'https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/wijk-aan-zee-noord-holland-netherlands.html|https://www.windfinder.com/forecast/wijk_aan_zee_de_hangout_kitespot|https://www.surf-forecast.com/breaks/Wijkaan-Zee-Noordpier|https://www.nhnieuws.nl/nieuws/267982/kitesurfers-uit-zee-gered-bij-wijk-aan-zee-wind-draaide-plotseling-naar-aflandig', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'wijk-aan-zee' AND (SELECT status FROM spots WHERE id = 'wijk-aan-zee') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wijk-aan-zee', 'SW', 'best', 'Cross-shore. Gives the biggest waves at the spot.' WHERE (SELECT status FROM spots WHERE id = 'wijk-aan-zee') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wijk-aan-zee', 'S', 'ok', 'Gives the cleanest waves, which wrap around the 400 m harbour wall. Needs more wind, and the pier may block some of it.' WHERE (SELECT status FROM spots WHERE id = 'wijk-aan-zee') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wijk-aan-zee', 'WSW', 'ok', '' WHERE (SELECT status FROM spots WHERE id = 'wijk-aan-zee') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wijk-aan-zee', 'W', 'ok', 'Onshore to cross-onshore. Expect choppy conditions.' WHERE (SELECT status FROM spots WHERE id = 'wijk-aan-zee') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wijk-aan-zee', 'NW', 'ok', 'The most common wind direction here. The beach also takes swell from SW to N.' WHERE (SELECT status FROM spots WHERE id = 'wijk-aan-zee') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wijk-aan-zee', 'N', 'ok', 'Windfinder lists the De HangOut kitespot as working in northerly winds.' WHERE (SELECT status FROM spots WHERE id = 'wijk-aan-zee') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wijk-aan-zee', 'E', 'forbidden', 'Offshore. KNRM has rescued kiters here after the wind suddenly turned offshore.' WHERE (SELECT status FROM spots WHERE id = 'wijk-aan-zee') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wijk-aan-zee', 'SE', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'wijk-aan-zee') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'wijk-aan-zee', 'NE', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'wijk-aan-zee') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('fehmarn-gold', 'Fehmarn Gold', 'gold / fehmarn|gold fehmarn|strand gold|fehmarn gold', 54.4246, 11.0972, 'Germany', 'sea', 240, 'guide', 'kitesurf|windsurf|wingfoil|sailing', 'No real tide (Baltic). The water is less than 1.5 m deep over a large area, so wind-driven water level changes affect how deep it is.', 'Rocky dike and groyne areas, plus a groyne next to the entrance. Shallow water with seagrass. Very crowded in summer, so collisions are a risk. Water gets too deep to stand between Gold and the opposite peninsula.', 'Separate kite zone. Follow right-of-way rules and sail with foresight, especially with summer crowds. Parking fee in summer.', 'Big parking area about 100 m from the water. You get to the water over a grass meadow. Kiters usually launch further right, windsurfers increasingly on the left. Kiters have their own zone. Watch out for the groyne to the left of the entrance (it is visible). Tim''s Beach (school and rental), toilets and Café Achterndiek are on site.', '', 'seed', 'https://www.windfinder.com/spotguide/gold|https://www.surf-magazin.de/spots/fehmarn-gold/|https://www.surf-magazin.de/en/spots-and-areas/baltic-sea/fehmarn-guide-the-best-windsurfing-spots-on-fehmarn/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'fehmarn-gold' AND (SELECT status FROM spots WHERE id = 'fehmarn-gold') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'fehmarn-gold', 'SW', 'best', 'Reference direction. Flat to small chop, short and steep, waves rarely above 0.5 m. Large shallow area where you can stand.' WHERE (SELECT status FROM spots WHERE id = 'fehmarn-gold') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'fehmarn-gold', 'WSW', 'best', 'Reference direction. Works well in south to west winds.' WHERE (SELECT status FROM spots WHERE id = 'fehmarn-gold') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'fehmarn-gold', 'W', 'best', 'Best direction according to surf-magazin. The headland 2 km upwind blocks the bigger waves in W to NW winds.' WHERE (SELECT status FROM spots WHERE id = 'fehmarn-gold') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'fehmarn-gold', 'WNW', 'ok', 'Usable. The headland upwind keeps the water fairly flat.' WHERE (SELECT status FROM spots WHERE id = 'fehmarn-gold') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'fehmarn-gold', 'NW', 'ok', 'Usable. The headland upwind keeps the water fairly flat.' WHERE (SELECT status FROM spots WHERE id = 'fehmarn-gold') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'fehmarn-gold', 'NNW', 'ok', 'surf-magazin gives south to west to NNW as the working range.' WHERE (SELECT status FROM spots WHERE id = 'fehmarn-gold') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'fehmarn-gold', 'S', 'ok', 'Works. You can sail across to the opposite peninsula, but the water in between is too deep to stand.' WHERE (SELECT status FROM spots WHERE id = 'fehmarn-gold') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'fehmarn-gold', 'N', 'marginal', 'surf-magazin lists north as working, but it is outside the main S-NNW range.' WHERE (SELECT status FROM spots WHERE id = 'fehmarn-gold') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'fehmarn-gold', 'E', 'forbidden', 'surf-magazin says easterly winds do not work (offshore here). One kite blog says Gold works in E, so check locally.' WHERE (SELECT status FROM spots WHERE id = 'fehmarn-gold') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('st-peter-ording', 'St. Peter-Ording', 'sankt peter-ording|spo|ording|ordinger strand|böhl|böhler strand|südstrand|st. peter-ording', 54.336, 8.587, 'Germany', 'sea', 270, 'guide', 'kitesurf|windsurf|wingfoil', 'Very tide-dependent. Shallow tideways form at low tide (good for beginners). Higher water brings waves on the outer sandbanks. Südstrand lagoon and Böhl only work about 2 h before to 2 h after high tide; at low water the sea runs out too far to ride. Distance from parking to the water can reach about 500 m. Storm surges can flood the beach car park.', 'Strong tidal current: runs north on the rising tide and south on the falling tide. Drift risk rises when wind and current line up. Reaching the outer sandbanks takes experience and fitness. The wave off Ording breaks unpredictably. Little real shorebreak thanks to the sandbanks. Can get crowded at the main beach at peak times.', 'Kitesurfing only inside the buoyed kite zones on either side of the swimming area. Kiting in the bathing zone is prohibited. Overnight camping and BBQs on the beach are prohibited. The beach lies at the edge of the Schleswig-Holstein Wadden Sea National Park.', 'Main area is Ordinger Strand, reached by car over a dike crossing. You can park and rig directly on the beach (parking fee). Kite zones lie left and right of the swimming area in front of the beach car park, marked with white/yellow buoys. Kiting in the swim zone is banned. Areas are shared with windsurfers: keep your distance and keep launch zones clear. Böhler Strand (south) is best for beginners: wide standing area, less traffic, but a longer walk.', 'Late March to early June and September to November. Windiest months: March, April, June, September, October, November. Year-round when not frozen.', 'seed', 'https://www.surf-magazin.de/en/spots-and-areas/north-sea/area-info-windsurfing-in-st-peter-ording/|https://www.kitemana.com/en-no/info/blog/kitespot-st-peter-ording-in-germany-1593|https://iksurfmag.com/travel-guides/europe/germany/sankt-peter-ording', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'st-peter-ording' AND (SELECT status FROM spots WHERE id = 'st-peter-ording') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'st-peter-ording', 'S', 'ok', 'Works at Südstrand and Böhl lagoon areas.' WHERE (SELECT status FROM spots WHERE id = 'st-peter-ording') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'st-peter-ording', 'SSW', 'ok', 'Side-on; usable on all beaches.' WHERE (SELECT status FROM spots WHERE id = 'st-peter-ording') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'st-peter-ording', 'SW', 'best', 'Cross-onshore. Best for the wave in front of Ording. SW storms bring the best wave riding. Ideal for the Südstrand lagoon.' WHERE (SELECT status FROM spots WHERE id = 'st-peter-ording') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'st-peter-ording', 'WSW', 'best', 'Prevailing direction; the spot works best.' WHERE (SELECT status FROM spots WHERE id = 'st-peter-ording') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'st-peter-ording', 'W', 'best', 'Onshore to cross-onshore. Good at the main beach and Südstrand.' WHERE (SELECT status FROM spots WHERE id = 'st-peter-ording') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'st-peter-ording', 'WNW', 'best', 'Cross-onshore; good at all beaches.' WHERE (SELECT status FROM spots WHERE id = 'st-peter-ording') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'st-peter-ording', 'NW', 'best', 'Very good at Ording/FKK beach and Böhl, especially in the last two hours of the rising tide.' WHERE (SELECT status FROM spots WHERE id = 'st-peter-ording') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'st-peter-ording', 'N', 'ok', 'Side-shore; works at the main beach (SW to N range).' WHERE (SELECT status FROM spots WHERE id = 'st-peter-ording') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'st-peter-ording', 'SE', 'marginal', 'Side-off. Guides list Südstrand/Böhl as working from SE, but use caution.' WHERE (SELECT status FROM spots WHERE id = 'st-peter-ording') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'st-peter-ording', 'E', 'forbidden', 'Offshore. Kiters should never go out in offshore wind. Windsurfers sometimes ride it because the beach is so wide, but there is a drift risk.' WHERE (SELECT status FROM spots WHERE id = 'st-peter-ording') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('sylt-westerland-brandenburger-strand', 'Sylt Westerland (Brandenburger Strand)', 'westerland|brandenburger strand|westerland hauptstrand|sylt westerland (brandenburger strand)', 54.9065, 8.3015, 'Germany', 'sea', 275, 'guide', 'kitesurf|windsurf', 'Runs cleanest around low tide: shorebreak and wave height near the shore stay moderate, and small flat-water pools form in places. As the tide rises the sets reach the shore and the shorebreak can get extreme at high tide. Tidal range is larger in westerly winds and at spring tides.', 'Powerful, mast-breaking shorebreak; short standing area; noticeable current across the whole area; stone groynes in the water (the remaining one is marked with yellow crosses). Wear a helmet and impact vest. Crowded in summer.', 'Inside the Schleswig-Holstein Wadden Sea National Park area. Seasonal bathing zones: with a green or yellow flag, windsurfing is restricted in the guarded bathing areas; with a red flag, water access is unrestricted. Stay out of swimming zones and away from groynes. Follow the zoning shown on beach signs.', 'Launch and land on Brandenburger Strand, the main beach in front of the Westerland promenade (GKA Kite World Cup and Windsurf World Cup venue). Keep clear of swimming zones and of the groynes on the west side. Check the information boards on the beach for current zones. Parking behind the dike gets crowded in summer.', 'Apr-Jun and Sep-Oct are best; windiest Oct-Mar.', 'seed', 'https://www.surf-magazin.de/en/spots-and-areas/north-sea/spot-guide-windsurfing-on-sylt-the-flat-water-and-wave-spots-at-a-glance/|https://www.kitemana.com/en-gb/info/blog/kitespot-sylt-1586|https://www.festivalsindeutschland.de/festival/gka-kite-world-cup-sylt', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'sylt-westerland-brandenburger-strand' AND (SELECT status FROM spots WHERE id = 'sylt-westerland-brandenburger-strand') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'sylt-westerland-brandenburger-strand', 'N', 'best', 'Sideshore along the west coast; at 20 kn and more it is a fun wave session (surf-magazin).' WHERE (SELECT status FROM spots WHERE id = 'sylt-westerland-brandenburger-strand') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'sylt-westerland-brandenburger-strand', 'NNE', 'best', 'Sideshore, cited with N as a reference direction for 20 kn+ sessions.' WHERE (SELECT status FROM spots WHERE id = 'sylt-westerland-brandenburger-strand') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'sylt-westerland-brandenburger-strand', 'NW', 'ok', 'Open North Sea; onshore leaning, so conditions are challenging with big shorebreak.' WHERE (SELECT status FROM spots WHERE id = 'sylt-westerland-brandenburger-strand') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'sylt-westerland-brandenburger-strand', 'W', 'ok', 'Straight onshore, typically 15-35 kn; rough, demanding conditions for experienced riders only.' WHERE (SELECT status FROM spots WHERE id = 'sylt-westerland-brandenburger-strand') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'sylt-westerland-brandenburger-strand', 'SW', 'best', 'Sideshore from S-SW at 20 kn+ gives good wave riding.' WHERE (SELECT status FROM spots WHERE id = 'sylt-westerland-brandenburger-strand') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'sylt-westerland-brandenburger-strand', 'S', 'best', 'Sideshore, cited with SW as a reference direction.' WHERE (SELECT status FROM spots WHERE id = 'sylt-westerland-brandenburger-strand') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'sylt-westerland-brandenburger-strand', 'E', 'forbidden', 'Fully offshore at Westerland.' WHERE (SELECT status FROM spots WHERE id = 'sylt-westerland-brandenburger-strand') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('hvide-sande', 'Hvide Sande', 'hvide sande nord|westwind nord|ringkøbing fjord / hvide sande nord|hvide sande', 56.0203, 8.1291, 'Denmark', 'lagoon', 90, 'guide', 'kitesurf|windsurf|wingfoil', 'The fjord is brackish and shallow, fed with seawater through the Hvide Sande sluice/harbour opening. It is mostly standing to chest depth. Ringkøbing Fjord is not really tidal.', 'Fishing nets and net poles. Bathers, dogs and children near shore. Short, unpleasant chop further out in strong wind. Gusts near shore in westerlies. At Hvide Sande Syd it gets very shallow near shore (risk of grounding, fin strikes). North Sea side: strong currents, always running outward along both harbour piers, can be life-threatening.', 'No formal kite zones are listed for Hvide Sande Nord. Windsurfing and kitesurfing are banned at the ''Betweens'' spot between the harbour moles on the North Sea side.', 'Fjord-side spot north of Hvide Sande, signposted for windsurfing. Large paid car park a few metres from a grass rigging area and a small sandy beach. Facilities: Westwind centre (school, rental, shop, showers, toilets, storage boxes). Busy with windsurfers, and kiters are asked to keep out of their way.', 'April–November. March–May and September–November are the windiest; summer winds are lighter. You always need a wetsuit.', 'seed', 'https://westwind.dk/en/pages/westwind-spot-guide-ringkoebing-fjord|https://www.surf-magazin.de/en/spots-and-areas/international/denmark/spot-guide-ringkobing-fjord-the-best-spots-around-hvide-sande-and-bork-havn/|https://se.kiteforum.com/kitesurf/spot/ringkobing_fjord___hvide_sande_nord', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'hvide-sande' AND (SELECT status FROM spots WHERE id = 'hvide-sande') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hvide-sande', 'W', 'ok', 'The reference wind per guides: westerlies with some north in them. Blows side-off/offshore over the dune strip, so it is gusty near shore and steadier further out. Shallow water reaches ~800 m out, and in an emergency you drift across to the fjord''s far shore.' WHERE (SELECT status FROM spots WHERE id = 'hvide-sande') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hvide-sande', 'WNW', 'ok', 'Westerlies with a northerly component work best. Gusty near shore. Choppy wind waves build further out in strong wind.' WHERE (SELECT status FROM spots WHERE id = 'hvide-sande') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hvide-sande', 'NW', 'ok', 'Usable on the fjord. Strong NW–N is also the wave-riding direction on the North Sea side at the south mole, for experts only.' WHERE (SELECT status FROM spots WHERE id = 'hvide-sande') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hvide-sande', 'SW', 'ok', 'Works, but the Hvide Sande Syd spot (55.9854, 8.1385) is rated better in SW.' WHERE (SELECT status FROM spots WHERE id = 'hvide-sande') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hvide-sande', 'E', 'marginal', 'Onshore. The local guide (Westwind) lists onshore winds as a hazard.' WHERE (SELECT status FROM spots WHERE id = 'hvide-sande') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('camber-sands-broomhill', 'Camber Sands (Broomhill)', 'camber|broomhill sands|kite beach camber|camber sands (broomhill)', 50.9299, 0.8136, 'United Kingdom', 'sea', 160, 'guide', 'kitesurf|windsurf|wingfoil', 'Very tidal (spring range around 8m). No kiting from 2.5–3 hours before to 2.5–3 hours after high tide, because the water reaches the sea defence wall and there is no launch area left. Flat tidal pools form on the rising and falling tide. Shore break and strong currents at high tide.', 'Sea defence wall and steps, granite rock boulders, wooden groynes, two shipwrecks at the east end (visible at low tide), MOD live firing range to the east, shore break and strong currents around high tide.', 'Only fly inside the designated kite zones, and keep to the separate teaching and freeride zones. Third-party insurance is required. No kiting at the Dunes end. Do not ride or enter the water in front of the MOD range when red flags are flying. No riding around high tide (council: 3 h either side). Water sports are not advised in offshore winds.', 'Launch in the designated Water Sports Zone in front of Broomhill Sands car park (free parking, Lydd Road, home of The Kitesurf Centre). Teaching zone runs from the black/white flag west to the first houses; freeride zone runs from the flag east to the MOD range. Kiting is banned at the Dunes end of Camber. Launch at least 50m (local guide: 75m) from people and hard hazards, ideally at the water''s edge.', 'Main riding season is March to November, busiest June to September (SW winds plus afternoon summer sea breezes). The windiest months are October to April.', 'seed', 'https://www.rother.gov.uk/leisure-and-events/beaches-and-coastline/camber-sands|https://iksurfmag.com/travel-guides/europe/united-kingdom/camber-sands|https://locations.thekitespot.com/locations/kitesurf-camber-sands-united-kingdom|https://thekitesurfcentre.com/about/location', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'camber-sands-broomhill' AND (SELECT status FROM spots WHERE id = 'camber-sands-broomhill') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'camber-sands-broomhill', 'SW', 'best', 'Prevailing direction, cross-onshore from the right looking out to sea.' WHERE (SELECT status FROM spots WHERE id = 'camber-sands-broomhill') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'camber-sands-broomhill', 'SSW', 'best', 'Cross-onshore; works well.' WHERE (SELECT status FROM spots WHERE id = 'camber-sands-broomhill') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'camber-sands-broomhill', 'S', 'best', 'Onshore; guides say any wind with ''S'' in it works (ESE to WSW).' WHERE (SELECT status FROM spots WHERE id = 'camber-sands-broomhill') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'camber-sands-broomhill', 'WSW', 'ok', 'Cross-shore; usable, quoted as the western limit of the working range.' WHERE (SELECT status FROM spots WHERE id = 'camber-sands-broomhill') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'camber-sands-broomhill', 'W', 'ok', 'Listed as a working direction by local guides; close to side-shore.' WHERE (SELECT status FROM spots WHERE id = 'camber-sands-broomhill') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'camber-sands-broomhill', 'SSE', 'ok', 'Onshore, usable.' WHERE (SELECT status FROM spots WHERE id = 'camber-sands-broomhill') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'camber-sands-broomhill', 'SE', 'ok', 'Listed as a working direction.' WHERE (SELECT status FROM spots WHERE id = 'camber-sands-broomhill') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'camber-sands-broomhill', 'ESE', 'marginal', 'Eastern limit of the working range; for easterlies the council points riders to Greatstone instead.' WHERE (SELECT status FROM spots WHERE id = 'camber-sands-broomhill') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'camber-sands-broomhill', 'NW', 'forbidden', 'Offshore. Council: ''Do not use this area'' in northwesterlies.' WHERE (SELECT status FROM spots WHERE id = 'camber-sands-broomhill') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'camber-sands-broomhill', 'N', 'forbidden', 'Offshore; water sports not advised in offshore winds. Use Greatstone in northerlies.' WHERE (SELECT status FROM spots WHERE id = 'camber-sands-broomhill') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('hunstanton', 'Hunstanton', 'old hunstanton|hunstanton beach|old hunstanton beach|hunstanton', 52.95172, 0.49548, 'United Kingdom', 'sea', 300, 'guide', 'kitesurf|windsurf', 'Can be sailed at all tides; medium tidal range. Low tide: flat lagoon behind the sandbar, good for freestyle but shallow. Mid tide: shallow and choppier. High tide on the main beach: water against the 4 m sea defences between wooden groynes, dangerous for kiters. Go to Old Hunstanton at high tide. The flood comes in fast over the sandbanks and can cut people off.', '4 m sea wall and old wooden groynes at high tide on the main beach. Sandbars and very shallow water at low tide. Fast incoming tide can strand people on the sandbanks. Strong unpredictable gusts: a kiter was lifted about 20 ft and seriously injured at Old Hunstanton. No lifeguards at Old Hunstanton.', '', 'Main beach in front of the town (New Hunstanton) at low tide. Old Hunstanton at mid to high tide: north of the resort, no sea wall, car park, toilets and café on site. Kite Eze (IKO school) teaches at Old Hunstanton, PE36 6JL. Sand bars and shallow flat water make it a good place to learn.', '', 'seed', 'https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/hunstanton-east-north-east-england-great-britain.html|https://bigsalty.com/en/windsurfing/guide/113/|https://www.beachlets.co.uk/?p=112980|https://hmcoastguard.uk/news/kitesurfers-20-foot-fall-race-against-time-and-tide-north-norfolk-coastguards', 0, 'spot')
