INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hunstanton', 'SW', 'best', 'Prevailing wind on the west-facing beach. Short fetch over The Wash, so the water stays flat.' WHERE (SELECT status FROM spots WHERE id = 'hunstanton') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hunstanton', 'W', 'best', 'Listed as one of the best directions. Flat water, good for freestyle and beginners.' WHERE (SELECT status FROM spots WHERE id = 'hunstanton') = 'seed';
