INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hunstanton', 'E', 'forbidden', 'Offshore for a W/NW-facing beach (deduced from the orientation; no guide states it explicitly).' WHERE (SELECT status FROM spots WHERE id = 'hunstanton') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hunstanton', 'SE', 'forbidden', 'Offshore for a W/NW-facing beach (deduced from the orientation; no guide states it explicitly).' WHERE (SELECT status FROM spots WHERE id = 'hunstanton') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('rhosneigr', 'Rhosneigr', 'traeth crigyll|rhosneigr town beach|traeth llydan|broad beach|rhosneigr', 53.2325, -4.5195, 'United Kingdom (Wales)', 'sea', 245, 'guide', 'kitesurf|windsurf|wingfoil', 'Rideable at all tides. Mid-tide is best: clean kickers and swell, plus room to rig. At high tide the beach is narrow and rigging space gets tight. From mid to low tide rocks are exposed, and windsurf guides warn of submerged rocks near high water. The best waves come on the incoming tide.', 'Strong rip and submerged rocks at the southern end of the bay. Rocks between Traeth Crigyll and Traeth Llydan. The river that cuts across the beach halfway up (near the dunes) has a strong rip after heavy rain. Wind shadow at high tide near Glan-y-Môr Road. Keep clear of sailing lanes marked by yellow buoys. Can get crowded on good days.', 'Anglesey Council seashore byelaws set an 8-knot speed limit for craft. Traeth Llydan is a launch site where launching fees apply to powered craft. No overnight van parking on Glan-y-Môr Road; campervans and motorhomes are restricted from 12:00 to 08:00.', 'Kitesurfers mostly use Traeth Crigyll, the northern town beach, and launch along Glan-y-Môr Road. At high tide there is a wind shadow near Glan-y-Môr Road, so launch further south near Funsport. Launch and ride well away from the rocks that split the two beaches. Surfers mostly use Traeth Llydan (Broad Beach) to the south. Parking on Glan-y-Môr Road and Beach Road fills early; park around the edges of the grass areas.', 'Windy all year. Spring and summer are milder. Best sessions come with S–SW wind and swell.', 'seed', 'https://www.northernwatersports.co.uk/pages/rhosneigr-kitesurfing-spot-guide|https://rhosneigr.co.uk/rhosneigr-anglesey-windsurfing/|https://rhosneigr.co.uk/best-kitesurfing-beaches-in-anglesey/|https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/rhosneigr-wales-bristol-channel-great-britain.html', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'rhosneigr' AND (SELECT status FROM spots WHERE id = 'rhosneigr') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'rhosneigr', 'S', 'best', 'Reference direction: cross-shore with wind funnelling down the coast, deep water and swell running along the beach. The classic big-air setup.' WHERE (SELECT status FROM spots WHERE id = 'rhosneigr') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'rhosneigr', 'SSW', 'best', 'Ideal for sideshore wave riding.' WHERE (SELECT status FROM spots WHERE id = 'rhosneigr') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'rhosneigr', 'SW', 'best', 'Prevailing wind, which speeds up between Wales and Ireland. Sideshore to cross-onshore wave conditions.' WHERE (SELECT status FROM spots WHERE id = 'rhosneigr') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'rhosneigr', 'WSW', 'ok', 'Onshore. Inside the SW–NW range that guides list as rideable.' WHERE (SELECT status FROM spots WHERE id = 'rhosneigr') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'rhosneigr', 'W', 'ok', 'Onshore. Inside the SW–NW range that guides list as rideable.' WHERE (SELECT status FROM spots WHERE id = 'rhosneigr') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'rhosneigr', 'WNW', 'ok', 'Inside the SW–NW range that guides list as rideable.' WHERE (SELECT status FROM spots WHERE id = 'rhosneigr') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'rhosneigr', 'NW', 'ok', 'Guides say NW can give very good wave conditions.' WHERE (SELECT status FROM spots WHERE id = 'rhosneigr') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'rhosneigr', 'N', 'marginal', 'Windsurf guides call N a good wave direction, but it runs side to side-off on a beach facing WSW. Check on site.' WHERE (SELECT status FROM spots WHERE id = 'rhosneigr') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'rhosneigr', 'NE', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'rhosneigr') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'rhosneigr', 'E', 'forbidden', 'Offshore. Blows over the village, so it is very gusty and full of holes.' WHERE (SELECT status FROM spots WHERE id = 'rhosneigr') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('dakhla-lagoon', 'Dakhla lagoon', 'dakhla bay|baie de dakhla|dakhla attitude|pk25|dakhla camps|dakhla lagoon', 23.89922, -15.77952, 'Morocco', 'lagoon', 130, 'guide', 'kitesurf|windsurf|wingfoil', 'Rideable at all tides. Low tide: flat, standing-depth water for about 300 m from the beach; expect a carry of up to about 350 m, and some areas get very shallow. High tide: deeper water and chop, especially in strong wind. Tides are bigger at full and new moon. Speed Spot only works around low tide, when a sandbank of about 600 m forms across the wind.', 'Gusty wind, worse near the dunes and around full moon. Chop at high tide. Very shallow areas and exposed sandbanks at low tide. Sharp shell fragments on the beach (boots recommended). Busy in peak summer. Strong current in the channel inside Dragon Island if riding to Speed Spot. Remote site with limited rescue outside the camps.', 'No specific kite rules reported (common sense). Part of Dakhla Bay is a Ramsar wetland and an Important Bird Area (ZICO); oyster farms sit on the lagoon edges.', 'Launch from the kite camps on the western shore of the lagoon (Dakhla Attitude on its point, PK25, Westpoint, Lagoon Village...), about 25-30 min from town. Each camp has its own beach, school, rental and rescue. If you ride without staying at a camp, get a rescue voucher. Speed Spot (east shore, about 23.87895,-15.74894) is reached by 4x4/boat or by riding across; little or no assistance there.', 'Year-round (about 300-340 windy days a year). Strongest Apr-Sep, peak Jun-Aug. Nov-Apr has lighter wind, good for beginners. Weakest in Dec-Jan.', 'seed', 'https://www.iksurfmag.com/travel-guides/africa/morocco/dakhla/|https://locations.thekitespot.com/locations/kitesurf-dakhla-morocco|https://www.surf-magazin.de/en/spots-and-areas/international/overseas/up-and-coming-spot-of-the-month-dakhla-lagoon/|https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/dakhla-pk25-dakhla-sahara-occidental-morocco.html', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'dakhla-lagoon' AND (SELECT status FROM spots WHERE id = 'dakhla-lagoon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'dakhla-lagoon', 'NNE', 'best', 'Prevailing trade wind, side-shore over the lagoon. Usually 15-25 kn, stronger Apr-Sep (up to 35 kn), often lighter in the morning and picking up in the early afternoon.' WHERE (SELECT status FROM spots WHERE id = 'dakhla-lagoon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'dakhla-lagoon', 'NE', 'best', 'Prevailing trade wind, side-shore along the lagoon. Funnelled and gusty near the dunes.' WHERE (SELECT status FROM spots WHERE id = 'dakhla-lagoon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'dakhla-lagoon', 'N', 'ok', 'Part of the trade wind sector, side to side-on.' WHERE (SELECT status FROM spots WHERE id = 'dakhla-lagoon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'dakhla-lagoon', 'S', 'marginal', 'Rare (about 1-2 times a year, per IKSURFMAG).' WHERE (SELECT status FROM spots WHERE id = 'dakhla-lagoon') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'dakhla-lagoon', 'NW', 'forbidden', 'Estimated offshore at the west-shore camps, based on beach orientation; not confirmed by a source.' WHERE (SELECT status FROM spots WHERE id = 'dakhla-lagoon') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('essaouira-bay', 'Essaouira Bay', 'essaouira|baie d''essaouira|mogador|essaouira plage|essaouira bay', 31.50005, -9.76805, 'Morocco', 'sea', 265, 'guide', 'kitesurf|windsurf|wingfoil', 'Works at all tides on a sandy bottom, but guides rate high tide best. At high tide the small river-mouth lagoon at the south end of the bay fills with flat, glassy water for freestyle, with room for only a few riders.', 'Hidden rocks and very gusty wind near the town and harbour (north/right side). Launching and landing are dangerous on strong days because of gusts. The beach is crowded with horse and camel tours, swimmers and other watercraft, especially at weekends. Mogador island shelters the bay from swell. Waves get bigger to the south, where the island stops blocking them, and in spring/autumn reach 1-2 m. Current is weak (<1 kn).', '', 'Launch from the long, wide sandy beach south of the medina walls, in front of the schools and rental centres in the middle and downwind part of the bay. Rig away from horse and camel tours, tourists and locals. Stay out of the swimming zones. Do not launch near the town at the north end, where wind is gusty and rocks are hidden.', 'Rideable all year. Most reliable from April to September, with a peak in July-August (about 90% windy days, often 25-30+ kn). Main season runs May to October.', 'seed', 'https://locations.thekitespot.com/locations/kitesurf-essaouira-bay-morocco|http://en.wannakitesurf.com/spot/Africa/Morocco/Essaouira_Bay/|https://alexpastorkiteclub.com/blog/kitesurf/kitesurfing-in-essaouira-morocco-a-complete-guide/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'essaouira-bay' AND (SELECT status FROM spots WHERE id = 'essaouira-bay') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'essaouira-bay', 'N', 'best', 'Main summer trade wind (Alizé/Charki) direction, made stronger by the afternoon thermal. 20-30+ kn in Jul-Aug, side to side-onshore along the 5 km arc.' WHERE (SELECT status FROM spots WHERE id = 'essaouira-bay') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'essaouira-bay', 'NNE', 'best', 'Trade-wind variant. Guides call it cross to cross-onshore. Often stronger in the afternoon.' WHERE (SELECT status FROM spots WHERE id = 'essaouira-bay') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'essaouira-bay', 'NNW', 'ok', 'Side-onshore. Gusty near the medina because the town wind shadow disturbs it.' WHERE (SELECT status FROM spots WHERE id = 'essaouira-bay') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'essaouira-bay', 'NW', 'ok', 'Wannakitesurf lists NW side-onshore as a reference direction. Very gusty close to the city because buildings disturb the flow.' WHERE (SELECT status FROM spots WHERE id = 'essaouira-bay') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'essaouira-bay', 'NE', 'marginal', 'Guides list NE as the trade direction, but given the beach orientation it is likely side-off, especially in the mornings. Check on site.' WHERE (SELECT status FROM spots WHERE id = 'essaouira-bay') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'essaouira-bay', 'SW', 'ok', 'Mostly winter. Less predictable and sometimes slightly cross-offshore in the morning before it turns onshore.' WHERE (SELECT status FROM spots WHERE id = 'essaouira-bay') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'essaouira-bay', 'S', 'ok', 'Winter secondary wind. Less reliable than the summer trades.' WHERE (SELECT status FROM spots WHERE id = 'essaouira-bay') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('cumbuco', 'Cumbuco', 'praia do cumbuco|cumbuco beach|cumbuco', -3.63077, -38.71958, 'Brazil', 'sea', 35, 'guide', 'kitesurf|windsurf|wingfoil', 'Main beach is described as not tide dependent. Sandbanks further out make small waves. The size of the Cauipe lagoon depends on water level (rainy season), not on the tide.', 'Chop and small shorebreak, sandbanks offshore. Current of 1-2 kn. Swimmers and other boats in the water. Crowded on weekends and in peak season, especially at Cauipe lagoon. Theft of gear and valuables reported.', '', 'Main kite zone is on the beach in front of the Eco Paradise hotel, where most kiters gather. The beach is wide, so you can move about 150 m up or downwind to find space. It gets busier with obstacles near the village center. The usual downwinder goes to Lagoa do Cauipe (about 6 km downwind) for flat water.', 'June to February. Best from August to December, kiteable almost every day (10-14 m kites). Little wind from March to May (rainy season).', 'seed', 'http://en.wannakitesurf.com/spot/South_America/Brazil/Ceara/Cumbuco/|https://www.mackiteboarding.com/news/kiteboarding-travel-guide-cumbuco-brazil-destinations-ep-18/|https://s2as.com/blogs/news/kitesurfing-in-cumbuco-brazil', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'cumbuco' AND (SELECT status FROM spots WHERE id = 'cumbuco') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cumbuco', 'E', 'best', 'Trade wind with thermal boost from the dunes, often stronger in the afternoon. Cross-onshore from the right.' WHERE (SELECT status FROM spots WHERE id = 'cumbuco') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cumbuco', 'ESE', 'best', 'Average direction of the SE trades. Cross to cross-onshore from the right, usually 15-25 kn from Aug to Dec.' WHERE (SELECT status FROM spots WHERE id = 'cumbuco') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cumbuco', 'SE', 'ok', 'Usual morning direction, side to side-offshore, before it turns side-onshore in the afternoon. Be careful when it is gusty near shore.' WHERE (SELECT status FROM spots WHERE id = 'cumbuco') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cumbuco', 'SSE', 'marginal', 'Side-offshore. Guides say to move to other spots north or south of Cumbuco when it goes offshore.' WHERE (SELECT status FROM spots WHERE id = 'cumbuco') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cumbuco', 'S', 'forbidden', 'Offshore at the main beach.' WHERE (SELECT status FROM spots WHERE id = 'cumbuco') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('jericoacoara-prea', 'Jericoacoara (Preá)', 'jeri|praia do preá|prea|jericoacoara & preá|barrinha|jericoacoara (preá)', -2.8135, -40.4076, 'Brazil', 'sea', 10, 'guide', 'kitesurf|windsurf|wingfoil', 'The ocean beach works at all tides. Low tide gives shallower, flat-to-choppy water. Rising and high tide bring kickers and small waves. The lagoons depend on the tide: Guriú works at medium–high tide, Barra Grande is best at low tide, and Tatajuba changes size with the tide. Check depth before trying tricks.', 'Sand buggies and 4x4s drive along the beach and may not see lines or gear. Medium alongshore current (1–2 kn). Near Jericoacoara village: boats, rocks and buildings close to the beach, and gusty wind off the dune. Very crowded in peak season.', 'The beach is in Jericoacoara National Park (ICMBio). Kiting and kite landing are banned on Jeri''s main beach, which is reserved for windsurfers. A kite zone lies past the sunset dune, and windsurfing is banned within 500 m of shore in that zone. Kite/windsurf schools need a 12-month park authorization (ICMBio portaria, 2016).', 'The main kite launch is on the wide, flat sandy beach at Preá, home to most schools and kite centers. You can kite anywhere along the 14 km strip from Barrinha to Preá. Preá→Jeri is a short downwinder. The landing near the Jeri sunset dune is not for beginners, and wind in front of Jeri is gusty. Flat-water lagoons downwind: Guriú (medium to high tide), Tatajuba, and Barra Grande (low tide).', 'July to January (peak August–January, 20–38 kn). February is mid-season. Lighter winds March–June.', 'seed', 'https://locations.thekitespot.com/locations/kitesurf-jericoacoara-prea-brazil|https://www.mackiteboarding.com/news/kiteboarding-travel-guide-jericoacoara-brazil-destinations-ep-12/|https://windy.app/forecast2/spot/67447/Prea%20Beach,%20Brazil%20(Praia%20do%20Pre%C3%A1)|https://www.opovo.com.br/noticias/economia/2016/08/novas-regras-para-windsurf-e-kitesurf-em-jericoacoara.html', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'jericoacoara-prea' AND (SELECT status FROM spots WHERE id = 'jericoacoara-prea') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'jericoacoara-prea', 'E', 'best', 'Reference trade wind, cross-shore from the right along the Preá–Jericoacoara strip. Typically 16–35 kn in season, blowing until sunset.' WHERE (SELECT status FROM spots WHERE id = 'jericoacoara-prea') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'jericoacoara-prea', 'ESE', 'best', 'Frequent trade direction, cross to slightly cross-offshore from the right. Listed as a working direction by spot guides.' WHERE (SELECT status FROM spots WHERE id = 'jericoacoara-prea') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'jericoacoara-prea', 'ENE', 'ok', 'Cross-onshore, usable along the beach strip.' WHERE (SELECT status FROM spots WHERE id = 'jericoacoara-prea') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'jericoacoara-prea', 'NE', 'ok', 'Cross-onshore, usable.' WHERE (SELECT status FROM spots WHERE id = 'jericoacoara-prea') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'jericoacoara-prea', 'NNE', 'ok', 'Listed as a working direction (thekitespot). Close to onshore.' WHERE (SELECT status FROM spots WHERE id = 'jericoacoara-prea') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'jericoacoara-prea', 'SE', 'marginal', 'Side-offshore at the beach. Listed by windy.app, but it gets gusty and drifts riders out to sea.' WHERE (SELECT status FROM spots WHERE id = 'jericoacoara-prea') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'jericoacoara-prea', 'S', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'jericoacoara-prea') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'jericoacoara-prea', 'SSW', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'jericoacoara-prea') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('barra-grande', 'Barra Grande', 'barra grande do piauí|praia de barra grande|barra grande (cajueiro da praia)|barra grande', -2.90978, -41.41863, 'Brazil', 'sea', 15, 'guide', 'kitesurf|windsurf|wingfoil', 'Very tide-dependent. Mid to low tide gives flat, waist-deep water, and lagoons/pools form on the sea side: ideal for beginners and freestyle. Right at low tide some areas get too shallow. High tide makes the water deeper and choppy, with small waves on the outer sandbank.', 'Shallow sandbanks: jumping or falling in very shallow water near the edges risks injury. Shore break of about 2 m over the outer sandbank at higher tides. Sandy bottom, little current reported. Spot guides mention visible hazards without saying what they are.', '', 'Wide sandy beach about 4-5 km long in front of the village (Cajueiro da Praia municipality), with several kite schools and pousadas along it. Launch from the beach in front of the schools. Give learners room in the shallows. Downwinders run to nearby lagoons (Barrinha, Mangue) and further on to the river mouth area (Macapá).', 'July to January (most consistent August to December, peak in August-September)', 'seed', 'https://wannakitesurf.com/spot/South_America/Brazil/Piaui/Barra_Grande/|https://vvanat.fr/blog/bresil-kite-surf-barra-grande/|https://bahia.ws/en/guia-de-turismo-barra-grande-no-piaui/|https://www.windfinder.com/windstatistics/barra_grande', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'barra-grande' AND (SELECT status FROM spots WHERE id = 'barra-grande') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'barra-grande', 'E', 'best', 'Steady trade wind, typically 18-24 kn (range 15-35 kn), side-shore to side-on from the right (starboard). Stronger in the afternoon.' WHERE (SELECT status FROM spots WHERE id = 'barra-grande') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'barra-grande', 'ENE', 'best', 'Side-on starboard, the reference direction in the season.' WHERE (SELECT status FROM spots WHERE id = 'barra-grande') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'barra-grande', 'ESE', 'ok', 'Side-shore. Usable trade-wind variant.' WHERE (SELECT status FROM spots WHERE id = 'barra-grande') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'barra-grande', 'NE', 'ok', 'More onshore. Choppier, harder to get upwind of the shallows.' WHERE (SELECT status FROM spots WHERE id = 'barra-grande') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'barra-grande', 'SE', 'marginal', 'Some guides call SE the main direction, but on this north-facing coast it turns side-off and gusty. Check on site.' WHERE (SELECT status FROM spots WHERE id = 'barra-grande') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'barra-grande', 'S', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'barra-grande') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'barra-grande', 'SW', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'barra-grande') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('ouistreham-riva-bella', 'Ouistreham Riva-Bella', 'ouistreham - colleville (côte de nacre)|colleville / ouistreham|riva-bella|ouistreham riva-bella', 49.2921, -0.2725, 'France', 'sea', 0, 'guide', 'kitesurf|windsurf|wingfoil', 'Sources disagree. Let''s kite says low tide only: at high tide the beach disappears and the seawall disturbs the wind. Another guide says it works best from mid-tide up, with very shallow water far out at low tide. At high tide water reaches the stone jetty and seawall, which is awkward with waves.', 'Seawall and stone jetty on the beach. Wind turbulence near the seawall and houses at high tide. Shallow, choppy water and small waves in strong onshore wind. Heavy crowds of swimmers in summer. The Orne mouth and Ouistreham ferry port and channel are to the east; watch the currents near the estuary.', 'Kitesurf and other traction kites are covered by municipal beach police orders (arrêté of 9 March 2026, plus a temporary order setting the supervised bathing periods). Navigation in the 300 m band is governed by Préfecture maritime order 53-2013. In the supervised summer season, once the buoys are in place, kites are reportedly banned in the 300 m band except in the designated buoyed channel. Check the posted beach rules.', 'Launch on the beach by the Ouistreham seawall near the SNSM station; access via avenue de Trouville. Parking, a grassy rigging area and beach showers. Never launch close to the seawall or houses (turbulence, injury risk). Use the marked buoyed channel to get in and out, and stay clear of swimming zones.', 'April–September; July is the most consistent. Busy in summer, so riding outside the peak season is advised.', 'seed', 'https://lets-kite.com/fr/spots/1100/ouistreham-colleville-cote-de-nacre|https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/colleville-ouistreham-normandie-france.html|https://ouistreham-rivabella.fr/decouvrir/la-plage-et-la-station-balneaire/securite-a-la-plage/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'ouistreham-riva-bella' AND (SELECT status FROM spots WHERE id = 'ouistreham-riva-bella') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'ouistreham-riva-bella', 'NE', 'best', 'Reference direction. Summer NE sea breeze builds in the afternoon to about 15-18 kn. Venturi effect off the Orne estuary often gives more wind than nearby spots.' WHERE (SELECT status FROM spots WHERE id = 'ouistreham-riva-bella') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'ouistreham-riva-bella', 'NW', 'best', 'Reference direction with low-pressure systems. Brings waves only when it blows strong.' WHERE (SELECT status FROM spots WHERE id = 'ouistreham-riva-bella') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'ouistreham-riva-bella', 'N', 'ok', 'Onshore and usable.' WHERE (SELECT status FROM spots WHERE id = 'ouistreham-riva-bella') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'ouistreham-riva-bella', 'NNE', 'ok', 'Usable.' WHERE (SELECT status FROM spots WHERE id = 'ouistreham-riva-bella') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'ouistreham-riva-bella', 'ENE', 'ok', 'Usable.' WHERE (SELECT status FROM spots WHERE id = 'ouistreham-riva-bella') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'ouistreham-riva-bella', 'E', 'ok', 'Usable. Listed as rideable by Let''s kite.' WHERE (SELECT status FROM spots WHERE id = 'ouistreham-riva-bella') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'ouistreham-riva-bella', 'NNW', 'ok', 'Usable.' WHERE (SELECT status FROM spots WHERE id = 'ouistreham-riva-bella') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'ouistreham-riva-bella', 'WNW', 'ok', 'Usable.' WHERE (SELECT status FROM spots WHERE id = 'ouistreham-riva-bella') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'ouistreham-riva-bella', 'W', 'ok', 'Usable. Listed as rideable by Let''s kite.' WHERE (SELECT status FROM spots WHERE id = 'ouistreham-riva-bella') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'ouistreham-riva-bella', 'ESE', 'marginal', 'Rideable only in some conditions according to Let''s kite. One guide says SE becomes sailable at low tide.' WHERE (SELECT status FROM spots WHERE id = 'ouistreham-riva-bella') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'ouistreham-riva-bella', 'WSW', 'marginal', 'Rideable only in some conditions according to Let''s kite.' WHERE (SELECT status FROM spots WHERE id = 'ouistreham-riva-bella') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'ouistreham-riva-bella', 'SE', 'forbidden', 'Offshore side. Let''s kite says to avoid the southern sector. One guide reports SE as sailable at low tide only; treat with caution.' WHERE (SELECT status FROM spots WHERE id = 'ouistreham-riva-bella') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'ouistreham-riva-bella', 'SSE', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'ouistreham-riva-bella') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'ouistreham-riva-bella', 'S', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'ouistreham-riva-bella') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'ouistreham-riva-bella', 'SSW', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'ouistreham-riva-bella') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'ouistreham-riva-bella', 'SW', 'forbidden', 'Offshore side.' WHERE (SELECT status FROM spots WHERE id = 'ouistreham-riva-bella') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('les-sables-d-olonne-grande-plage', 'Les Sables-d''Olonne – Grande Plage', 'grande plage des sables-d''olonne|plage du remblai|les sables-d''olonne – grande plage', 46.49333, -1.7925, 'France', 'sea', 180, 'guide', 'windsurf|wingfoil|sailing', 'Low tide gives a wide beach, and with swell the waves line up in front of the jetty. High tide leaves only a narrow strip below the Remblai promenade and the wind gets patchy.', 'Busy urban beach with lots of swimmers and surfers. Harbour mouth and boat traffic just west of the Petite Jetée. Wind shadow and gusts from the town and promenade. Swimming outside the patrolled zones is banned along much of the coast because of strong currents.', 'Municipal decree LSO-DSN-PL-2025-012: kitesurfing, land yachting and speed sail are banned on the whole Grande Plage and on Tanchet beach, unless a club affiliated to FFVoile, FFVL or FFCV gets an exemption. When buoyed, the 300 m swimming zone is closed to all craft, foils included. Use the non-motorised channel by the Petite Jetée. Traction kites are banned on patrolled beaches from 1 June to 30 September and during the spring and All Saints'' school holidays. Paid teaching only through schools approved by the town. Motor craft limited to 5 knots in the 300 m band south of the swimming zone.', 'Launch and come back only through the buoyed channel for non-motorised craft, on the west end of the beach next to the Petite Jetée: about 160 m wide at the shore and 180 m offshore. No stopping or anchoring in the channel. Sailing and foiling are banned in the buoyed swimming zone and in the surf zone at the east end.', '', 'seed', 'https://ville.lessablesdolonne.fr/media/lso-dsn-pl-2025-012-arrete-plage-reglementation-2025-signe-tpn.pdf|https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/les-sables-d-olonne-pays-de-la-loire-france.html', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'les-sables-d-olonne-grande-plage' AND (SELECT status FROM spots WHERE id = 'les-sables-d-olonne-grande-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'les-sables-d-olonne-grande-plage', 'S', 'ok', 'Onshore on this south-facing bay; choppy, with waves in front of the jetty.' WHERE (SELECT status FROM spots WHERE id = 'les-sables-d-olonne-grande-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'les-sables-d-olonne-grande-plage', 'SSW', 'ok', 'Cross-onshore, inferred from the beach orientation.' WHERE (SELECT status FROM spots WHERE id = 'les-sables-d-olonne-grande-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'les-sables-d-olonne-grande-plage', 'SW', 'ok', 'Cross-onshore, inferred from the beach orientation.' WHERE (SELECT status FROM spots WHERE id = 'les-sables-d-olonne-grande-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'les-sables-d-olonne-grande-plage', 'W', 'ok', 'Cross-shore, inferred from the beach orientation; the harbour mouth and La Chaume are upwind, so expect gusts.' WHERE (SELECT status FROM spots WHERE id = 'les-sables-d-olonne-grande-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'les-sables-d-olonne-grande-plage', 'E', 'ok', 'Cross-shore from the left, inferred from the beach orientation.' WHERE (SELECT status FROM spots WHERE id = 'les-sables-d-olonne-grande-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'les-sables-d-olonne-grande-plage', 'NW', 'marginal', 'Side-offshore over the town; wind is patchy near the Remblai, especially at high tide.' WHERE (SELECT status FROM spots WHERE id = 'les-sables-d-olonne-grande-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'les-sables-d-olonne-grande-plage', 'NE', 'marginal', 'Side-offshore over the town; patchy near the promenade.' WHERE (SELECT status FROM spots WHERE id = 'les-sables-d-olonne-grande-plage') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'les-sables-d-olonne-grande-plage', 'N', 'forbidden', 'Offshore: blows from the town out to sea.' WHERE (SELECT status FROM spots WHERE id = 'les-sables-d-olonne-grande-plage') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('sotavento', 'Sotavento', 'playa de sotavento|playa barca|sotavento lagoon|rené egli sotavento|risco del paso|sotavento', 28.12043, -14.21632, 'Spain', 'lagoon', 130, 'guide', 'kitesurf|windsurf|wingfoil', 'Tidal lagoon about 4 km long. It fills best around spring tides (full and new moon), with 35-85 cm of water for about 2 h either side of high tide. At low tide it can be very shallow or dry, so you may have to walk about 300 m or cross the sandbank to ride the open sea.', 'Cross-offshore wind blows you out to sea, so use paid jet-ski rescue (about EUR 50 per rescue or EUR 90 per week). Strong, gusty summer wind and blowing sand. Very shallow water and sandbanks at low tide. Small shorebreak; wind chop outside the lagoon. Not ideal for unsupervised beginners.', 'Separate zones for windsurf, kite and swimming; the windsurf zone at sea is supervised. Keep to your zone.', 'Very wide, long sandy beach. Two main access points: the René Egli centre at the north end of the lagoon and Risco del Paso at the south end (ION Club). Windsurf and kite areas are kept apart by a swimming zone. Ask the local centres about beach assistance and rescue.', 'May-September (windiest, Jun-Aug peak); can be ridden year-round with less wind.', 'seed', 'https://www.sportif.travel/events/70/18/Canary_Islands/Fuerteventura_-_Sotavento/Sotavento_Lagoon_Spot_Guide|https://locations.thekitespot.com/locations/kitesurf-fuerteventura-playa-sotavento-canary-islands|https://www.windsurf.co.uk/micro-guides-sotavento-fuerteventura-canary-islands/|https://wannakitesurf.com/spot/Europe/Spain/Canary_Islands/Fuerteventura/Sotavento/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'sotavento' AND (SELECT status FROM spots WHERE id = 'sotavento') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'sotavento', 'NE', 'best', 'Reference direction: NE trade wind, cross-offshore from the left, accelerated by a double venturi effect. Strongest May-Sept, often 25-30 kn and up to 40 kn in Jul-Aug; gusty.' WHERE (SELECT status FROM spots WHERE id = 'sotavento') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'sotavento', 'NNE', 'ok', 'Trade-wind variant, more side-offshore. Gusty, and drift goes out to sea.' WHERE (SELECT status FROM spots WHERE id = 'sotavento') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'sotavento', 'ENE', 'ok', 'Side-shore trade-wind variant.' WHERE (SELECT status FROM spots WHERE id = 'sotavento') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'sotavento', 'N', 'marginal', 'N is listed among the working directions, but it blows side-offshore to offshore on this beach and is very gusty. Not for beginners without rescue cover.' WHERE (SELECT status FROM spots WHERE id = 'sotavento') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'sotavento', 'NW', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'sotavento') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'sotavento', 'NNW', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'sotavento') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('cabarete-kite-beach', 'Cabarete Kite Beach', 'kite beach|playa kite beach|cabarete kitebeach|cabarete kite beach', 19.76378, -70.42264, 'Dominican Republic', 'sea', 30, 'guide', 'kitesurf', 'Generally works at any tide, but the reef is very shallow in places, especially at low tide.', 'Outer reef about 300 m out with breaking waves up to mast high in winter. Shallow reef with fire coral, worst at the point; go wide on downwinders. Choppy inside when windy. Crowded water with mixed levels and many students. Swimmers and bystanders on the beach. No official rescue service; school boats are limited in strong conditions and can''t cross the reef.', 'Certified training required. Teaching allowed only by official schools. Launching and landing only in the school zones. No swimming on windy days. Windsurfers usually use the main Cabarete Bay; Bozo Beach is a separate kite spot downwind in the bay.', 'Launch and land only in front of the kite schools. Other areas only in an emergency. Beach is small and busy (4 schools). Use competent assistants and release only on the rider''s signal. Don''t ride straight in front of schools or hotels. More room near the Dare2Fly end. To avoid crowds, ride at lunchtime or in the evening.', 'Trade winds blow almost all year. Most reliable April–September, strongest June–August (about 15–30 kn). December–January can also be good, with bigger waves in winter.', 'seed', 'https://se.kiteforum.com/kitesurf/spot/cabarete_kitebeach|https://www.mackiteboarding.com/news/kiteboarding-travel-guide-cabarete-dominican-republic-destinations-ep-02/|https://www.iksurfmag.com/travel-guides/caribbean/dominican-republic/cabarete/|https://vvanat.fr/blog/cabarete-republique-dominicaine-kitesurf/', 0, 'spot')
