INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cabarete-kite-beach', 'ENE', 'best', 'Northeast/east trades, side-onshore from the right.' WHERE (SELECT status FROM spots WHERE id = 'cabarete-kite-beach') = 'seed';
