INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cabarete-kite-beach', 'SE', 'marginal', 'Side-off at this beach orientation (estimate).' WHERE (SELECT status FROM spots WHERE id = 'cabarete-kite-beach') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cabarete-kite-beach', 'S', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'cabarete-kite-beach') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cabarete-kite-beach', 'SSW', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'cabarete-kite-beach') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'cabarete-kite-beach', 'SW', 'forbidden', 'Offshore.' WHERE (SELECT status FROM spots WHERE id = 'cabarete-kite-beach') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('langebaan', 'Langebaan', 'langebaan main beach|langebaan lagoon|shark bay (langebaan)|langebaan', -33.093, 18.032, 'South Africa', 'lagoon', 270, 'guide', 'kitesurf|windsurf|wingfoil|sailing', 'Strong tidal currents in the lagoon. Main Beach: incoming tide gives easy riding; outgoing tide current makes upwind return hard, especially in SE. Shark Bay: shallow sandbars at low water, watch foil masts.', 'Strong ebb current at Main Beach (drift away from launch); sandbars and shallow patches at Shark Bay (foils); heavy crowds and kite tangles in peak season, many accidents when beginners try upwind riding at Shark Bay; gusty venturi wind; lost boards carried off by the tide; theft of unattended gear.', 'Lagoon is part of West Coast National Park / Langebaan Lagoon MPA, split into zones: northern Controlled Zone (Zone A, multi-use incl. kiteboarding and power boats), Restricted Zone (Zone B, non-powered craft only, no fishing), southern Sanctuary/Wilderness Zone (Zone C, closed to all access). Respect zone boundaries; lessons only via licensed schools at crowded spots.', 'Two main launches 5-10 min apart: Main Beach (town centre, rig on the wide beach, restaurants, safety boat often on patrol, deeper water further out, favoured by foilers/advanced) and Shark Bay (park on the hill, walk down to rig on grass; small crowded beach, ~2 km of waist-deep clear water, beginner/school area). Wind can differ between both: check the other if one is off. Stay out of the downwind freestyle area where pros train; look before launching.', 'October to March (best November-February).', 'seed', 'https://www.mackiteboarding.com/news/kiteboarding-travel-guide-langebaan-south-africa-destinations-ep-17/|https://kitekahunas.com/kitesurfing_langebaan_main_beach.html|https://kitekahunas.com/kitesurfing_langebaan_shark_bay.html|https://en.wikipedia.org/wiki/Langebaan_Lagoon_Marine_Protected_Area', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'langebaan' AND (SELECT status FROM spots WHERE id = 'langebaan') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'langebaan', 'S', 'best', 'Summer thermal-enhanced southerly, cross to cross-onshore from the left; frequently 20+ kn Oct-Mar, gusty, up to ~35 kn Nov-Feb.' WHERE (SELECT status FROM spots WHERE id = 'langebaan') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'langebaan', 'SSW', 'best', 'Cross-shore on the lagoon; flat to slightly choppy water.' WHERE (SELECT status FROM spots WHERE id = 'langebaan') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'langebaan', 'SW', 'ok', 'Listed as working for Main Beach and Shark Bay.' WHERE (SELECT status FROM spots WHERE id = 'langebaan') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'langebaan', 'SSE', 'ok', 'Workable but gustier; on outgoing tide the current makes it hard to stay upwind.' WHERE (SELECT status FROM spots WHERE id = 'langebaan') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'langebaan', 'SE', 'marginal', 'Side-off and gusty at Main Beach; with ebb tide the current pushes riders away from the launch, very unpleasant. Shark Bay often more usable.' WHERE (SELECT status FROM spots WHERE id = 'langebaan') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'langebaan', 'NW', 'ok', 'Mentioned as usable at Main Beach (winter frontal winds); less consistent.' WHERE (SELECT status FROM spots WHERE id = 'langebaan') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('kite-beach-bloubergstrand', 'Kite Beach (Bloubergstrand)', 'kite beach blouberg|blouberg kite beach|bloubergstrand beach|kite beach (bloubergstrand)', -33.82189, 18.47611, 'South Africa', 'sea', 245, 'guide', 'kitesurf|windsurf|wingfoil', '', 'Shore break and small to medium waves, with rocky patches in places. Cold Atlantic water (13-18 °C, sometimes under 10 °C after strong SE): wear a 4/3 mm wetsuit. Cross-offshore angle in SE wind, so plan a downwind escape route. Very crowded Dec-Feb, with swimmers on busy days and advanced riders jumping. Sharks reported.', '', 'Wide sandy launch less than 60 m from the water, across Otto du Plessis Drive from the KFC (address listed as 2B Athens Rd). It lies halfway between Dolphin Beach and Table View and is the main base for kite schools and beginners. Parking is on the street next to the beach. In peak season, wrap your bar and don''t leave lines across the beach. Beginners should ride with a school.', 'Oct-Mar (peak Dec-Feb)', 'seed', 'https://breeza.io/spots/south-africa/blouberg-kite-beach|https://locations.thekitespot.com/locations/kitesurf-blougbergstrand-cape-town-south-africa|https://theplanetd.com/kitesurfing-cape-town-guide/|http://en.wannakitesurf.com/spot/Africa/South_Africa/Western_Cape/Tableview/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'kite-beach-bloubergstrand' AND (SELECT status FROM spots WHERE id = 'kite-beach-bloubergstrand') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'kite-beach-bloubergstrand', 'SSE', 'best', 'Reference summer SE-SSE trade wind (Cape Doctor), roughly cross-shore, often 20-30 kn. Usually lighter here than at Sunset Beach. Most riders use a 10 m kite or smaller, with 5-7 m on windy days.' WHERE (SELECT status FROM spots WHERE id = 'kite-beach-bloubergstrand') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'kite-beach-bloubergstrand', 'S', 'best', 'Inside the reference SE-S window (113-203°). Cross-shore.' WHERE (SELECT status FROM spots WHERE id = 'kite-beach-bloubergstrand') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'kite-beach-bloubergstrand', 'SE', 'ok', 'Workable, but tends cross-offshore on this west-facing beach. Strong SE makes choppy, energetic water and brings very cold upwelling water.' WHERE (SELECT status FROM spots WHERE id = 'kite-beach-bloubergstrand') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'kite-beach-bloubergstrand', 'SW', 'ok', 'Listed as working (SW-NW range). Onshore-side component.' WHERE (SELECT status FROM spots WHERE id = 'kite-beach-bloubergstrand') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'kite-beach-bloubergstrand', 'W', 'ok', 'Listed as working (SW-NW range). Onshore.' WHERE (SELECT status FROM spots WHERE id = 'kite-beach-bloubergstrand') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'kite-beach-bloubergstrand', 'NW', 'ok', 'Listed as working (SW-NW range). Mostly frontal or winter wind.' WHERE (SELECT status FROM spots WHERE id = 'kite-beach-bloubergstrand') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'kite-beach-bloubergstrand', 'E', 'forbidden', 'Offshore on a beach facing WSW.' WHERE (SELECT status FROM spots WHERE id = 'kite-beach-bloubergstrand') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('le-morne', 'Le Morne', 'le morne lagoon|the point (le morne)|kite lagoon|le morne kitebeach|le morne', -20.46675, 57.30862, 'Mauritius', 'lagoon', 170, 'guide', 'kitesurf|windsurf|wingfoil', 'The lagoon is shallow and stays waist-deep in most places. At low tide some areas get too shallow, and windsurfing is sometimes impossible there. One Eye should only be ridden at high tide, and low tide there is hazardous. Manawa is reported best at low tide. An outgoing tide combined with a big SW swell produces very strong currents out of the channels, so avoid that combination.', 'Shallow, sharp coral and sea urchins: wear booties. Strong currents run in the channels below Manawa and One Eye and around the back of the reef, especially in big swell (Sep-Nov). Manawa lies about 1-1.5 km out, beyond a wide channel. Chameau and One Eye are downwind/right of the beach and are expert-only: shallow reef, fast hollow waves, cross-offshore wind, rescue very difficult. The beach has trees where kites can get tangled. Wind can turn offshore in the evening, and the lagoon gets choppy in strong wind. Rescue is paid (around EUR 20-100+). Stay ashore on red-flag days with huge waves.', '', 'Two main launches. The Point is the large sandy beach at the south tip of the peninsula in front of Club Mistral/the hotels. The wind is sideshore from the left, gusty on the beach, and the spot is for independent/advanced riders. The water is flat to choppy, the lagoon runs about 800 m to the reef, and it gives access to the reef breaks. Kite Lagoon/The Bay is slightly SE of the Point: an almost closed, waist-deep bay with onshore wind, used by schools and beginners. Experienced riders should stay upwind of lesson zones and give way to surfers at One Eye.', 'May to November is the main windy season (SE trades), with the peak from June to October and August often the best month. November to April has lighter, patchier wind and cyclone risk.', 'seed', 'https://www.sportif.travel/events/90/5/Indian_Ocean_and_SE_Asia/Mauritius_-_Le_Morne/Mauritius_Le_Morne_Spot_Guide|https://boards.co.uk/travel/world-travel/le-morne-mauritius.html|https://www.mackiteboarding.com/news/kiteboarding-travel-guide-mauritius-le-morne-destinations-ep-15-/|https://kitejungle.com/kite-places/mauritius/le-morne', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'le-morne' AND (SELECT status FROM spots WHERE id = 'le-morne') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'le-morne', 'SE', 'best', 'Reference trade wind direction. Cross to cross-onshore from the left at The Point; nearly onshore in the beginner Kite Lagoon/Bay. Le Morne Brabant and nearby mountains add roughly 5-10 kn to the trades.' WHERE (SELECT status FROM spots WHERE id = 'le-morne') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'le-morne', 'SSE', 'ok', 'Trade-wind variant, cross-onshore across the lagoon.' WHERE (SELECT status FROM spots WHERE id = 'le-morne') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'le-morne', 'ESE', 'marginal', 'Guides report the southern zones work less well and the wind is lighter in ESE.' WHERE (SELECT status FROM spots WHERE id = 'le-morne') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'le-morne', 'E', 'marginal', 'Lagoon wind gets lighter and more side-off. Manawa outer reef is reported to work best in easterlies (experts only).' WHERE (SELECT status FROM spots WHERE id = 'le-morne') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'le-morne', 'N', 'forbidden', 'Offshore from the peninsula.' WHERE (SELECT status FROM spots WHERE id = 'le-morne') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'le-morne', 'NW', 'forbidden', 'Offshore from the peninsula.' WHERE (SELECT status FROM spots WHERE id = 'le-morne') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('mui-ne', 'Mui Ne', 'mui ne beach|ham tien|mui ne main beach|mui ne', 10.94176, 108.19473, 'Vietnam', 'sea', 160, 'guide', 'kitesurf|windsurf|wingfoil', 'Tidal spot. At high tide the beach is narrow and a heavy shore dump makes launching and landing hard, especially in strong wind. Low to mid tide is easier.', 'Strong shorebreak at high tide and in strong wind, beyond beginner level. Gusty wind that builds fast in the afternoon. Crowds of kiters, windsurfers and swimmers. Rocky headland at the northern end of the peninsula. Beach erosion at the northern end of Rang Beach. Low-risk jellyfish. Rubbish at Malibu beach.', '', 'Main launch is the 1 km+ stretch of sand along Nguyen Dinh Chieu (Ham Tien), in front of the schools: C2Sky, VKS, Surfpoint, Jibe''s. Launching gets hard at high tide because the beach is narrow. Do not launch with people or buildings directly downwind. Weigh unattended kites down with sand. Give learners extra room. Busy in high-season afternoons.', 'November-March, peak January-March. April and October are transition months with unreliable wind. May-September brings light southerly winds.', 'seed', 'https://locations.thekitespot.com/locations/kitesurf-mui-ne-vietnam|https://www.iksurfmag.com/travel-guides/asia/vietnam/mui-ne|https://localvietnam.com/binh-thuan/mui-ne/kite-windsurfing-in-mui-ne/|http://en.wannakitesurf.com/spot/Asia/Vietnam/Mui_Ne/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'mui-ne' AND (SELECT status FROM spots WHERE id = 'mui-ne') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'mui-ne', 'NE', 'best', 'Main NE monsoon direction from Nov to Mar, side-shore to side-onshore. Usually 18-30 kn, sometimes up to 40 kn. The thermal effect builds it from about 10:00 to 18:00.' WHERE (SELECT status FROM spots WHERE id = 'mui-ne') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'mui-ne', 'ENE', 'best', 'Cross-onshore monsoon direction, very common in high season. Chop builds through the day.' WHERE (SELECT status FROM spots WHERE id = 'mui-ne') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'mui-ne', 'E', 'ok', 'Cross-onshore, works on the main beach. Guides give NE to SE as the usable range.' WHERE (SELECT status FROM spots WHERE id = 'mui-ne') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'mui-ne', 'ESE', 'ok', 'Side-onshore to onshore, usable.' WHERE (SELECT status FROM spots WHERE id = 'mui-ne') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'mui-ne', 'SE', 'ok', 'Upper limit of the NE-SE range in guides. Mostly onshore.' WHERE (SELECT status FROM spots WHERE id = 'mui-ne') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'mui-ne', 'S', 'marginal', 'Low season (May-Sep) southerly winds, often only 10-14 kn. Onshore, needs big kites (about 14 m).' WHERE (SELECT status FROM spots WHERE id = 'mui-ne') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('bulabog-beach', 'Bulabog Beach', 'bulabog|boracay kite beach|boracay island|bulabog beach', 11.96368, 121.9309, 'Philippines', 'lagoon', 90, 'guide', 'kitesurf|windsurf', 'Strongly tidal. Common advice: no riding from 1.5 h before to 1.5 h after low tide, when exposed reef leaves little space. Mid tide is best: fairly flat water, mostly waist-deep, enough beach. High tide leaves a very narrow beach. Sources disagree on low tide (one guide says best at low tide), so check with local schools.', 'Shallow coral reef, sea urchins and seagrass, so wear booties. The outer reef sits about 500 m out and can have waves up to 2 m in stormy weather. Palm trees, power lines, sea walls and the road are close to the launch. Crowded in peak season with schools. Jet skis and motorised sports use the outer reef/deep water.', 'Activity zoning: the shallow inner lagoon is for kiteboarding/windsurfing instruction; the outer reef/deep water is for jet skis and motorised sports. Designated launch zones help limit crowding and reef damage.', 'Launch from the sand zone on the east side of the narrow neck of the island, about a 5-7 min walk from Station 1. Watch out for palm trees and power lines when setting up. Lay lines out crosswind/upwind. Space is very tight at high tide (palms, sea walls, road), so you need deep-water pack-down, self-rescue and assisted launch/land skills. Several schools are based here.', 'November to April (Amihan), peak January-February; also good December, March and April.', 'seed', 'https://locations.thekitespot.com/locations/boracay-island|https://4stogo.com/blog/posts/boracay-activity-zone-maps-bulabog-puka-ariels-point|http://en.wannakitesurf.com/spot/Asia/Philippines/Visayas/Bulabog_Beach/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'bulabog-beach' AND (SELECT status FROM spots WHERE id = 'bulabog-beach') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'bulabog-beach', 'NE', 'best', 'Amihan NE trade wind, side-on/onshore over the reef-sheltered bay; typically 16-25 kn, most reliable Dec-Mar.' WHERE (SELECT status FROM spots WHERE id = 'bulabog-beach') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'bulabog-beach', 'ENE', 'best', 'Steady Amihan direction, cross-onshore to onshore.' WHERE (SELECT status FROM spots WHERE id = 'bulabog-beach') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'bulabog-beach', 'E', 'ok', 'Listed as a working direction (NE and E dominant); onshore.' WHERE (SELECT status FROM spots WHERE id = 'bulabog-beach') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'bulabog-beach', 'NNE', 'ok', 'Amihan described as N-NE; cross-onshore.' WHERE (SELECT status FROM spots WHERE id = 'bulabog-beach') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'bulabog-beach', 'SW', 'forbidden', 'Habagat (May-Oct) SW wind is offshore at east-facing Bulabog; wind sports move to the west coast/White Beach.' WHERE (SELECT status FROM spots WHERE id = 'bulabog-beach') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'bulabog-beach', 'W', 'forbidden', 'Offshore at the east-facing beach.' WHERE (SELECT status FROM spots WHERE id = 'bulabog-beach') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('hood-river-sandbar-event-site', 'Hood River Sandbar (Event Site)', 'hood river spit|the spit|kite beach|hood river event site|hood river waterfront|hood river sandbar (event site)', 45.716, -121.513, 'USA', 'river', 0, 'guide', 'kitesurf|windsurf|wingfoil', 'No real tide, but the river level changes a lot. Depending on the Columbia''s level, the sandbar can be as big as a football field or completely under water. At high water, launch space is very limited. At low water, watch for shallows and stones.', 'Strong river current (over 2 knots). If you miss the downwind exit, the current can carry you toward the Hood River Bridge. Frequent barge and boat traffic in the shipping channel, and large vessels block the wind. Gusty, shifty wind with turbulence and dead zones near the beach. Stones on the beach and in the water. The launch and the water get very crowded, with kite schools, beginners and trick sessions all at once. You need to ride upwind confidently and recover your kite and board on your own before going beyond the sandbar.', 'Port of Hood River rules: you may launch kites, including trainer kites, only where official signs allow it. From about late June until October, kites may be launched only from the sandbar, and the Event Site beach and lawn are closed to kites. The Marina is always off-limits for pumping or launching. No kiting from other beaches in the area. The access is managed with the Columbia Gorge Kiteboarding Association. A kiteboarder has been arrested before for breaking Port rules.', 'Park at the Port of Hood River Event Site, then walk with your gear along the gravel path to the sandbar, between the Event Site and the Marina. In summer, kites may be launched only from the sandbar, which is kite-only. Windsurfers use the Event Site just upwind. In pre-season, when the sandbar is under water, the Port may allow kite setup on the Event Site lawn in a marked kite box on the east side. Riders sort themselves by level: independent riders upwind, lessons and the slider park downwind. Follow strict launch etiquette. Riders who look inexperienced or unsafe may be asked to deflate their kite.', 'May to September. June to August is the peak, with daily west wind of about 15-35 knots. Winter is generally not rideable.', 'seed', 'https://www.mackiteboarding.com/news/kiteboarding-travel-guide-hood-river-oregon-usa-destinations-ep-03/|https://portofhoodriver.specialdistrict.org/event-site-closed-to-kite-launching|https://se.kiteforum.com/kitesurf/spot/columbia_river___hood_river_sandbar|https://www.iksurfmag.com/travel-guides/americas/usa/hood-river', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'hood-river-sandbar-event-site' AND (SELECT status FROM spots WHERE id = 'hood-river-sandbar-event-site') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hood-river-sandbar-event-site', 'W', 'best', 'Main summer wind, usually 18-25 mph and often 25-35+ mph on strong days. Gusty and sideshore near the beach. The current flows against the wind, so it helps riders work upwind and less wind is needed.' WHERE (SELECT status FROM spots WHERE id = 'hood-river-sandbar-event-site') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hood-river-sandbar-event-site', 'WSW', 'best', 'Listed as a good direction for the sandbar. Gusty and shifty near shore.' WHERE (SELECT status FROM spots WHERE id = 'hood-river-sandbar-event-site') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hood-river-sandbar-event-site', 'WNW', 'best', 'Listed as a good direction for the sandbar.' WHERE (SELECT status FROM spots WHERE id = 'hood-river-sandbar-event-site') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'hood-river-sandbar-event-site', 'E', 'marginal', 'Rare at Hood River. Easterlies mostly come in winter and are cold and harsh, so they are generally not suitable for riding. The sandbar is described as a west-wind-only spot.' WHERE (SELECT status FROM spots WHERE id = 'hood-river-sandbar-event-site') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('kite-beach-kanaha-maui', 'Kite Beach (Kanaha), Maui', 'kite beach maui|kanaha kite beach|kitebeach|lesson beach (west end)|kanaha beach park|kite beach (kanaha), maui', 20.8963, -156.4581, 'USA', 'sea', 10, 'guide', 'kitesurf|windsurf|wingfoil', 'Spot guides say the tide makes little difference. The water is shallow, about 8-12 ft deep for up to half a mile out, over a reef. The inside is flat or choppy, and waves break on the outer reef about 300 m out.', 'Sharp reef and rocks, especially between Kanaha and Kite Beach. Outer reef break gets big in winter north swell, with high-surf warnings and rescues. Gusty wind on the inside. Crowded, with runaway kites. Rocks, shells and trees on the beach. A no-kite zone at the end of the airport runway lies upwind. Kahului Harbor is downwind.', '11 o''clock rule: no kiting or windsurfing before 11:00 so swimmers and fishermen have the water to themselves. Swimmers, fishermen and outrigger canoes have right of way. Keep at least 200 ft from other water users. No kiting when kids are on the beach. Do not jump over other people. Under the FAA waiver, kites must stay below 125 ft above sea level and are banned in the 2 x 1 mile corridor at the end of Kahului Airport Runway 2, toward Spreckelsville. Kanaha swim zones A, B and C are swimming only.', 'Launch from the sand at Kite Beach, on Amala Place downwind (west) of Kanaha Beach Park, which is the windsurf beach. Do not launch from the windsurf park. The far west end, called Lesson Beach, is used by kite schools. The beach is crowded with many pros, so get help launching, keep a tidy line set-up and do not jump over other people.', 'May to October, when the trades are most reliable. Some guides say April to August.', 'seed', 'https://se.kiteforum.com/kitesurf/spot/maui____kanaha_park|https://se.kiteforum.com/kitesurf/spot/Maui___Lesson_Beach|https://www.law.cornell.edu/regulations/hawaii/Haw-Code-R-SS-13-256-130|https://mauinow.com/2018/12/07/three-wind-kite-surfers-rescued-at-kanaha-maui/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'kite-beach-kanaha-maui' AND (SELECT status FROM spots WHERE id = 'kite-beach-kanaha-maui') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'kite-beach-kanaha-maui', 'NE', 'best', 'Reference trade-wind direction, side-onshore from the right. Usually blows from about 9am to 6pm. Gusty on the inside.' WHERE (SELECT status FROM spots WHERE id = 'kite-beach-kanaha-maui') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'kite-beach-kanaha-maui', 'ENE', 'best', 'Main trade-wind direction, side/side-onshore. Consistent and often strong because the trades are funnelled between the Maui mountains.' WHERE (SELECT status FROM spots WHERE id = 'kite-beach-kanaha-maui') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'kite-beach-kanaha-maui', 'NNE', 'ok', 'Listed by spot guides as a good direction. Side-onshore.' WHERE (SELECT status FROM spots WHERE id = 'kite-beach-kanaha-maui') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'kite-beach-kanaha-maui', 'E', 'ok', 'One of the main trade-wind directions. More side-shore, so it is gustier on the inside.' WHERE (SELECT status FROM spots WHERE id = 'kite-beach-kanaha-maui') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('sherman-island', 'Sherman Island', 'sherman island county park|sherman island kite launch|sherman|sherman island', 38.057, -121.79212, 'USA', 'river', 0, 'guide', 'kitesurf|windsurf|wingfoil', 'Tidal river. On the ebb, the current runs seaward against the westerly and builds steep chop (up to about waist high on big tides). If you crash, the current carries your board away. On the flood, the river runs upstream with the wind: flatter water but less apparent wind, so it suits beginners better. Water is flattest upwind toward the islands.', 'Trees and thorn bushes right behind the launch: you must get upwind within about 20 ft of your waterstart. Logs at the water''s edge, submerged obstacles near the launch and the islands (foilers should use short masts), shallows, a shipping channel, strong tidal currents, gusty wind, and crowds of 100+ sailors on summer days. Not for beginners without a school (lesson or boat support).', 'Sacramento County Regional Parks: open sunrise to sunset, parking fee required (self-pay if no attendant). Kiters must stay at least 200 ft from beaches and shore areas, with no jumping or tricks near shore. Do not launch or land when people are in the way. No launching at the Access/Pit.', 'The only approved kite launches are the Sacramento County Park beaches and the Baja Road launch. No launching at the Access/Pit (California Water Management Board). Upper Kite Beach is direct onshore and the hardest; the Middle Beaches are cross/onshore; the Baja area is the safest for launching and landing. Rig on the grass, walk the bush-lined path, step over the logs. Give the head-tap landing signal and wait for a clear reply before landing.', 'April to September (Delta Breeze nearly every day from May to August). Most consistent in June, July and August. Late September and October can still be strong and less crowded.', 'seed', 'https://regionalparks.saccounty.gov/us/en/parks/sacramento-river-and-delta/sherman-island.html|https://www.mackiteboarding.com/news/-kiteboarding-travel-guide-sherman-island-california-usa-destinations-ep-15/|https://blog.tempest.earth/?p=34618|https://www.nps.gov/articles/000/surfing-the-delta-breeze-at-sacramento-san-joaquin-delta-national-heritage-area.htm', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'sherman-island' AND (SELECT status FROM spots WHERE id = 'sherman-island') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'sherman-island', 'W', 'best', 'Prevailing summer ''Delta Breeze'' (sea breeze driven by the SF–Sacramento temperature gradient), typically 16-30 kn. Gusty, with fast swings in strength.' WHERE (SELECT status FROM spots WHERE id = 'sherman-island') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'sherman-island', 'WSW', 'best', 'Prevailing thermal westerly. Cross/onshore at the middle beaches, more directly onshore at Upper Kite Beach.' WHERE (SELECT status FROM spots WHERE id = 'sherman-island') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'sherman-island', 'N', 'marginal', 'Blows straight onto the launch beach from the power-line tower across the river. Shifty and gusty, with sudden lulls of 5-10 mph after near-30 mph gusts.' WHERE (SELECT status FROM spots WHERE id = 'sherman-island') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('safaga-soma-bay', 'Safaga Soma Bay', 'soma bay|somabay|abu soma|7bft kite house soma bay|safaga soma bay', 26.84758, 33.99041, 'Egypt', 'lagoon', 150, 'guide', 'kitesurf|windsurf|wingfoil', 'The Red Sea tide range is small, but the standing-depth area dries out at low tide. At low tide you may have to walk 50-100 m across the reef flat to reach deep enough water. At high tide there is no walk and more shallow riding area.', 'Wind is offshore to cross-offshore at the main beach, so drifting out to sea is a risk (boat rescue with up to 3 boats in peak season). The flat dries out and the reef bottoms out at low tide. There are coral reefs in the shallows and further out, plus mangroves and islands with reefs beyond the bay. Slight shore break in places. Crowded in peak season.', 'Beach/rescue package with safety boat is compulsory. Advanced riders must avoid kite school teaching zones. Riding hours follow the station''s water hours (8:30-17:00).', 'Main launch is the sandy beach at the kite centre (7Bft Kite House) at the northern end of Soma Bay, next to the nautical station in front of the Kempinski. Lat/lon is the geocoded Soma Bay resort point, not the exact launch. Only experienced kiters should launch or land near the nautical station. Beach staff launch and land kites, and the beach/rescue package is compulsory. Ride west for cleaner, sideshore wind. Advanced riders must keep out of the school teaching zones. Station opens 8:00-18:30, water 8:30-17:00.', 'Rideable all year (80-90% wind probability). Most consistent from May/June to October/November, averaging about 22 kn and often 25-30 kn in the afternoon. From April to November no wetsuit is needed; in winter bring a shorty.', 'seed', 'https://locations.thekitespot.com/locations/kitesurf-safaga-soma-bay-egypt|https://www.sportif.travel/destinations/108/Red_Sea/Soma_Bay|https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/7bft-kitehouse-west-shore-red-sea-egypt.html|https://www.iksurfmag.com/?p=19631', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'safaga-soma-bay' AND (SELECT status FROM spots WHERE id = 'safaga-soma-bay') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'safaga-soma-bay', 'NW', 'best', 'Prevailing thermal wind that builds through the morning. At the main beach it blows side-shore to cross-offshore from the right. Water stays flat. Often 2-4 kn more than forecast, and local mountain acceleration adds roughly 5 kn compared with Hurghada.' WHERE (SELECT status FROM spots WHERE id = 'safaga-soma-bay') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'safaga-soma-bay', 'NNW', 'best', 'Same prevailing northerly pattern as NW. Side-shore to cross-offshore, flat water.' WHERE (SELECT status FROM spots WHERE id = 'safaga-soma-bay') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'safaga-soma-bay', 'N', 'ok', 'Part of the prevailing northerly regime. Guides do not describe how it lines up with the beach.' WHERE (SELECT status FROM spots WHERE id = 'safaga-soma-bay') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'safaga-soma-bay', 'WNW', 'marginal', 'Blows more offshore at the main beach. Rely on the rescue boats.' WHERE (SELECT status FROM spots WHERE id = 'safaga-soma-bay') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('el-gouna-mangroovy-beach', 'El Gouna – Mangroovy Beach', 'el gouna|mangroovy beach|buzzha beach|kbc el gouna|el gouna – mangroovy beach', 27.41572, 33.67782, 'Egypt', 'lagoon', 45, 'guide', 'kitesurf|windsurf|wingfoil', 'Better at high tide. The lagoon is waist-deep, and at low tide the rideable deep-water areas shrink. Sharp shells and rock patches are exposed in the shallows.', 'Coral reef about 200 m from shore. Past the reef the water is deep and choppy, with some waves. Sharp shells in the shallows, rock zones near some launch areas, and swimmer zones that are hard to stay upwind of in light wind. Rescue boats only work in deep water outside the reef, not in the shallow lagoon. Busy with schools.', 'Kiting is done through the centres (registration and fee). At KBC: no jumping within 50 m of the beach, keep 50 m clearance when doing tricks or overtaking, stay inside a 600 m safety radius around the station, no kiting on land, and no riding under the influence of alcohol or drugs. Swimmer zones are no-kite areas. Standard right-of-way rules apply.', 'Launch from the wide sandy beaches run by the kite centres (Mangroovy Beach, KBC on Buzzha Beach). The beach charges an entrance or day-use fee, and you must register if you bring your own gear. At KBC the first 50 m are a launch/landing zone only. A beach assistant launches with the rider standing in the water at least one line length out. Lessons run north of the open riding area.', 'Wind blows all year (thermal, force 4-6). Windiest March-September. April-November is warmest (no wetsuit needed).', 'seed', 'https://kitejungle.com/kite-places/egypt/el-gouna-mangroovy-beach|https://www.kiteboarding-club.com/en/el-gouna/safety-while-kitesurfing-at-the-kbc/|https://bytheseatofmyskirt.com/2012/09/08/kitespot-review-el-gouna-egypt/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'el-gouna-mangroovy-beach' AND (SELECT status FROM spots WHERE id = 'el-gouna-mangroovy-beach') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'el-gouna-mangroovy-beach', 'NW', 'best', 'Prevailing direction (stats ~314-351°). Coast runs NW-SE, so it blows cross/cross-on from the left.' WHERE (SELECT status FROM spots WHERE id = 'el-gouna-mangroovy-beach') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'el-gouna-mangroovy-beach', 'NNW', 'best', 'Prevailing direction. Cross-onshore from the left, flat water in the lagoon.' WHERE (SELECT status FROM spots WHERE id = 'el-gouna-mangroovy-beach') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'el-gouna-mangroovy-beach', 'N', 'best', 'Common thermal wind (''north-ish''), cross-onshore.' WHERE (SELECT status FROM spots WHERE id = 'el-gouna-mangroovy-beach') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'el-gouna-mangroovy-beach', 'WNW', 'marginal', 'Becomes side-shore to side-off. Can be gusty close to shore.' WHERE (SELECT status FROM spots WHERE id = 'el-gouna-mangroovy-beach') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'el-gouna-mangroovy-beach', 'W', 'forbidden', 'Westerlies come off the desert and blow offshore at this NE-facing beach.' WHERE (SELECT status FROM spots WHERE id = 'el-gouna-mangroovy-beach') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('vung-tau-back-beach-bai-sau', 'Vung Tau (Back Beach / Bai Sau)', 'bãi sau|back beach|thuy van beach|bãi thùy vân|vũng tàu|vung tau (back beach / bai sau)', 10.35, 107.098, 'Vietnam', 'sea', 130, 'guide', 'kitesurf|windsurf', 'Between mid-low and mid-high tide, flat water forms between the sandbanks at the far end of the beach. To reach the river-mouth spot along the beach you must go and come back at the lowest tide, or rising water can cut you off.', 'Waves break gently on a shallow, gradual beach, so there is little shore break, but onshore days are choppy. At the river mouth: a 30-40 m wide channel before a large sandbank, fishing traps and fishing boats. Swimmers on the city beach, especially at weekends.', '', 'Launch from the wide, shallow sand of Back Beach (Bai Sau, along Thuy Van street), a 14 km beach. Quiet on weekdays (4-5 kiters), 10-12 kiters at weekends. A flatter, windier, less crowded area lies at the far NE end, at the river mouth facing Long Hai. You get there by dirt tracks or by riding a motorbike along the beach at low tide.', 'October/mid-November to April (NE monsoon), with the most reliable wind from December to March. In the summer SW monsoon the local school recommends going elsewhere.', 'seed', 'https://kitesurfinglessonsvietnam.com/en/the-kitespot-vung-tau-vietnam|https://kitesurfinglessonsvietnam.com/en/wind-in-vietnam-wind-directions-at-kite-beach-vung-tau|https://kitesurfinglessonsvietnam.com/en/the-river-vung-tau-kitesurfing-spot|https://www.windfinder.com/spotguide/vung_tau', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'vung-tau-back-beach-bai-sau' AND (SELECT status FROM spots WHERE id = 'vung-tau-back-beach-bai-sau') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'vung-tau-back-beach-bai-sau', 'NE', 'best', 'Northeast monsoon from mid-Nov to Apr blows NE to E daily, about side-shore on Back Beach. Usually 12-25 kn, sometimes up to 30 kn or more.' WHERE (SELECT status FROM spots WHERE id = 'vung-tau-back-beach-bai-sau') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'vung-tau-back-beach-bai-sau', 'ENE', 'best', 'Main dry-season direction. Side to side-on.' WHERE (SELECT status FROM spots WHERE id = 'vung-tau-back-beach-bai-sau') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'vung-tau-back-beach-bai-sau', 'E', 'ok', 'Common in season (ESE is the most frequent direction). Side-onshore: the shore break and incoming waves take some skill.' WHERE (SELECT status FROM spots WHERE id = 'vung-tau-back-beach-bai-sau') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'vung-tau-back-beach-bai-sau', 'ESE', 'ok', 'Side-onshore to onshore. Choppier water.' WHERE (SELECT status FROM spots WHERE id = 'vung-tau-back-beach-bai-sau') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'vung-tau-back-beach-bai-sau', 'SE', 'marginal', 'Straight onshore: rough, messy waves. Local school advises only advanced riders go out.' WHERE (SELECT status FROM spots WHERE id = 'vung-tau-back-beach-bai-sau') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'vung-tau-back-beach-bai-sau', 'W', 'forbidden', 'Offshore from land. Gusty, and getting back to shore is hard.' WHERE (SELECT status FROM spots WHERE id = 'vung-tau-back-beach-bai-sau') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'vung-tau-back-beach-bai-sau', 'NW', 'forbidden', 'Offshore. Do not ride.' WHERE (SELECT status FROM spots WHERE id = 'vung-tau-back-beach-bai-sau') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'vung-tau-back-beach-bai-sau', 'N', 'forbidden', 'Side-offshore to offshore. Gusty and dangerous.' WHERE (SELECT status FROM spots WHERE id = 'vung-tau-back-beach-bai-sau') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('etang-de-leucate-le-goulet-lagoon-side', 'Étang de Leucate – Le Goulet (lagoon side)', 'le goulet|leucate le goulet|étang de leucate / salses-leucate lagoon|wesh center spot|étang de leucate – le goulet (lagoon side)', 42.91346, 3.02, 'France', 'lagoon', 200, 'guide', 'kitesurf|windsurf|wingfoil', 'Mediterranean lagoon with practically no tide. The water level varies with the season: after a hot summer it is low and there can be a lot of seaweed. The bottom is muddy, with algae.', 'Oyster beds and the wooden posts marking them. Stones in the water. Gusty Tramontane up to 30-40 kn, accelerated by a venturi effect; it blows offshore, so there is a drift risk. Very shallow water (falls, fins). Crowded with windsurfers in the north zone. Protected bird area nearby (signposted).', 'Zoning: the northern part of Le Goulet is reserved for windsurfing, and kitesurfing is not allowed there. Designated kite zone further south towards Île de la Rascasse (mostly standing depth). Access to the protected bird area is banned (sign at the entrance). Kite and windsurf zones are separated; supervised in season.', 'Lagoon spot at the far north end of the Étang de Leucate, near Leucate village, by the Wesh Center Crew base (school, rental, bar). Free dirt car park behind the centre, paid motorhome area; it fills up quickly in high season. Shallow water: ankle-deep for about 50 m, then waist- to chest-deep. Approximate beach orientation (sunset view, S-SW): confirm locally. Beginner-friendly.', 'March-April and July-October; Tramontane all year round', 'seed', 'https://www.ultimatefrance.com/?p=5582|https://waterwind.it/new/en/windsurfing/spots/spots-reviews/262-france/369-leucate-le-goulet-france.html|https://www.surf-magazin.de/en/spots-and-areas/international/france/south-of-france-leucate-the-up-and-coming-windsurfing-spot-of-the-month/|https://vvanat.fr/blog/planche-a-voile-port-leucate/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'etang-de-leucate-le-goulet-lagoon-side' AND (SELECT status FROM spots WHERE id = 'etang-de-leucate-le-goulet-lagoon-side') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'etang-de-leucate-le-goulet-lagoon-side', 'NW', 'best', 'Tramontane, the reference wind: blows 200+ days/yr, often F6-9, strong and gusty. Le Goulet is said to be the first spot to get it. Flat water even at F6-7. Guides call it offshore here, so beware of drifting out into the lagoon.' WHERE (SELECT status FROM spots WHERE id = 'etang-de-leucate-le-goulet-lagoon-side') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'etang-de-leucate-le-goulet-lagoon-side', 'NNW', 'ok', 'Tramontane variant. Strong, gusty, offshore-ish; flat water.' WHERE (SELECT status FROM spots WHERE id = 'etang-de-leucate-le-goulet-lagoon-side') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'etang-de-leucate-le-goulet-lagoon-side', 'N', 'ok', 'Listed as a working direction for the lagoon in general (ultimatefrance). No spot-specific detail.' WHERE (SELECT status FROM spots WHERE id = 'etang-de-leucate-le-goulet-lagoon-side') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'etang-de-leucate-le-goulet-lagoon-side', 'W', 'ok', 'Listed as a working direction for the lagoon in general (ultimatefrance). No spot-specific detail.' WHERE (SELECT status FROM spots WHERE id = 'etang-de-leucate-le-goulet-lagoon-side') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'etang-de-leucate-le-goulet-lagoon-side', 'SE', 'ok', 'Marin (onshore sea wind): often moderate, flat water on the lagoon according to local guides.' WHERE (SELECT status FROM spots WHERE id = 'etang-de-leucate-le-goulet-lagoon-side') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('gruissan-etang-de-mateille', 'Gruissan – Étang de Mateille', 'mateille|base nautique de mateille|akila gruissan – pôle étang|gruissan – étang de mateille', 43.11808, 3.11957, 'France', 'lagoon', NULL, 'guide', 'windsurf|wingfoil|sailing|kitesurf', '', 'Very shallow water. Small water area that gets crowded with beginners, school groups, catamarans, paddleboards and kayaks.', '', 'Easy entry from several access points on the shallow lagoon shore. The Akila Gruissan Pôle Étang school (base nautique de Mateille) works here, with a kids'' sailing area. The spot is small and pond-like, with many beginners and school groups, so give learners room.', 'April to mid-October (the school is open about April to early November)', 'seed', 'https://www.tourisme-occitanie.com/akila-nautic-gruissan-pole-etang/gruissan|https://srokacompany.com/en/blogs/news/wingfoil-destination-in-gruissan|https://vvanat.fr/blog/la-planche-a-voile-gruissan/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'gruissan-etang-de-mateille' AND (SELECT status FROM spots WHERE id = 'gruissan-etang-de-mateille') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'gruissan-etang-de-mateille', 'NW', 'marginal', 'Tramontane, the dominant wind (often blows 3–6 days in a row, April–October). On this small lagoon riders describe it as sheltered, gusty and unstable.' WHERE (SELECT status FROM spots WHERE id = 'gruissan-etang-de-mateille') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'gruissan-etang-de-mateille', 'WNW', 'marginal', 'Tramontane sector. Gusty and unstable on the lagoon, same as NW.' WHERE (SELECT status FROM spots WHERE id = 'gruissan-etang-de-mateille') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'gruissan-etang-de-mateille', 'S', 'best', 'Local wing riders call the spot ''legendary'' when the ''grec'' blows. One source describes this wind as southerly, but in Occitan ''grec'' usually means NE, so check the direction locally.' WHERE (SELECT status FROM spots WHERE id = 'gruissan-etang-de-mateille') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('etang-de-thau-pont-levis-sete', 'Étang de Thau – Pont-Levis (Sète)', 'pont levis|pont-levis sète|étang de thau sète|thau lagoon|mèze (le taurus)|étang de thau – pont-levis (sète)', 43.4018, 3.65663, 'France', 'lagoon', 315, 'guide', 'kitesurf|windsurf|wingfoil|sailing', 'Very small Mediterranean tide, but water level changes the width of the sandbank. Between the shore and the sandbank the water is 5–40 cm deep, about 1 m at most.', 'Very shallow water and the sandbank (watch fins and foils). Sea urchins and stinging anemones, so booties are essential. No-go zone around the Sète hospital heliport next to the spot. Oyster/shellfish farming tables in the lagoon. Choppier water in the middle of the lagoon. Crowded in summer and at weekends. Car break-ins reported at the car park.', 'Natura 2000 area with nesting birds. Yellow buoys mark protected quiet zones in summer. Keep away from the second dike during nesting season. Area around the heliport is off limits (signposted). Kitesurf launch etiquette above applies.', 'Main launch is at Aire du Pont-Levis, Sète (free gravel car park, 2.2 m height barrier). From there it is about 800 m along the dike plus a short wade to the sandbank, roughly 15 min with gear. Kiters: only one kite at a time on the sandbank safe zone, priority to riders coming in, no jumping near the launch or the dike, leave bags on the dike. Mèze (Centre Nautique Le Taurus, north shore) is a quieter alternative with schools.', 'All year. September–June is considered best. The summer SW thermal makes July–August usable but crowded.', 'seed', 'https://vvanat.fr/blog/magic-bruce-kitesurf-sete/|https://vvanat.fr/blog/planche-a-voile-etang-de-thau/|https://ultimatefrance.com/kitesurfing/south-france/sete-etang-de-thau|https://en.archipel-thau.com/kite-premium.html', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'etang-de-thau-pont-levis-sete' AND (SELECT status FROM spots WHERE id = 'etang-de-thau-pont-levis-sete') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'etang-de-thau-pont-levis-sete', 'NW', 'best', 'Tramontane, the main wind. Onshore at Pont-Levis. Often strong. Water stays flat behind the sandbank (toc).' WHERE (SELECT status FROM spots WHERE id = 'etang-de-thau-pont-levis-sete') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'etang-de-thau-pont-levis-sete', 'WNW', 'best', 'Part of the main Tramontane/NW range. Onshore to cross-onshore with flat water.' WHERE (SELECT status FROM spots WHERE id = 'etang-de-thau-pont-levis-sete') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'etang-de-thau-pont-levis-sete', 'W', 'ok', 'Works well. One guide calls it the best direction for chop/waves in the open lagoon.' WHERE (SELECT status FROM spots WHERE id = 'etang-de-thau-pont-levis-sete') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'etang-de-thau-pont-levis-sete', 'SW', 'ok', 'Summer thermal (SW). Guides say it works well in summer.' WHERE (SELECT status FROM spots WHERE id = 'etang-de-thau-pont-levis-sete') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'etang-de-thau-pont-levis-sete', 'S', 'ok', 'Summer southerlies are reported as usable. Less favourable than SW–NW according to some guides.' WHERE (SELECT status FROM spots WHERE id = 'etang-de-thau-pont-levis-sete') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'etang-de-thau-pont-levis-sete', 'N', 'ok', 'N/NE (locally called Mistral) is reported to work at Pont-Levis. Maldormir (Marseillan side) is the usual northerly alternative.' WHERE (SELECT status FROM spots WHERE id = 'etang-de-thau-pont-levis-sete') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'etang-de-thau-pont-levis-sete', 'E', 'marginal', 'Less favourable. Strong easterlies are reported as not working well.' WHERE (SELECT status FROM spots WHERE id = 'etang-de-thau-pont-levis-sete') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'etang-de-thau-pont-levis-sete', 'SE', 'forbidden', 'Offshore at the NW-facing launch. A strong SE quickly churns the lagoon and builds sizeable chop. It can also bring algae.' WHERE (SELECT status FROM spots WHERE id = 'etang-de-thau-pont-levis-sete') = 'seed';
INSERT INTO spots (id, name, aliases, lat, lon, country, water, facing_deg, facing_source, sports, tide_notes, hazards, rules, launch_notes, season, status, sources, submissions, kind) VALUES ('almanarre-hyeres-giens-side', 'Almanarre Hyères (Giens side)', 'l''almanarre|plage de l''almanarre|almanarre - zone de kite|route du sel|almanarre hyères (giens side)', 43.053, 6.13, 'France', 'sea', 250, 'guide', 'kitesurf|windsurf|wingfoil', 'Mediterranean, tide is negligible. Water gets deep quickly.', 'Narrow beach that gets crowded. Some rocks to the right of the launch. Water gets deep fast. Close-out shore break in W/SW wind. Strong Mistral gusts. In easterly wind, offshore drift. Frequent car break-ins in the beach car parks.', 'From 15 June to 15 September, the town of Hyères limits kiting to the zone between accesses 16 and 21. Riding inside the 300 m coastal band is forbidden: use the marked channel to get past 300 m. A Beach Marshall is present and the municipal police can fine riders. From April to October, launching is allowed only through the kite channels (Almanarre or Mérou).', 'Launch only from the marked kite zone between beach accesses 16 and 21. The launch strip is about 150 m long and very narrow, with wooden dune fences (ganivelles) behind it and FFVL flag posts in summer. Launching and landing are tight and crowded on good days. Not recommended for beginners.', 'October to April (best). Summer is restricted and crowded.', 'seed', 'https://vvanat.fr/blog/kitesurf-almanarre-spot-carte/|https://www.ultimatefrance.com/kitesurfing/south-france/almanarre|https://web.kite-and-windsurfing-guide.com/spots/kiteboarding-windsurfing-sup/l-almanarre-hyeres-provence-alpes-cote-d-azur-france.html|https://madeinmarseille.net/a-la-une-marseille/14282-meilleur-spot-planche-kitesurf-provence/', 0, 'spot')
  ON CONFLICT(id) DO UPDATE SET aliases = excluded.aliases, country = excluded.country, water = excluded.water, facing_deg = COALESCE(excluded.facing_deg, spots.facing_deg), facing_source = excluded.facing_source, sports = excluded.sports, tide_notes = excluded.tide_notes, hazards = excluded.hazards, rules = excluded.rules, launch_notes = excluded.launch_notes, season = excluded.season, sources = excluded.sources WHERE spots.status = 'seed';
DELETE FROM spot_wind WHERE spot_id = 'almanarre-hyeres-giens-side' AND (SELECT status FROM spots WHERE id = 'almanarre-hyeres-giens-side') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'almanarre-hyeres-giens-side', 'W', 'best', 'Onshore with chop and waves along the whole beach. Reference direction for the spot.' WHERE (SELECT status FROM spots WHERE id = 'almanarre-hyeres-giens-side') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'almanarre-hyeres-giens-side', 'WNW', 'best', 'Mistral, often force 6-9: powerful and gusty, with waves that tend to close out. For experienced riders.' WHERE (SELECT status FROM spots WHERE id = 'almanarre-hyeres-giens-side') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'almanarre-hyeres-giens-side', 'NW', 'ok', 'Mistral sector, side-on. Strong gusts.' WHERE (SELECT status FROM spots WHERE id = 'almanarre-hyeres-giens-side') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'almanarre-hyeres-giens-side', 'WSW', 'best', 'Onshore, waves along the beach.' WHERE (SELECT status FROM spots WHERE id = 'almanarre-hyeres-giens-side') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'almanarre-hyeres-giens-side', 'SW', 'best', 'Libeccio, up to about 20 kn. Onshore with waves.' WHERE (SELECT status FROM spots WHERE id = 'almanarre-hyeres-giens-side') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'almanarre-hyeres-giens-side', 'E', 'forbidden', 'Offshore. Water is glassy but riders drift away from shore quickly. Some guides list it for experts only; the usual advice is to go to La Bergerie on the east side of the peninsula instead.' WHERE (SELECT status FROM spots WHERE id = 'almanarre-hyeres-giens-side') = 'seed';
INSERT OR IGNORE INTO spot_wind (spot_id, sector, quality, note) SELECT 'almanarre-hyeres-giens-side', 'SE', 'marginal', 'Listed by some guides; side-offshore on this beach, so flat water with a drift risk.' WHERE (SELECT status FROM spots WHERE id = 'almanarre-hyeres-giens-side') = 'seed';
